import type { MeaningPack } from '../../types';

export const taHoma: MeaningPack = {
  lang: 'ta',
  texts: {
    'homa-purvanga': {
      summary: "எல்லா ஹோமங்களுக்கும் பொதுவான பகுதிகள், செய்யும் வரிசையில் முழு மந்திரங்களுடன்: ஆசமனம், ப்ராணாயாமம், ஸங்கல்பம், கலசமும் சுருக்கமான புண்யாஹவாசனமும், ஸ்தண்டிலம், அக்னியைக் கொண்டுவந்து ப்ரதிஷ்டை செய்தல், அக்னிமுகம் (மாத்வ: அன்வாதானம், பரிஸ்தரணம், ப்ரஹ்மா, ஆஜ்ய ஸம்ஸ்காரம், இத்மம், ஆகாரம், ஆஜ்யபாகம், அக்னிக்குப் பதினாறு ஸம்ஸ்காரங்கள், புருஷஸூக்தத்துடன் வைஷ்ணவ ஆஹுதிகள்; ஸ்மார்த்த: பரிஸ்தரணம், பாத்ராஸாதனம், பரிதிகள், பரிஷேசனம், இத்மம், ஆகாரம், ஆஜ்யபாகம், அக்னிமுகம்); ஒவ்வொரு ஹோம நூலிலும் உள்ள பிரதான ஆஹுதிகளுக்குப் பின் உத்தராங்கம்: ஸ்விஷ்டக்ருத், ப்ராயச்சித்த ஆஹுதிகள், பூர்ணாஹுதி, ஸம்ஸ்ராவம், மார்ஜனம், அக்னி உபஸ்தானம், ரக்ஷை, ஸமர்ப்பணம் (ஸ்மார்த்தர்களுக்கு ஜயா, அப்யாதான, ராஷ்ட்ரப்ருத் ஆஹுதிகளும்). மேலே மாத்வ அல்லது ஸ்மார்த்த தேர்ந்தெடுக்கவும்.",
      verses: {
        '0.0': "ஆதியில் பிரஜாபதி யஜ்ஞத்துடன் பிரஜைகளைப் படைத்துச் சொன்னார்: இதனால் நீங்கள் வளருங்கள்; இது உங்கள் விருப்பங்களையெல்லாம் தரும் காமதேனுவாகட்டும். (பகவத்கீதை 3.10)",
        '1.0': "தெய்வம், பூதங்கள் அல்லது தன்னாலேயே துன்பங்கள் ஏற்படும்போது, அல்லது ஆயுள், சாந்தி, செல்வம், புண்ய வளர்ச்சிக்காக… (தந்த்ரஸாரஸங்க்ரஹம் 2.13)",
        '1.1': "…தகுதி, மந்திரஸித்தி அல்லது வெறும் விஷ்ணுப்ரீதிக்காக, முன் சொன்னபடி ஸம்ஸ்கரித்த அக்னியில் ஜனார்த்தன தேவனைத் த்யானித்து ஆயிரம், பத்தாயிரம், இலட்சம் அல்லது கோடி ஆஹுதிகள் ஹோமம் செய்ய வேண்டும். (தந்த்ரஸாரஸங்க்ரஹம் 2.14)",
        '2.0': "எல்லா விக்னங்களும் அடங்க, வெண்ணாடை அணிந்த, நிலவு நிறமுடைய, நான்கு தோள்களுடைய, மலர்ந்த முகமுடைய, எங்கும் நிறைந்தவரைத் த்யானிக்க வேண்டும்.",
        '2.1': "கேசவனுக்கு, நாராயணனுக்கு, மாதவனுக்கு அர்ப்பணம்: இறைவனின் இந்த ஒவ்வொரு நாமத்துடனும் ஒரு மிடறு நீர் ஆசமனம் செய்யப்படுகிறது.",
        '2.2': "கோவிந்தன், விஷ்ணு முதல் ஹரி, ஸ்ரீகிருஷ்ணன் வரையிலான இறைவனின் புனித நாமங்களால் நமஸ்காரம்; ஒவ்வொன்றுடனும் தொடப்படும் உடற்பகுதியில் இறைவன் இருப்பதாக நினைக்கப்படுகிறான்.",
        '2.3': "ஓம் ஏழு உலகங்கள் ஒவ்வொன்றுடனும் — பூ: முதல் ஸத்யம் வரை — நினைக்கப்படுகிறது. நம் மனங்களைத் தூண்டும் தெய்வ ஸவிதாவின் போற்றத்தக்க ஒளியைத் தியானிக்கிறோம். ஓம் — அவனே நீர், ஒளி, ரஸம், அமுதம், பிரம்மம்; பூமி, அந்தரிக்ஷம், ஸ்வர்க்கம் அனைத்தையும் நிறைப்பவன்.",
        '2.4': "இந்த நல்ல மங்கல வேளையில், இன்று, விஷ்ணுவின் ஆணையால் நடக்கும் யுகத்தில் — பிரம்மாவின் ஆயுளின் இரண்டாம் பாதி, ச்வேதவராஹ கல்பம், வைவஸ்வத மன்வந்தரம், இருபத்தெட்டாம் கலியுகத்தின் முதல் பாதம் — பாரதவர்ஷத்தில், கோதாவரிக்குத் தெற்கே தண்டகாரண்யத்தில், சாலிவாஹன சகாப்தத்தில், நடப்பு ஆண்டு, அயனம், ருது, மாதம், பக்ஷம், திதி, வாரம், நட்சத்திரம் ஆகியவற்றில், இத்தகைய இந்தப் புண்ணிய நாளில்…",
        '3.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியான, பாரதீரமண முக்யப்ராணாந்தர்கதரான ஹரிணீபதி (லக்ஷ்மீபதி) ஸ்ரீபரசுராமரின் ப்ரேரணையால், அவர் ப்ரீதிக்காக, இந்த ஹோமம் என்னும் கர்மத்தைச் செய்கிறேன்; அதன் அங்கமாக ஸ்தண்டிலத்தை மெழுகி, கோடுகள் வரைந்து அக்னிப் பிரதிஷ்டை செய்கிறேன்.",
        '4.0': "என் சேர்ந்த எல்லாப் பாவங்களும் அழிவதன் மூலம் பரமேஸ்வரனின் ப்ரீதிக்காக, இப்பலன் கைகூட இந்த ஹோமத்தைச் செய்கிறேன்; அதன் அங்கமாக ஸ்தண்டிலத்தில் கோடுகள் வரைந்து அக்னிப் பிரதிஷ்டை செய்கிறேன்.",
        '5.0': "கலசத்தின் வாயில் விஷ்ணுவும், கழுத்தில் ருத்திரனும் உறைகின்றனர்; அடியில் பிரம்மா நிற்கிறார்; நடுவில் மாத்ருகணங்கள் உள்ளனர் என்பர்.",
        '5.1': "கலசத்தின் வயிற்றில் எல்லாக் கடல்களும் ஏழு தீவுகளுடைய பூமியும் உள்ளன; ரிக், யஜுர், ஸாம, அதர்வ வேதங்கள் அங்கங்களுடன் கலசத்தை அடைக்கலமாகக் கொண்டுள்ளன. இங்கே காயத்ரீ, ஸாவித்ரீ, அமைதியும் வளமும் தரும் சக்திகளும் உள்ளன.",
        '5.2': "பாவத்தை அழிக்கும் எல்லாக் கடல்களும், ஆறுகளும், தீர்த்தங்களும், மேகங்களும், நதிகளும் இறைவனின் பூஜைக்காக இங்கே வரட்டும்.",
        '5.3': "கங்கையே, யமுனையே, கோதாவரியே, ஸரஸ்வதியே, நர்மதையே, ஸிந்துவே, காவேரியே, இந்நீரில் ஸந்நிதி கொள்வீர்.",
        '5.4': "ஓ வருணா, என் இந்த அழைப்பைக் கேள், இன்று எங்களுக்கு அருள்செய்; உன் பாதுகாப்பை விரும்பி உன்னை அழைக்கிறேன். (ரிக்வேதம் 1.25.19; கலசத்தில் வருண ஆவாஹனம்)",
        '5.5': "இந்த யஜமானனுக்கு புண்யாஹம் என்று நீங்கள் சொல்லுங்கள் — “ஓம் புண்யாஹம்”; ஸ்வஸ்தி சொல்லுங்கள் — “ஓம் ஸ்வஸ்தி”; ருத்தி சொல்லுங்கள் — “ஓம் ருத்திரஸ்து.” (ஒவ்வொரு அழைப்பும் மூன்று முறை)",
        '5.6': "தூய்மையானவனாயினும் தூய்மையற்றவனாயினும், எந்த நிலையிலிருந்தாலும், தாமரைக்கண்ணனான இறைவனை நினைப்பவன் உள்ளும் புறமும் தூயவன் ஆகிறான். (கலச நீரைத் தெளிக்கும்போது)",
        '6.0': "பிரம்மா, விஷ்ணு, ருத்ரன், உமா, லக்ஷ்மி, ஸரஸ்வதி — ஸ்தண்டிலத்தில் கோடுகள் வரையும் வரிசையில் இவர்களே ஆறு கோடுகளின் தேவதைகள் எனப்படுகிறார்கள்.",
        '7.0': "கிழக்கு நோக்கி மூன்றும் வடக்கு நோக்கி மூன்றுமாகக் கோடுகள் வரைந்து, நீரால் ப்ரோக்ஷித்து… (அக்னியின் இடத்தைக் குறிக்கும் ஆபஸ்தம்ப விதி)",
        '8.0': "தன்னுள் ஹரியையும் குண்டத்தில் ஸ்ரீதேவியையும் த்யானித்து, விஷ்ணுவின் வீர்யமான அக்னியைப் ப்ரணவத்துடன் வைக்க வேண்டும். (தந்த்ரஸாரஸங்க்ரஹம் 2.18)",
        '8.1': "மஞ்சள் பட்டு உடுத்தியவள், தாமரைக் கண்ணாள், தாமரைக் கரங்களில் இரு தாமரைகளையும் அபய வரங்களையும் ஏந்தியவள், நூறு உதய சூரியர்களைப் போல் ஒளிர்பவள், பரமனின் மடியில் அமர்ந்தவள், பிரம்மனும் ஈசனும் போற்றும் திருவடிகள் உடைய ஜகன்மாதாவை தியானிக்க வேண்டும். (குண்டத்தில் லக்ஷ்மீ தியானம்.)",
        '8.2': "ஓம், ஆயிரம் ஆரங்கள் கொண்ட (சக்கரமே), ஹும் பட். (ஸுதர்சனரின் அஸ்த்ர மந்திரம்; அக்னியின் க்ரவ்யாத பாகத்தை தென்மேற்கில் எறியும்போது.)",
        '8.3': "வீட்டின் அன்பான நண்பா, விருந்தினனே, அறிவாளியான அக்னியே, எங்கள் இந்த யஜ்ஞத்திற்கு வா; தாக்குபவர்களை அழித்து எதிரிகளின் போகங்களை எங்களுக்குக் கொண்டுவா. (ரிக்வேதம் 5.4.5)",
        '8.4': "ஓ அக்னியே, வா, இங்கே ஹோதாவாக அமர்; தடையின்றி எங்கள் முன்னோடியாக இரு; எங்கும் நிறைந்த த்யாவாப்ருதிவிகள் உன்னைக் காக்கட்டும்; எங்கள் நல்லெண்ணத்திற்காக தேவர்களை யஜி. (ரிக்வேதம் 1.76.2; இவ்விரு மந்திரங்களால் அக்ஷதை இட்டு அக்னியை ஆவாஹனம் செய்வர்)",
        '8.5': "ஓம் பூர்ப்புவஸ்ஸுவ — விஷ்ணுவின் வீர்யமான, இக்கர்மத்துக்குரிய பெயருடைய அக்னியைப் பிரதிஷ்டை செய்கிறேன்.",
        '9.0': "அவர் மனத்திலிருந்து சந்திரன் பிறந்தான், கண்ணிலிருந்து சூரியன்; வாயிலிருந்து இந்திரனும் அக்னியும், பிராணனிலிருந்து வாயு பிறந்தனர். (புருஷஸூக்தம், தைத்திரீய ஆரண்யகம் 3.12)",
        '9.1': "ஓம் பூர்ப்புவஸ்ஸுவ — இக்கர்மத்துக்குரிய பெயருடைய அக்னியைப் பிரதிஷ்டை செய்கிறேன்.",
        '10.0': "அவனுக்கு நான்கு கொம்புகள், மூன்று பாதங்கள், இரண்டு தலைகள், ஏழு கைகள்; மூன்று விதமாகக் கட்டுண்ட எருது முழங்குகிறது; அம்மஹாதேவன் மனிதர்களுள் புகுந்துள்ளான். (ரிக்வேதம் 4.58.3)",
        '10.1': "இந்த தேவனே எல்லாத் திசைகளிலும் வியாபித்துள்ளான்; முதலில் பிறந்தவன், கர்ப்பத்தின் உள்ளேயும் இருப்பவன்; பிறக்கிறவனும் பிறக்கப்போகிறவனும் அவனே; எல்லாப் பக்கமும் முகமுடையவனாய் எல்லா உயிர்களின் முன் நிற்கிறான்.",
        '11.0': "உதிக்கும் சூரியர்களின் தொகுதி போல ஒளிரும், அச்யுதனின் மடியில் நன்கு அமர்ந்த, எப்போதும் அவர் துதியிலேயே வாக்கு ஈடுபட்ட, கதையும் அபயமும் ஏந்திய, அஞ்சலி செய்த, விரும்பிய உருவம் ஏற்கவல்ல, பெருங்கர்மசக்தி கொண்ட பிராணதேவரைத் த்யானிக்க வேண்டும். (தந்த்ரஸாரஸங்க்ரஹம் 4.69)",
        '11.1': "நெருப்புக் கங்கு நிறமுடைய, தன் ஒளியால் அண்டத்தின் உள்ளும் புறமும் நிறைந்த, கோடரியும் வில்லும் ஏந்திய ஒப்பற்ற வீரர், பிரம்மா–ருத்ர–இந்திராதியரால் துதிக்கப்பட்டு உயிர்களுக்கு அவற்றின் ஸ்வரூபப் பதவியை அருள்பவரான பரசுராமரைத் த்யானிக்க வேண்டும். (தந்த்ரஸாரஸங்க்ரஹம் 4.35)",
        '11.2': "ஓ சாண்டில்ய கோத்ர, மேஷத்வஜ வைஸ்வாநர அக்னியே, கிழக்கு நோக்கிய தேவா; அக்னியிலும் முக்யப்ராணனிலும் உள்ள ஹரிணீபதி பரசுராமா, மேற்கு நோக்கியவனாய் எனக்கு எதிர்முகமாய், வரமளிப்பவனாய், மிக்க அருள்மலர்ந்தவனாய் இரு.",
        '11.3': "இப்போது வைத்த இந்த அக்னியில் நான் யஜிப்பேன்: ஜாதவேத அக்னியை இத்மத்தால்; இரு ஆகாரங்களால் ப்ரஜாபதியை; கண்களான அக்னீஷோமர்களை நெய்யால்; அக்னியை வைஷ்ணவமாக்க மூலமந்திரத்தால் நாராயணனை எட்டு முறை, த்வாதசாக்ஷரத்தால் வாஸுதேவனை பன்னிரண்டு முறை, புருஷஸூக்தத்தின் ஒவ்வொரு ருக்காலும் ஒருமுறை மஹாபுருஷனை, விஷ்ணு ஷடக்ஷரத்தால் விஷ்ணுவை ஆறு முறை நெய்யால்; இங்கு பிரதானமாக இந்த ஹோம தேவதையை அதன் எண்ணிக்கை, த்ரவ்யத்துடன்; மீதியால் ஸ்விஷ்டக்ருத்தை; இத்மம் கட்டிய கயிற்றால் ருத்ரனை; அயஸ் அக்னி, தேவர்கள், விஷ்ணு, அக்னி, வாயு, ஸூர்யன், ப்ரஜாபதி என்ற ப்ராயச்சித்த தேவதைகளை நெய்யால்; அறிந்தும் அறியாமலும் செய்த தோஷங்கள் நீங்க அக்னியை மூன்று முறை, மருத்துகளை நெய்யால்; விச்வேதேவர்களை ஸம்ஸ்ராவத்தால். எல்லா அங்க தேவதைகளும் பிரதான தேவதைகளும் ஸந்நிதியில் இருக்கட்டும்; இவ்வாறு அங்கங்களுடன் கூடிய கர்மத்தால் இப்போதே யஜிப்பேன். (அன்வாதானம்)",
        '11.4': "ஓம் பூர்ப்புவஸ்ஸுவ ஸ்வாஹா — இது பிரஜாபதிக்கும் அவருள் உள்ள ஸ்ரீவாஸுதேவனுக்கும், என்னுடையதன்று. (அன்வாதானத்தில் இரு ஸமித்துகளுடன்)",
        '12.0': "ஓ கிழக்கு நோக்கிய தேவனே அக்னியே, எனக்கு எதிர்முகமாய் இரு.",
        '13.0': "இக்கர்மத்தில் உங்களை பிரம்மாவாக (யஜ்ஞ மேற்பார்வையாளராக) வரிக்கிறேன்.",
        '13.1': "பராவஸு (தீங்கு செய்பவன்) விரட்டப்பட்டான். அர்வாவஸுவின் (நன்மை செய்பவன்) இருக்கையில் நான் அமர்கிறேன். (ப்ரஹ்மா தன் ஆசனத்திலிருந்து ஒரு தர்ப்பையை தென்மேற்கில் எறிந்து அமரும்போது.)",
        '13.2': "வருணனுக்கு நமஸ்காரம்; எல்லா உபசாரங்களாலும் நன்கு பூஜிக்கப்படட்டும் (ப்ரணீதா நீரில் அக்ஷதை இட்டு). ப்ரஹ்மாவுக்கு நமஸ்காரம்; எல்லா உபசாரங்களாலும் பூஜிக்கப்படட்டும் (ப்ரஹ்மா அல்லது கூர்ச்சத்துக்கு).",
        '14.0': "ஸவிதாவின் தூண்டுதலால், குறையற்ற இந்தப் பவித்ரத்தால், ஒளிரும் சூரியனின் கிரணங்களால் உன்னைத் தூய்மைப்படுத்துகிறேன். (ஆஸ்வலாயன க்ருஹ்யஸூத்ரம் 1.3.3; பவித்ரத்தால் நெய்யை எடுக்கும்போது)",
        '14.1': "ஓ ஜாதவேதனே, படகால் ஆற்றைக் கடத்துவது போல எல்லாத் துன்பங்களையும் பாவங்களையும் கடக்கச்செய். ஓ அத்ரியைப் போல நமஸ்காரத்தால் துதிக்கப்படும் அக்னியே, எங்கள் உடல்களின் காவலனாய் விழிப்பாய் இரு. (ரிக்வேதம் 5.4.9)",
        '14.2': "மனிதனான நான் துதிக்கும் உள்ளத்தால் உன்னை நினைத்து அமரனான உன்னைத் திரும்பத் திரும்ப அழைக்கிறேன்: ஓ ஜாதவேதனே, எங்களுக்குப் புகழைத் தா; ஓ அக்னியே, சந்ததியின் மூலம் நான் அமரத்துவம் அடையட்டும். (ரிக்வேதம் 5.4.10)",
        '14.3': "ஜாதவேத அக்னியே, எந்த நற்செயலாளனுக்கு நீ இனிய உலகைச் செய்கிறாயோ அவன் குதிரைகள், புதல்வர்கள், வீரர்கள், பசுக்கள் நிறைந்த செல்வத்தையும் நலத்தையும் அடைகிறான். (ருக்வேதம் 5.4.11)",
        '15.0': "ஓ அதிதியே, அனுமதி தா; ஓ அனுமதியே, அனுமதி தா; ஓ ஸரஸ்வதியே, அனுமதி தா; ஓ தேவ ஸவிதாவே, (இக்கர்மத்துக்கு) எங்களைத் தூண்டு.",
        '16.0': "ஓ ஜாதவேதனே, இந்த இத்மம் உன் ஆத்மா; இதனால் ஒளிர், வளர், ஒளிர்ந்து எங்களையும் வளர்; சந்ததி, பசுக்கள், பிரம்மவர்ச்சஸ், அன்னம் இவற்றால் எங்களைச் செழிக்கச்செய், ஸ்வாஹா. இது ஜாதவேத அக்னிக்கு, என்னுடையதன்று. (ஆஸ்வலாயன க்ருஹ்யஸூத்ரம் 1.10.12)",
        '17.0': "ப்ரஹ்மாவே, இந்த … ஹோமகர்மத்தில் இத்மத்தை வைப்பேன். (ப்ரஹ்மா “ஓம் ஆதத்ஸ்வ — வை” என்கிறார்.)",
        '18.0': "பிரஜாபதிக்கு ஸ்வாஹா; இது பிரஜாபதிக்கு, என்னுடையதன்று. (இரு நெய்த்தாரைகளுடனும் மனத்தில்)",
        '18.1': "பிரஜாபதிக்கு ஸ்வாஹா; இது பிரஜாபதிக்கு, என்னுடையதன்று. இந்திரனுக்கு ஸ்வாஹா; இது இந்திரனுக்கு, என்னுடையதன்று. (இரு நெய்த்தாரைகள், மந்திரம் மனத்தில்)",
        '18.2': "அக்னிக்கு ஸ்வாஹா; இது அக்னிக்கு, என்னுடையதன்று. ஸோமனுக்கு ஸ்வாஹா; இது ஸோமனுக்கு, என்னுடையதன்று. (இரு ஆஜ்யபாக ஆஹுதிகள்)",
        '18.3': "அக்னிக்கு ஸ்வாஹா; இது அக்னிக்கு, என்னுடையதல்ல. (அக்னியின் நடுவில் அக்னிமுக ஆஹுதி, ஸ்மார்த்த.)",
        '18.4': "ஸங்கல்பம் முதல் இந்தக் கணம் வரை நடுவில் நேர்ந்திருக்கக்கூடிய எல்லா தோஷங்களுக்கும் பிராயச்சித்தமாக ஸர்வப்ராயச்சித்த ஹோமம் செய்வேன். ஓம் பூர்புவஸ்ஸுவ: ஸ்வாஹா; இது ப்ரஜாபதிக்கு, என்னுடையதல்ல.",
        '19.0': "ஸங்கல்பம் முதல் இந்த நொடி வரை நடுவில் ஏற்பட்ட எந்தக் குறைக்கும் ப்ராயச்சித்தமாக: ஓம் பூர்ப்புவஸ்ஸுவ ஸ்வாஹா; இது பிரஜாபதிக்கும் அவருள் உள்ள ஸ்ரீவாஸுதேவனுக்கும், என்னுடையதன்று.",
        '19.1': "அக்னியின் பதினாறு ஸம்ஸ்காரங்களுக்காக வ்யாஹ்ருதி ஹோமம் செய்கிறேன். அக்னி வைஷ்ணவமாக ஆக, மூலமந்திரத்தால் நாராயணனை எட்டு முறையும், துவாதசாக்ஷரத்தால் வாஸுதேவனை பன்னிரண்டு முறையும், புருஷஸூக்தத்தின் ஒவ்வொரு ரிக்கால் மஹாபுருஷனையும், விஷ்ணு ஷடக்ஷரத்தால் விஷ்ணுவை ஆறு முறையும் நெய்யால் யஜிக்கிறேன்.",
        '19.2': "அக்னியின் கர்ப்பாதான ஸம்ஸ்காரத்துக்காக: ஓம் பூர்புவ: ஸ்வ: ஸ்வாஹா; இது ப்ரஜாபதிக்கும் அவருள் உள்ள ஸ்ரீ வாஸுதேவனுக்கும், என்னுடையதல்ல. (பும்ஸவனம், ஸீமந்தோந்நயனம், வைஷ்ணவபலி, ஜாதகர்மம், நாமகரணம், நிஷ்க்ரமணம், அன்னப்ராசனம், சௌளம், உபநயனம், மஹாநாம்னீ, மஹாவ்ரதம், உபநிஷத்வ்ரதம், கோதானம், ஸமாவர்த்தனம், விவாஹம் — வரிசையாகப் பெயர் சொல்லி மீண்டும் செய்க; மொத்தம் பதினாறு.)",
        '19.3': "ஓம் நாராயணனுக்கு நமஸ்காரம், ஸ்வாஹா; இது நாராயணனுக்கு, என்னுடையதல்ல. (அஷ்டாக்ஷர மூலமந்திரம்: எட்டு நெய் ஆஹுதிகள்.)",
        '19.4': "ஓம் பகவான் வாஸுதேவனுக்கு நமஸ்காரம், ஸ்வாஹா; இது வாஸுதேவனுக்கு, என்னுடையதல்ல. (த்வாதசாக்ஷர மந்திரம்: பன்னிரண்டு ஆஹுதிகள்.)",
        '20.0': "பரமபுருஷன் ஆயிரம் தலைகளும் ஆயிரம் கண்களும் ஆயிரம் பாதங்களும் உடையவன். பூமியை எப்புறமும் நிறைத்து, அதற்குப் பத்து விரல் அளவு — அதாவது எல்லா அளவுக்கும் — அப்பால் நிற்கிறான். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.1)",
        '20.1': "இவை அனைத்தும் புருஷனே: இருந்தவையும் இனி இருக்கப்போவனவும். அவனே அமரத்துவத்தின் தலைவன்; உணவால் வளர்வன அனைத்துக்கும் மேலாக உயர்ந்தவன். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.2)",
        '20.2': "இதுவே அவன் மகிமை, ஆயினும் புருஷன் அதனினும் பெரியவன். எல்லா உயிர்களும் அவனுடைய ஒரு கால் பங்கே; அவனுடைய முக்கால் பங்கு மேலான வானில் அமரத்துவமாக உள்ளது. ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.3)",
        '20.3': "முக்கால் பங்கால் புருஷன் மேலே உயர்ந்தான்; ஒரு கால் பங்கு உலகமாக மீண்டும் மீண்டும் இங்கே தோன்றுகிறது. அதிலிருந்து உண்பன, உண்ணாதன அனைத்திலும் எங்கும் பரவினான். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.4)",
        '20.4': "அவனிடமிருந்து விராட் எனும் பிரபஞ்ச வடிவம் பிறந்தது; விராட்டுக்குள் புருஷன் உறைந்தான். வெளிப்பட்டதும் அதற்கு அப்பாலும் விரிந்து, பின் பூமியையும் உயிர்களின் உடல்களையும் தோற்றுவித்தான். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.5)",
        '20.5': "புருஷனையே ஹவிஸாகக் கொண்டு தேவர்கள் யாகம் செய்தபோது, வசந்தம் அதன் நெய், கோடை அதன் விறகு, சரத்காலம் அதன் ஹவிஸ். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.6)",
        '20.6': "அனைத்துக்கும் முன் பிறந்த அப்புருஷனை யாகமாகவே தர்ப்பையின் மீது பிரோக்ஷணம் செய்தனர். அவனாலேயே தேவர்களும் ஸாத்யர்களும் ரிஷிகளும் வழிபட்டனர். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.7)",
        '20.7': "அனைத்தும் அர்ப்பணிக்கப்பட்ட அந்த யாகத்திலிருந்து தயிர் கலந்த நெய் சேர்க்கப்பட்டது. அதிலிருந்து வான்வெளி உயிர்களையும், காட்டு விலங்குகளையும், ஊர் விலங்குகளையும் படைத்தான். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.8)",
        '20.8': "அனைத்தும் அர்ப்பணிக்கப்பட்ட அந்த யாகத்திலிருந்து ரிக் மந்திரங்களும் ஸாம கானங்களும் பிறந்தன; அதிலிருந்து சந்தஸ்கள் பிறந்தன; அதிலிருந்து யஜுஸ் தோன்றியது. ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.9)",
        '20.9': "அதிலிருந்து குதிரைகளும் இரு தாடைகளிலும் பற்களுடைய எல்லா விலங்குகளும் பிறந்தன. அதிலிருந்து பசுக்கள் பிறந்தன; அதிலிருந்து ஆடுகளும் செம்மறிகளும் பிறந்தன. ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.10)",
        '20.10': "புருஷனைக் கண்டுணர்ந்தபோது அவனை எத்தனை விதமாகக் கற்பித்தனர்? அவன் வாய் எது, கரங்கள் எவை, தொடைகளும் பாதங்களும் எவை எனப்படுகின்றன? ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.11)",
        '20.11': "அந்தணன் அவன் வாயானான், க்ஷத்ரியன் அவன் கரங்களாக்கப்பட்டான், வைசியன் அவன் தொடைகளானான், அவன் பாதங்களிலிருந்து சூத்திரன் பிறந்தான். இவ்வாறு ஒரே உடலின் அங்கங்கள் போல் சமூகத்தின் எல்லாப் பிரிவுகளும் ஒரே இறைவனிடமிருந்து தோன்றுகின்றன. ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.12)",
        '20.12': "அவன் மனத்திலிருந்து சந்திரன் பிறந்தான், கண்களிலிருந்து சூரியன்; வாயிலிருந்து இந்திரனும் அக்னியும், மூச்சிலிருந்து வாயுவும் தோன்றினர். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.13)",
        '20.13': "நாபியிலிருந்து அந்தரிக்ஷம் தோன்றியது, தலையிலிருந்து வானம் உருவானது; பாதங்களிலிருந்து பூமி, காதுகளிலிருந்து திசைகள். இவ்வாறு உலகங்கள் அமைக்கப்பட்டன. ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.14)",
        '20.14': "தேவர்கள் அந்த யாகத்தை விரித்துப் புருஷனையே பலியாகக் கட்டியபோது, அதற்கு ஏழு பரிதிகளும் மூவேழு ஸமித்துகளும் இருந்தன. ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.15)",
        '20.15': "யாகமே வடிவான இறைவனைத் தேவர்கள் யாகத்தால் வழிபட்டனர்; இவையே தர்மங்களில் முதலானவை. அம்மகான்கள் பழைய ஸாத்யர்களும் தேவர்களும் உறையும் மேலான வானை அடைகின்றனர். ஸ்வாஹா; இது மஹாபுருஷனுக்கு, என்னுடையதல்ல. (ருக்வேதம் 10.90.16)",
        '20.16': "ஓம் விஷ்ணுவுக்கு நமஸ்காரம், ஸ்வாஹா; இது விஷ்ணுவுக்கு, என்னுடையதல்ல. (விஷ்ணு ஷடக்ஷர மந்திரம், பாகவதம் 6.8.10: ஆறு ஆஹுதிகள்.)",
        '21.0': "ஓம் பூஃ ஸ்வாஹா — அக்னிக்கு, என்னுடையதன்று. ஓம் புவஃ ஸ்வாஹா — வாயுவுக்கு, என்னுடையதன்று. ஓம் ஸுவஃ ஸ்வாஹா — சூரியனுக்கு, என்னுடையதன்று. ஓம் பூர்ப்புவஸ்ஸுவ ஸ்வாஹா — பிரஜாபதிக்கு, என்னுடையதன்று.",
        '22.0': "இப்போது முக்கிய ஹோமம். (உங்கள் ஹோம பாடத்தில் தரப்பட்ட ஆஹுதிகளைச் செய்யுங்கள்.)",
        '22.1': "நெய்யால், அல்லது பாயஸத்தால், அல்லது பால்மர ஸமித்துகளால், அல்லது எள்ளால், அல்லது அரிசியால், அல்லது மூன்று இனிப்புகளால் (பால், நெய், தேன்) ஹோமம் செய்ய வேண்டும்; அல்லது அரச ஸமித்துகளால், அல்லது அம்ருதா (சீந்தில்) ஸமித்துகளால்; அம்ருதா ஸமித்துகள் எங்கும் நான்கு அங்குலம். (தந்த்ரஸாரஸங்க்ரஹம் 2.20-21)",
        '23.0': "இக்கர்மத்தில் நான் மிகுதியாகச் செய்தாலும் குறைவாகச் செய்தாலும், அதை அறிந்த ஸ்விஷ்டக்ருத் அக்னி அனைத்தையும் எனக்கு நன்கு யஜிக்கப்பட்டதாகவும் நன்கு ஹோமம் செய்யப்பட்டதாகவும் ஆக்கட்டும். ஆஹுதியை நன்கு ஹோமமாக்குபவரும், எல்லா ப்ராயச்சித்த ஆஹுதிகளையும் விருப்பங்களையும் நிறைவேற்றுபவருமான ஸ்விஷ்டக்ருத் அக்னியே: எங்கள் எல்லா விருப்பங்களையும் நிறைவேற்று, ஸ்வாஹா. இது ஸ்விஷ்டக்ருத் அக்னிக்கு, என்னுடையதன்று. (ஆஸ்வலாயன க்ருஹ்யஸூத்ரம் 1.10.23)",
        '24.0': "பசுபதியான ருத்ரனுக்கு ஸ்வாஹா. இது ருத்ரனுள் உள்ள பாரதீரமண முக்யப்ராணாந்தர்கதரான ஸ்ரீஸங்கர்ஷணனுக்கு, என்னுடையதன்று.",
        '24.1': "அக்னியே, நீ எங்களை நோக்கிச் செல்பவன், பழியற்றவன்; உண்மையில் நீ “அயஸ்”. வேகமாகச் சென்று ஹவிஸைச் சுமந்து செல்கிறாய்; எங்களுக்கு மருந்தைத் தா, ஸ்வாஹா. இது அயஸ் அக்னிக்கு, என்னுடையதல்ல. (ஆச்வலாயன ச்ரௌதஸூத்ரம் 1.11.13)",
        '24.2': "விஷ்ணு எங்கிருந்து பூமியின் ஏழு தாமங்கள் வழியாக அடி வைத்தாரோ அங்கிருந்து தேவர்கள் எங்களைக் காக்கட்டும், ஸ்வாஹா. இது தேவர்களுக்கு, என்னுடையதன்று. (ரிக்வேதம் 1.22.16)",
        '24.3': "விஷ்ணு இந்த உலகை அளந்தார்; மூன்று முறை அடி வைத்தார்; அனைத்தும் அவர் புழுதி படிந்த அடிச்சுவட்டில் அடங்கியுள்ளது, ஸ்வாஹா. இது விஷ்ணுவுக்கு, என்னுடையதன்று. (ரிக்வேதம் 1.22.17)",
        '24.4': "ஓம் பூஃ ஸ்வாஹா — அக்னிக்கும் அவருள் உள்ள ஸ்ரீஅனிருத்தனுக்கும். ஓம் புவஃ ஸ்வாஹா — வாயுவுக்கும் ஸ்ரீப்ரத்யும்னனுக்கும். ஓம் ஸ்வஃ ஸ்வாஹா — சூரியனுக்கும் ஸ்ரீஸங்கர்ஷணனுக்கும். ஓம் பூர்ப்புவஸ்ஸ்வஃ ஸ்வாஹா — பிரஜாபதிக்கும் ஸ்ரீவாஸுதேவனுக்கும். எதுவும் என்னுடையதன்று.",
        '25.0': "யஜ்ஞத்தில் அறியாமலோ அறிந்தோ தவறாகச் செய்ததை, ஓ அக்னியே, சரிசெய்; அது உள்ளவாறு உனக்கே தெரியும், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று.",
        '25.1': "யஜ்ஞம் புருஷனுக்குச் சமம், புருஷன் யஜ்ஞத்துக்குச் சமம்; ஓ அக்னியே, இதைச் சரிசெய், உள்ளவாறு உனக்கே தெரியும், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று.",
        '25.2': "எளிய மனமும் குறைந்த திறனும் உள்ள மனிதர்கள் யஜ்ஞத்தில் எதை அறிவதில்லையோ, அதைக் கர்மம் அறிந்த ஹோதா அக்னி அறிந்து, சிறந்த யாஜகனாகத் தக்க காலத்தில் தேவர்களுக்கு அர்ப்பணிக்கிறான், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று. (ரிக்வேதம் 10.2.5)",
        '25.3': "தேவர்களே, உங்களுக்கு நான் செய்த குறையும், சொல்லாலும் நோக்கத்தாலும் தேவர்களுக்குச் செய்த பிழையும் — எங்களுக்குத் தீங்கு நினைக்கும் கருமியின் பக்கம், எங்களிடமிருந்து விலகி, அந்தக் குற்றத்தை வையுங்கள், மருத்துகளே, ஸ்வாஹா. இது மருத் தேவர்களுக்கு, என்னுடையதல்ல. (ஆச்வலாயன ச்ரௌதஸூத்ரம் 3.13.18)",
        '25.4': "எல்லாவற்றின் பிராயச்சித்தத்துக்காக: ஓம் பூர்புவ: ஸ்வ: ஸ்வாஹா; இது ப்ரஜாபதிக்கும் அவருள் உள்ள ஸ்ரீ வாஸுதேவனுக்கும், என்னுடையதல்ல.",
        '26.0': "கடலிலிருந்து இனிய அலை எழுந்துள்ளது; ஸோமத்துடன் அது அமரத்துவத்தை அடைந்தது. அது நெய்யின் ரகசியப் பெயர், தேவர்களின் நாக்கு, அமுதத்தின் நாபி.",
        '26.1': "நெய்யின் பெயரை நாம் அறிவிப்போம், இந்த யஜ்ஞத்தில் நமஸ்காரங்களுடன் அதைத் தாங்குவோம். துதிக்கப்படுவதை பிரம்மா கேட்கட்டும்; நான்கு கொம்புகளுடைய ஒளிமயன் இதை வெளிப்படுத்தினான்.",
        '26.2': "அவனுக்கு நான்கு கொம்புகள், மூன்று பாதங்கள், இரண்டு தலைகள், ஏழு கைகள்; மூன்று விதமாகக் கட்டுண்ட எருது முழங்குகிறது; அம்மஹாதேவன் மனிதர்களுள் புகுந்துள்ளான். (ரிக்வேதம் 4.58.3)",
        '26.3': "மூன்று விதமாக வைக்கப்பட்ட, பணிகள் பசுவில் மறைத்த நெய்யை தேவர்கள் கண்டுபிடித்தனர். ஒன்றை இந்திரன், ஒன்றை சூரியன் உண்டாக்கினர்; மூன்றாவதை ஒளிமயனிடமிருந்து தம் ஆற்றலால் உருவாக்கினர்.",
        '26.4': "இந்த நீரோட்டங்கள் இதயக் கடலிலிருந்து நூறு வழிகளில் பாய்கின்றன, எதிரிக்குப் புலப்படாமல். நெய்யின் தாரைகளை நான் காண்கிறேன்; அவற்றின் நடுவில் பொன் வேதஸம் உள்ளது.",
        '26.5': "ஆறுகளைப் போலத் துதித்தாரைகள் இதயமும் மனமும் உள்ளே தூய்மையாக்க ஒன்றாகப் பாய்கின்றன. நெய்யின் இவ்வலைகள் வேட்டைக்காரனிடமிருந்து ஓடும் மான்களைப் போலப் பாய்கின்றன.",
        '26.6': "ஆற்றின் வேகம்போல விரைவான இளந்தாரைகள் காற்றினும் விரைந்து பறக்கின்றன; நெய்த்தாரைகள் எல்லை மீறும் செந்நிறக் குதிரைபோல அலைகளால் பொங்குகின்றன.",
        '26.7': "விழாவுக்குச் செல்லும் அழகிகளைப் போல் புன்னகையுடன் அவை அக்னியை நோக்கிச் சாய்கின்றன; நெய்த்தாரைகள் ஸமித்துகளை அடைகின்றன, ஜாதவேதன் அவற்றில் மகிழ்ந்து அவற்றை விரும்புகிறான்.",
        '26.8': "திருமணத்திற்குச் செல்லும் அலங்கரித்த கன்னியரைப் போல் நான் அவற்றைக் காண்கிறேன்; ஸோமம் பிழியப்படும் இடத்தில், யஜ்ஞம் நடக்கும் இடத்தில் நெய்த்தாரைகள் தூய்மையாகப் பாய்கின்றன.",
        '26.9': "எங்கள் இனிய துதியை நோக்கி, பசுச்செல்வப் பரிசை நோக்கிப் பாயுங்கள்; எங்களுக்கு மங்கலச் செல்வங்களைத் தாருங்கள். எங்கள் இந்த யஜ்ஞத்தைத் தேவர்களிடம் கொண்டு செல்லுங்கள்; இனிய நெய்த்தாரைகள் பாய்கின்றன.",
        '26.10': "உலகமெல்லாம் உன் தாமத்தில் — கடலில், இதயத்தில், ஆயுளில் — நிலைபெற்றுள்ளது. நீர்களின் சங்கமத்துக்குக் கொண்டுவரப்பட்ட உன் அந்த இனிய அலையை நாங்கள் சுவைப்போமாக, ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று.",
        '26.11': "அக்னி பெரும் ஒளியுடன் பிரகாசிக்கிறான், தன் மகிமையால் அனைத்தையும் வெளிப்படுத்துகிறான்; தெய்வ விரோத தீய மாயைகளை வெல்கிறான், அரக்கனைக் குத்த கொம்புகளைக் கூர்மையாக்குகிறான், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று. (ரிக்வேதம் 5.2.9; பூர்ணாஹுதி மீதம்)",
        '27.0': "ஸம்ஸ்ராவ பாகர்களான விஸ்வேதேவர்களுக்கு ஸ்வாஹா. இது ஸம்ஸ்ராவ பாகர்களான விஸ்வேதேவர்களுக்கு, என்னுடையதன்று.",
        '28.0': "நீ பூர்ணம், நான் பூர்ணனாக வேண்டும்; நீ ஸுபூர்ணம், நான் ஸுபூர்ணனாக வேண்டும்; நீ ஸத், நான் ஸத்தாக வேண்டும்; நீ ஸர்வம், எனக்கு எல்லாம் கிட்டட்டும்; நீ அழிவற்றது, எனக்குக் குறைந்துவிடாதே. (ப்ரணீதா பாத்திரத்தை — பூர்ணபாத்ரம் — தொட்டு; ஆச்வலாயன ச்ரௌதஸூத்ரம் 1.11.6)",
        '28.1': "கிழக்கில் தேவர்களும் ருத்விக்குகளும், தெற்கில் மாதங்களும் பித்ருக்களும், மேற்கில் வீடுகளும் பசுக்களும், வடக்கில் நீர்களும் ஓஷதிகளும் வனஸ்பதிகளும், மேலே யஜ்ஞமும் சம்வத்சரமும் பிரஜாபதியும் ப்ரோக்ஷிக்கப்படட்டும் (எங்களைத் தூய்மையாக்கட்டும்). (ஆபஸ்தம்ப முறையில் இறுதியில்: யஜ்ஞஃ ஸம்வத்ஸரோ யஜ்ஞபதிஃ)",
        '28.2': "அன்னையரான நீர்கள் எங்களைத் தூய்மைப்படுத்தட்டும்; நெய்யால் தூய்மைப்படுத்துபவை நெய்யால் எங்களைப் புனிதமாக்கட்டும். தெய்வ நீர்கள் எல்லா அழுக்கையும் அடித்துச் செல்கின்றன; அவற்றிலிருந்து நான் தூயவனாய்ப் புனிதனாய் மேலெழுகிறேன். (ரிக்வேதம் 10.17.10)",
        '28.3': "ஓ நீர்களே, என்னிடம் உள்ள எந்தப் பாவத்தையும், நான் செய்த துரோகத்தையும், இட்ட சாபத்தையும், பொய்யையும் அடித்துச் செல்லுங்கள். (ரிக்வேதம் 1.23.22) நீர்களும் மூலிகைகளும் எங்களுக்கு நட்பாக இருக்கட்டும்; எங்களை வெறுப்பவனுக்கும் நாங்கள் வெறுப்பவனுக்கும் பகையாக இருக்கட்டும் (தென்மேற்கில் நீர் ஊற்றும்போது).",
        '28.4': "எங்களுடன் செல்லும் நீர்களே, நான் சந்ததியைச் சிந்திவிடாமல் இருக்கட்டும்; உங்களைக் கடலில் ஊற்றுகிறேன், உங்கள் இடத்தைச் சேருங்கள். (ப்ரஹ்மா மீதமுள்ள ப்ரணீதா நீரை யஜமான பத்தினியின் கைகளில் ஊற்றும்போது; ஆச்வலாயன ச்ரௌதஸூத்ரம் 1.11.8)",
        '29.0': "ஓ அக்னியே, எங்களுக்கு மிக நெருங்கிய நண்பனாய், காவலனாய், மங்கலமானவனாய், புகலிடம் தருபவனாய் இரு. செல்வத்தால் புகழ்பெற்ற அக்னியே, எங்களிடம் வந்து மிகப் பிரகாசமான செல்வத்தைத் தா. எங்களைக் கவனி, எங்கள் அழைப்பைக் கேள், எல்லாத் தீயோரிடமிருந்தும் எங்களைக் காத்தருள். ஓ மிக ஒளிமிக்கவனே, பிரகாசிப்பவனே, எங்கள் நண்பர்களின் சுகத்துக்காக இப்போது உன்னை வேண்டுகிறோம். (ரிக்வேதம் 5.24.1-4)",
        '29.1': "ஓ மிக இளையவனே, தன்வலிமையுள்ள அக்னியே, நான் கொணர்ந்த இந்தச் சிறந்த துதிச்சொல்லைக் கவனி. ஒருவன் நிந்திக்கிறான், மற்றவன் துதிக்கிறான்; பக்தனான நான், ஓ அக்னியே, உன் உருவத்தை வணங்குகிறேன். (ரிக்வேதம் 1.147.2)",
        '30.0': "எங்கள் பிள்ளைகளுக்கும் பேரர்களுக்கும், எங்கள் ஆயுளுக்கும், எங்கள் பசுக்களுக்கும் குதிரைகளுக்கும் தீங்கு செய்யாதே. ஓ ருத்ரனே, கோபத்தில் எங்கள் வீரர்களைக் கொல்லாதே; ஹவிஸ்ஸுடன் நாங்கள் எப்போதும் உன்னை அழைக்கிறோம். (ரிக்வேதம் 1.114.8)",
        '30.1': "க்ஷத்ரத்தைத் தாங்கும், பெருவலிமையுள்ள ப்ருஹத்ஸாமம், த்ரிஷ்டுப்பின் ஓஜஸ், ஒளிர்வது, உக்ர வீரர்கள் உடையது: இந்திரனே, பஞ்சதச ஸ்தோமத்தாலும் ஸகரம் என்ற காற்றாலும் இந்த நடுப்பகுதியை (உடலை) காப்பாயாக. (ரக்ஷா பஸ்மம் தரிக்கும்போது; ஆச்வலாயன ச்ரௌதஸூத்ரம் 4.12.2)",
        '30.2': "ஜமதக்னியின் முக்குண ஆயுள், கஸ்யபரின் முக்குண ஆயுள், அகஸ்தியரின் முக்குண ஆயுள், தேவர்களின் முக்குண ஆயுள் — அந்த முக்குண ஆயுள் எனக்கு உண்டாகட்டும்; அனைத்தும் நூறு ஆண்டு ஆயுளாகட்டும்.",
        '31.0': "ஓ அக்னியே, எங்கள் எல்லா வழிகளையும் அறிந்த தேவா, நல்வழியில் எங்களைச் செழிப்புக்கு இட்டுச்செல். வழி தவறச்செய்யும் பாவத்தை எங்களிடமிருந்து அகற்று; உனக்கு மிகுந்த நமஸ்கார வார்த்தைகளை அர்ப்பணிக்கிறோம். (ரிக்வேதம் 1.189.1; தைத்திரீய ஸம்ஹிதை 1.1.14)",
        '31.1': "அக்னியே, என்றும் புதியவனான நீ உன் மங்கலங்களால் எல்லா இடர்களிலிருந்தும் எங்களைக் கடத்துவாயாக; எங்களுக்குப் பரந்த அரணாகவும், எங்கள் மக்களுக்கு நலமும் இன்பமுமாகவும் இரு. (ருக்வேதம் 1.189.2)",
        '31.2': "அக்னியே, அக்னியைப் பேணாத மக்களைத் தாக்கிய நோய்களை எங்களிடமிருந்து விரட்டு; வழிபடத்தக்க தேவனே, எல்லா அமரர்களுடனும் பூமியை மீண்டும் எங்கள் நலனுக்காக ஆக்கு. (ருக்வேதம் 1.189.3)",
        '31.3': "அக்னியே, உன் இனிய இருப்பிடத்தில் ஒளிர்ந்து இடையறாத காவல்களால் எங்களைக் காப்பாயாக; இளையோனே, வலியோனே, உன்னைப் போற்றுபவனை இப்போதோ பின்னரோ அச்சம் தீண்டாதிருக்கட்டும். (ருக்வேதம் 1.189.4)",
        '31.4': "அக்னியே, பாவிக்கும் பேராசைப் பகைவனுக்கும் துர்பாக்கியத்துக்கும் எங்களைக் கைவிடாதே; வலியோனே, பற்களால் கடிப்பவனுக்கும் பல்லில்லாதவனுக்கும் தீங்கிழைப்பவனுக்கும் எங்களை ஒப்படைக்காதே. (ருக்வேதம் 1.189.5)",
        '31.5': "ருதத்திலிருந்து பிறந்த அக்னியே, போற்றப்பட்ட உன் போன்றவன் எங்கள் உடல்களுக்குப் புகலிடம் தருவான்; தேவனே, தீங்கிழைக்க, பழிக்க, வீழ்த்த நினைக்கும் அனைவரையும் தடுப்பவன் நீயே. (ருக்வேதம் 1.189.6)",
        '31.6': "வழிபடத்தக்க அக்னியே, இருவகை மனிதர்களையும் அறிந்த நீ காலையில் அவர்களிடம் வருகிறாய்; மாலையில் மனிதனுக்கு அழைக்கத்தக்கவனாகி, ஆர்வமுள்ள ருத்விக்குகளால் ஒளியூட்டப்பட்டு, என்றும் தவறாதவனாக இருக்கிறாய். (ருக்வேதம் 1.189.7)",
        '31.7': "மானனின் மகனான நாங்கள் இந்த வலிய அக்னிக்கு இப்புகழ்மொழிகளைச் சொன்னோம்; ருஷிகளுடன் நாங்கள் ஆயிரமடங்கு பெறுவோமாக; உணவு, வலிமை, உற்சாகம் தரும் கொடைகளைப் பெறுவோமாக. (ருக்வேதம் 1.189.8)",
        '32.0': "கார்ஹபத்யாக்னியான உனக்கு நமஸ்காரம், தக்ஷிணாக்னியான உனக்கு நமஸ்காரம்; ஆஹவநீயாக்னிக்கு நமஸ்காரம், மஹாவேதிக்குத் திரும்பத் திரும்ப நமஸ்காரம்.",
        '32.1': "வேதத்தின் இரு காண்டங்களாலும் எடுத்துரைக்கப்படும், கர்ம–ப்ரஹ்ம ஸ்வரூபியான, ஸ்வர்க்கமும் மோட்சமும் அருளும் யஜ்ஞேசனுக்குத் திரும்பத் திரும்ப நமஸ்காரம்.",
        '32.2': "ஓ யஜ்ஞேசா, அச்யுதா, கோவிந்தா, மாதவா, அனந்தா, கேசவா, கிருஷ்ணா, விஷ்ணோ, ஹ்ருஷீகேசா, வாஸுதேவா — உனக்கு நமஸ்காரம்.",
        '32.3': "தவமும் கர்மமுமான எல்லாப் ப்ராயச்சித்தங்களிலும் ஸ்ரீகிருஷ்ணனின் இடைவிடாத நினைவே மேலானது.",
        '33.0': "கவனக்குறைவால் கர்மம் செய்பவர்களின் யஜ்ஞங்களில் எது குறைகிறதோ அது விஷ்ணுவின் நினைவாலேயே நிறைவு பெறும் என்று ஸ்ருதி கூறுகிறது.",
        '33.1': "அக்னிமண்டலத்தின் நடுவில் உள்ள, நான்கு தோள்களுடைய, கிரீடம் அணிந்த, பக்தர்களின் விருப்பத்தை அளிக்கும் யஜ்ஞபோக்தாவான ஸ்ரீஹரியைத் த்யானிக்க வேண்டும்.",
        '33.2': "இந்த ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியான பாரதீரமண முக்யப்ராணாந்தர்கதரான ஹரிணீபதி ஸ்ரீபரசுராமர் மகிழட்டும். ஸ்ரீகிருஷ்ணார்ப்பணமஸ்து.",
        '33.3': "தேவாசுரர்களால் வணங்கப்படும் தேவ ஸ்ரேஷ்டரே, செல்லுங்கள்; ஓ ஹுதாசனனே, பிரம்மாதி தேவர்கள் இருக்கும் இடத்திற்குச் செல்.",
        '34.0': "சித்தம், சித்தி, ஆகூதம், ஆகூதி, விஜ்ஞாதம், விஜ்ஞானம் — ஒவ்வொன்றுக்கும் ஸ்வாஹா; ஒவ்வொன்றும் அந்தத் தேவதைக்கே, என்னுடையதல்ல. (ஜயா ஆஹுதிகள் 1-6, தைத்திரீய ஸம்ஹிதை 3.4.4)",
        '34.1': "மனம், சக்வரீ, தர்சம், பூர்ணமாஸம், ப்ருஹத், ரதந்தரம் — ஒவ்வொன்றுக்கும் ஸ்வாஹா; ஒவ்வொன்றும் அந்தத் தேவதைக்கே, என்னுடையதல்ல. (ஜயா ஆஹுதிகள் 7-12, தைத்திரீய ஸம்ஹிதை 3.4.4)",
        '34.2': "ப்ரஜாபதி இந்த வெற்றிகளைப் போர்களில் உக்ரனான வலிய இந்திரனுக்கு அளித்தார்; எல்லா மக்களும் அவனை வணங்கினர்; அவன் உக்ரனாகவும் ஹவிஸுக்குத் தகுந்தவனாகவும் ஆனான், ஸ்வாஹா. இது ப்ரஜாபதிக்கு, என்னுடையதல்ல. (பதின்மூன்றாவது ஜயா ஆஹுதி)",
        '35.0': "உயிர்களின் தலைவனான அக்னி — இந்த ப்ரஹ்மத்திலும், இந்த க்ஷத்ரத்திலும், இந்த ஆசியிலும், இந்தப் புரோகிதத்திலும், இந்தக் கர்மத்திலும், இந்தத் தேவ அழைப்பிலும் என்னைக் காக்கட்டும், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதல்ல. (அப்யாதானம் 1, தைத்திரீய ஸம்ஹிதை 3.4.5)",
        '35.1': "மூத்தோரின் தலைவனான இந்திரன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது இந்திரனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 2)",
        '35.2': "பூமியின் தலைவனான யமன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது யமனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 3)",
        '35.3': "அந்தரிக்ஷத்தின் தலைவனான வாயு இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது வாயுவுக்கு, என்னுடையதல்ல. (அப்யாதானம் 4)",
        '35.4': "வானுலகின் தலைவனான ஸூர்யன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது ஸூர்யனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 5)",
        '35.5': "நட்சத்திரங்களின் தலைவனான சந்திரன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது சந்திரனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 6)",
        '35.6': "ப்ரஹ்மத்தின் (மந்திரத்தின்) தலைவனான ப்ருஹஸ்பதி இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது ப்ருஹஸ்பதிக்கு, என்னுடையதல்ல. (அப்யாதானம் 7)",
        '35.7': "உண்மைகளின் தலைவனான மித்ரன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது மித்ரனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 8)",
        '35.8': "நீர்களின் தலைவனான வருணன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது வருணனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 9)",
        '35.9': "நீரோட்டங்களின் தலைவனான ஸமுத்ரம் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது ஸமுத்ரத்துக்கு, என்னுடையதல்ல. (அப்யாதானம் 10)",
        '35.10': "பேரரசுகளின் தலைவனான அன்னம் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது அன்னத்துக்கு, என்னுடையதல்ல. (அப்யாதானம் 11)",
        '35.11': "மூலிகைகளின் தலைவனான ஸோமன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது ஸோமனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 12)",
        '35.12': "தூண்டுதல்களின் தலைவனான ஸவிதா இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது ஸவிதாவுக்கு, என்னுடையதல்ல. (அப்யாதானம் 13)",
        '35.13': "பசுக்களின் தலைவனான ருத்ரன் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது ருத்ரனுக்கு, என்னுடையதல்ல. (அப்யாதானம் 14)",
        '35.14': "உருவங்களின் தலைவனான த்வஷ்டா இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது த்வஷ்டாவுக்கு, என்னுடையதல்ல. (அப்யாதானம் 15)",
        '35.15': "மலைகளின் தலைவனான விஷ்ணு இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது விஷ்ணுவுக்கு, என்னுடையதல்ல. (அப்யாதானம் 16)",
        '35.16': "கணங்களின் தலைவர்களான மருத்துகள் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது மருத்துகளுக்கு, என்னுடையதல்ல. (அப்யாதானம் 17)",
        '35.17': "தந்தையர், பாட்டனார், தொலைவிலும் அருகிலும் உள்ள பித்ருக்கள், முன்னோர் இந்தக் கர்மத்தில் என்னைக் காக்கட்டும், ஸ்வாஹா. இது பித்ருக்களுக்கு, என்னுடையதல்ல. (அப்யாதானம் 18)",
        '36.0': "ருதத்தால் வெல்லும், ருதமே இருப்பிடமான கந்தர்வன் அக்னி; அவனுடைய அப்ஸரஸ்கள் மூலிகைகள், “ஊர்ஜ” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 1)",
        '36.1': "அனைத்தையும் இணைக்கும், ஸர்வஸாமனான கந்தர்வன் ஸூர்யன்; அவனுடைய அப்ஸரஸ்கள் கதிர்கள், “ஆயுவ” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 2)",
        '36.2': "சூரியக் கதிர் உடைய ஸுஷும்ன கந்தர்வன் சந்திரன்; அவனுடைய அப்ஸரஸ்கள் நட்சத்திரங்கள், “பேகுரி” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 3)",
        '36.3': "காக்கும், அழகிய சிறகுடைய கந்தர்வன் யஜ்ஞம்; அவனுடைய அப்ஸரஸ்கள் தக்ஷிணைகள், “ஸ்தவ” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 4)",
        '36.4': "ப்ரஜாபதியும் விச்வகர்மாவுமான கந்தர்வன் மனம்; அவனுடைய அப்ஸரஸ்கள் ருக்கும் ஸாமமும், “வஹ்னி” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 5)",
        '36.5': "விரைவான, எங்கும் பரவிய கந்தர்வன் வாயு; அவனுடைய அப்ஸரஸ்கள் நீர்கள், “முதா” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 6)",
        '36.6': "உலகின் தலைவனே, மேலும் இங்கும் உன் இல்லங்கள் உள்ளன; எங்களுக்குக் குறையாத செல்வ வளர்ச்சியும் நல்ல வலிமையும் ஆண்டு முழுவதும் நலமும் தா, ஸ்வாஹா. இது புவனபதிக்கு, என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 7)",
        '36.7': "பரமேஷ்டியும் அதிபதியுமான கந்தர்வன் ம்ருத்யு; அவனுடைய அப்ஸரஸ்கள் உலகம், “புவ” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 8)",
        '36.8': "நல்லிருப்பும் நல்வாழ்வும் தருபவன், நன்மை செய்பவன், ஒளி நிறைந்த கந்தர்வன் பர்ஜன்யன்; அவனுடைய அப்ஸரஸ்கள் மின்னல்கள், “ருச்” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 9)",
        '36.9': "தொலைவிலிருந்து ஆயுதம் எறியும், இரக்கமற்ற கந்தர்வன் ம்ருத்யு; அவனுடைய அப்ஸரஸ்கள் உயிர்கள், “பீரு” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 10)",
        '36.10': "அழகிய, எளியோரை ஒளிரச்செய்யும் கந்தர்வன் காமன்; அவனுடைய அப்ஸரஸ்கள் ஏக்கங்கள், “சோசயந்தீ” என்ற பெயருடையவர் — அவன் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும், அவர்கள் இந்த ப்ரஹ்ம க்ஷத்ரங்களைக் காக்கட்டும்; அவனுக்கு ஸ்வாஹா, அவர்களுக்கு ஸ்வாஹா. இது கந்தர்வனுக்கும் அப்ஸரஸ்களுக்கும், என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 11)",
        '36.11': "உலகின் தலைவனே, மேலும் இங்கும் இல்லங்கள் உடையவனே, இந்த ப்ரஹ்மத்துக்கும் இந்த க்ஷத்ரத்துக்கும் பரந்த பெரிய அடைக்கலம் தா, ஸ்வாஹா. இது புவனபதியான ப்ரஹ்மனுக்கு, என்னுடையதல்ல. (ராஷ்ட்ரப்ருத் 12)",
        '37.0': "ஓ பிரஜாபதியே, உன்னைத் தவிர வேறு யாரும் இப்படைப்புகள் அனைத்தையும் சூழவில்லை. எந்த விருப்பத்துடன் உனக்கு ஹோமம் செய்கிறோமோ அது எங்களுக்குக் கிடைக்கட்டும்; நாங்கள் செல்வங்களுக்கு அதிபதிகளாகட்டும், ஸ்வாஹா. இது பிரஜாபதிக்கு, என்னுடையதன்று. (தைத்திரீய ஸம்ஹிதை 1.8.14; ரிக்வேதம் 10.121.10)",
        '37.1': "பூ: ஸ்வாஹா — அக்னிக்கு, என்னுடையதல்ல. புவ: ஸ்வாஹா — வாயுவுக்கு, என்னுடையதல்ல. ஸுவ: ஸ்வாஹா — ஸூர்யனுக்கு, என்னுடையதல்ல. (மூன்று வ்யாஹ்ருதிகள்)",
        '37.2': "இக்கர்மத்தில் நான் மிகுதியாகச் செய்தாலும் குறைவாகச் செய்தாலும், அதை அறிந்த ஸ்விஷ்டக்ருத் அக்னி அனைத்தையும் நன்கு யஜிக்கப்பட்டதாகவும் நன்கு ஹோமம் செய்யப்பட்டதாகவும் ஆக்கட்டும், ஸ்வாஹா. இது ஸ்விஷ்டக்ருத் அக்னிக்கு, என்னுடையதன்று. (ஆபஸ்தம்ப க்ருஹ்யஸூத்ரம் 2.7)",
        '38.0': "ஸ்வாஹா — இது ஸம்ஸ்ராவ பாகிகளான வஸுக்கள், ருத்ரர்கள், ஆதித்யர்களுக்கு, என்னுடையதல்ல. ஓம் பூர்புவஸ்ஸுவ: ஸ்வாஹா — ப்ரஜாபதிக்கு, என்னுடையதல்ல.",
        '39.0': "யஜ்ஞத்தில் அறியாமலோ அறிந்தோ தவறாகச் செய்ததை, ஓ அக்னியே, சரிசெய்; அது உள்ளவாறு உனக்கே தெரியும், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று.",
        '39.1': "யஜ்ஞம் புருஷனுக்குச் சமம், புருஷன் யஜ்ஞத்துக்குச் சமம்; ஓ அக்னியே, இதைச் சரிசெய், உள்ளவாறு உனக்கே தெரியும், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று.",
        '39.2': "எளிய மனமும் குறைந்த திறனும் உள்ள மனிதர்கள் யஜ்ஞத்தில் எதை அறிவதில்லையோ, அதைக் கர்மம் அறிந்த ஹோதா அக்னி அறிந்து, சிறந்த யாஜகனாகத் தக்க காலத்தில் தேவர்களுக்கு அர்ப்பணிக்கிறான், ஸ்வாஹா. இது அக்னிக்கு, என்னுடையதன்று. (தைத்திரீய ப்ராஹ்மணம் 3.7.11)",
        '39.3': "பூ: ஸ்வாஹா — அக்னிக்கு; புவ: ஸ்வாஹா — வாயுவுக்கு; ஸுவ: ஸ்வாஹா — ஸூர்யனுக்கு; ஓம் பூர்புவஸ்ஸுவ: ஸ்வாஹா — ப்ரஜாபதிக்கு; எதுவும் என்னுடையதல்ல.",
        '39.4': "ஓம் பூர்ப்புவஸ்ஸுவ ஸ்வாஹா — பிரஜாபதிக்கு, என்னுடையதன்று. ஓம் ஸ்ரீவிஷ்ணவே ஸ்வாஹா — பரமாத்மாவான விஷ்ணுவுக்கு, என்னுடையதன்று. ஓம் பசுபதி ருத்ரனுக்கு ஸ்வாஹா — பசுபதி ருத்ரனுக்கு, என்னுடையதன்று.",
        '40.0': "கடைசி உயர்ந்த ஆஹுதியாகப் பூர்ணாஹுதியைச் செய்கிறான். பூர்ணாஹுதியே எல்லாம்; அதனால் எல்லாவற்றையும் அடைகிறான். இந்தப் பூமியே பூர்ணாஹுதி; இதில்தான் அவன் நிலைபெறுகிறான், ஸ்வாஹா.",
        '40.1': "ஓ அக்னியே, உனக்கு ஏழு ஸமித்துகள், ஏழு நாக்குகள், ஏழு ரிஷிகள், ஏழு பிரிய தாமங்கள்; ஏழு ஹோதாக்கள் ஏழு விதமாக உன்னை யஜிக்கிறார்கள்; உன் ஏழு யோனிகளை நெய்யால் நிரப்பு, ஸ்வாஹா. (வஸோர்தாரா) இது ஸப்தவானான அக்னிக்கு, என்னுடையதல்ல.",
        '41.0': "ஓ அதிதியே, நீ அனுமதித்தாய்; ஓ அனுமதியே, நீ அனுமதித்தாய்; ஓ ஸரஸ்வதியே, நீ அனுமதித்தாய்; ஓ தேவ ஸவிதாவே, நீ தூண்டினாய். (இறுதிப் பரிஷேசனம், ஆபஸ்தம்ப க்ருஹ்யஸூத்ரம் 2.8)",
        '41.1': "கிழக்கில்; தெற்கில்; மேற்கில்; வடக்கில்; மேலே; கீழே. (ப்ரணீதா நீரை ஒவ்வொரு திசையிலும் இரு துளிகள், மீதியைக் கிழக்கு நோக்கிக் கீழே; மைலாப்பூர் நூல்)",
        '41.2': "ப்ரஹ்மாவே, உமக்கு வரம் (தானம்) தருகிறேன். ப்ரஹ்மாவுக்கு நமஸ்காரம்; எல்லா உபசாரங்களாலும் பூஜிக்கப்படட்டும். (ப்ரஹ்மாவுக்குத் தக்ஷிணை தரும்போது)",
        '42.0': "ஓ அக்னியே, எங்கள் எல்லா வழிகளையும் அறிந்த தேவா, நல்வழியில் எங்களைச் செழிப்புக்கு இட்டுச்செல். வழி தவறச்செய்யும் பாவத்தை எங்களிடமிருந்து அகற்று; உனக்கு மிகுந்த நமஸ்கார வார்த்தைகளை அர்ப்பணிக்கிறோம். (ரிக்வேதம் 1.189.1; தைத்திரீய ஸம்ஹிதை 1.1.14) அக்னிக்கு நமஸ்காரம்.",
        '42.1': "ஓ அக்னியே, மந்திரம், கிரியை, பக்தி ஆகியவற்றில் குறையுடன் நான் எதை ஹோமம் செய்தேனோ, ஓ தேவா, அது உனக்கு நிறைவானதாகட்டும்.",
        '42.2': "தவமும் கர்மமுமான எல்லாப் ப்ராயச்சித்தங்களிலும் ஸ்ரீகிருஷ்ணனின் இடைவிடாத நினைவே மேலானது.",
        '42.3': "கார்ஹபத்யாக்னியான உனக்கு நமஸ்காரம், தக்ஷிணாக்னியான உனக்கு நமஸ்காரம்; ஆஹவநீயாக்னிக்கு நமஸ்காரம், மஹாவேதிக்குத் திரும்பத் திரும்ப நமஸ்காரம்.",
        '42.4': "வேதத்தின் இரு காண்டங்களாலும் எடுத்துரைக்கப்படும், கர்ம–ப்ரஹ்ம ஸ்வரூபியான, ஸ்வர்க்கமும் மோட்சமும் அருளும் யஜ்ஞேசனுக்குத் திரும்பத் திரும்ப நமஸ்காரம்.",
        '42.5': "ஓ யஜ்ஞேசா, அச்யுதா, கோவிந்தா, மாதவா, அனந்தா, கேசவா, கிருஷ்ணா, விஷ்ணோ, ஹ்ருஷீகேசா, வாஸுதேவா — உனக்கு நமஸ்காரம்.",
        '43.0': "க்ஷத்ரத்தைத் தாங்கும், பெருவலிமையுள்ள ப்ருஹத்ஸாமம், த்ரிஷ்டுப்பின் ஓஜஸ், ஒளிர்வது, உக்ர வீரர்கள் உடையது: இந்திரனே, பஞ்சதச ஸ்தோமத்தாலும் ஸகரம் என்ற காற்றாலும் இந்த நடுப்பகுதியை (உடலை) காப்பாயாக. (ரக்ஷா பஸ்மம் தரிக்கும்போது; ஆச்வலாயன ச்ரௌதஸூத்ரம் 4.12.2)",
        '44.0': "எவரது நினைவாலும் நாம உச்சரிப்பாலும் தவம், யஜ்ஞம், கிரியைகளில் உள்ள குறை உடனே நிறைவடைகிறதோ அந்த அச்யுதனை வணங்குகிறேன்.",
        '44.1': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '44.2': "என்னால் செய்யப்பட்ட இந்த … ஹோமம் என்ற கர்மம் — ஓம் தத்ஸத் — ப்ரஹ்மார்ப்பணமாகட்டும்.",
      },
    },
    'ganapati-homa': {
      summary: "தொடக்கம் முதல் இறுதி வரை கணபதி ஹோமம்: த்ரவ்யங்களும் எண்ணிக்கைகளும், ஸங்கல்பம், (ஸ்மார்த்த) விக்னேச்வர பூஜை, கலசமும் கும்பமும், ந்யாஸம் தியானம் மூலமந்திரம் ப்ராணப்ரதிஷ்டையுடன் மஹாகணபதி ஆவாஹனமும் பூஜையும்; பொது முறையிலிருந்து அக்னிமுகம்; அக்னியில் கணபதி ஆவாஹனம்; அஷ்டத்ரவ்யங்களின் பிரதான ஆஹுதிகள் மந்திரங்களுடன் (மூலமந்திரம், கணானாம் த்வா, கணேச காயத்ரீ, வக்ரதுண்ட, அருகம்புல், பொரி, தேங்காய் இரு ஓடுகள்), கணபதி அதர்வசீர்ஷம் ஒவ்வொரு பகுதியும் ஸ்வாஹாவுடன்; உத்தராங்கம்; நிறைவு பூஜை, ஆரத்தி, மந்த்ரபுஷ்பம், வலம்வருதல், தர்ப்பணம், உத்வாஸனம், தீர்த்தம், பிரார்த்தனை. மேலே மாத்வ அல்லது ஸ்மார்த்த தேர்ந்தெடுக்கவும்.",
      verses: {
        '0.0': "கணபதி, சங்கர யாகங்களில் ப்ரணீதா பாத்திரம், பிரம்மா, இத்மம், இரு சக்ஷுஷீ ஆஹுதிகள், ஸ்விஷ்டக்ருத் முதலியவை இல்லை. (வாஸிஷ்ட ஸம்ஹிதையின் விநாயகோதயம்; ஹோம–ஹவனத்தில் மேற்கோள்)",
        '1.0': "கணபதியே (கூட்டங்களின் தலைவனே), உன் கணங்களிடையே அமர்வாயாக; கவிகளில் சிறந்த ஞானி நீ என்கின்றனர். நீ இன்றி அருகிலோ தொலைவிலோ எதுவும் நடப்பதில்லை; எங்கள் இந்தப் பெரும் துதியை ஏற்பாயாக. (ரிக்வேதம் 10.112.9; பூஜைக்கு முன் பகவானிடம் ப்ரார்த்தனை.)",
        '1.1': "யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமணரான முக்யப்ராணருள் உள்ளவருமான ஹரிணீபதி ஸ்ரீ பரசுராமரின் தூண்டுதலால், அவர் ப்ரீதிக்காக, கணபதியுள் உள்ள விச்வம்பரரின் ப்ரீதிக்காக, இடையூறின்மைக்காக இத்தனை தேங்காய்களுடன் அஷ்டத்ரவ்யங்களால் கணஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக ஸ்தண்டில ஸம்ஸ்காரமும் அக்னி ப்ரதிஷ்டையும் செய்வேன்.",
        '2.0': "எல்லாத் தடைகளும் நீங்க, வெண்ணிற ஆடை அணிந்தவனும், சந்திரன் போல் ஒளிர்பவனும், நான்கு கரங்களுடையவனும், மலர்ந்த முகமுடையவனுமான எங்கும் நிறைந்தவனைத் தியானிக்க வேண்டும்.",
        '2.1': "என் சேர்ந்த பாவங்கள் அனைத்தும் நீங்குவதன் மூலம் பரமேச்வரனின் ப்ரீதிக்காக, செய்யப்போகும் கர்மம் இடையூறின்றி முடிய முதலில் விக்னேச்வர பூஜை செய்வேன்.",
        '2.2': "கணங்களின் தலைவனே, கவிகளின் கவியே, மிகப் புகழ்பெற்றவனே, மந்திரங்களில் மூத்த அரசனே, ப்ரஹ்மணஸ்பதியே, உன்னை அழைக்கிறோம்: எங்களைக் கேட்டபடி உன் காவல்களுடன் வந்து ஆசனத்தில் அமர். (ரிக்வேதம் 2.23.1)",
        '2.3': "ஓம் பூர்புவஸ்ஸுவரோம். இந்த மஞ்சள் பிம்பத்தில் விக்னேச்வரரை தியானிக்கிறேன், ஆவாஹனம் செய்கிறேன். விக்னேச்வரருக்கு நமஸ்காரம்: ஆஸனம், பாத்யம், அர்க்யம், ஆசமனீயம், ஸ்நானம், ஸ்நானத்துக்குப் பின் ஆசமனீயம்; வஸ்த்ரம், உபவீதம், ஆபரணங்களுக்குப் பதிலாக அக்ஷதை; சந்தனம், அதன்மேல் மஞ்சள் குங்குமம், அக்ஷதை, புஷ்பமாலை ஸமர்ப்பிக்கிறேன்; புஷ்பங்களால் பூஜிக்கிறேன்.",
        '2.4': "கணபதியின் பதினாறு நாமங்கள் — ஸுமுக, ஏகதந்த, கபில, கஜகர்ணக, லம்போதர, விகட, விக்னராஜ, விநாயக, தூமகேது, கணாத்யக்ஷ, பாலசந்த்ர, கஜானன, வக்ரதுண்ட, ஶூர்பகர்ண, ஹேரம்ப, ஸ்கந்தபூர்வஜ — ஒவ்வொன்றுக்கும் மலர் அல்லது அருகம்புல்.",
        '2.5': "தூப தீபங்களுக்குப் பதிலாக அக்ஷதை. விக்னேச்வரருக்கு நமஸ்காரம்: தேங்காய் இரு மூடிகள், வாழைப்பழங்கள், இந்த அமுதம் அனைத்தையும் நைவேத்யமாக; கற்பூர தாம்பூலம், கற்பூர நீராஜனம், மந்த்ரபுஷ்பம், ஸ்வர்ணபுஷ்பம் (நாணயம்), எல்லா உபசாரங்களையும் ஸமர்ப்பிக்கிறேன்.",
        '2.6': "வளைந்த துதிக்கையனே, பேருடலோனே, கோடி சூரியர் ஒளியோனே, தேவனே, என் எல்லாச் செயல்களையும் எப்போதும் இடையூறின்றிச் செய்வாயாக.",
        '2.7': "ஸுமுக, ஏகதந்த, கபில, கஜகர்ணக, லம்போதர, விகட, விக்னராஜ, விநாயக, தூமகேது, கணாத்யக்ஷ, பாலசந்த்ர, கஜானன, வக்ரதுண்ட, சூர்ப்பகர்ண, ஹேரம்ப, ஸ்கந்தபூர்வஜ — இந்தப் பதினாறு நாமங்களை வித்யாரம்பம், விவாஹம், நுழைதல், புறப்படுதல், போர், எல்லாச் செயல்களிலும் படிப்பவனுக்கும் கேட்பவனுக்கும் இடையூறு உண்டாவதில்லை.",
        '3.0': "என் பாவங்கள் நீங்குவதன் மூலம் பரமேச்வர ப்ரீதிக்காக; இன்ன நட்சத்திரம் ராசியில் பிறந்த இன்ன பெயருடைய எனக்கும் என் குடும்பத்துக்கும் க்ஷேமம், ஸ்தைர்யம், வீர்யம், விஜயம், ஆயுள், ஆரோக்யம், ஐச்வர்யம் வளர, தனதான்ய ஸம்ருத்தி பெற, எங்கும் வெற்றி பெற, எல்லாவித அரிஷ்டங்களும் நீங்க, எல்லா மங்கலங்களும் பெருக, மஹாகணபதியின் அருள் பெற, அவர் அருளால் எல்லா இடையூறுகளும் நீங்கி மனோரதங்களும் எல்லா விருப்பங்களும் நிறைவேற, தேங்காய் முதலிய த்ரவ்யங்களால் இயன்றவரை அறிந்தவரை மூலமந்திரத்தால் ஸ்ரீ மஹாகணபதி ஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக கலசாதி பூஜை செய்வேன்.",
        '4.0': "கலசத்தின் வாயில் விஷ்ணுவும், கழுத்தில் ருத்திரனும் உறைகின்றனர்; அடியில் பிரம்மா நிற்கிறார்; நடுவில் மாத்ருகணங்கள் உள்ளனர் என்பர்.",
        '4.1': "கலசத்தின் வயிற்றில் எல்லாக் கடல்களும் ஏழு தீவுகளுடைய பூமியும் உள்ளன; ரிக், யஜுர், ஸாம, அதர்வ வேதங்கள் அங்கங்களுடன் கலசத்தை அடைக்கலமாகக் கொண்டுள்ளன. இங்கே காயத்ரீ, ஸாவித்ரீ, அமைதியும் வளமும் தரும் சக்திகளும் உள்ளன.",
        '4.2': "பாவத்தை அழிக்கும் எல்லாக் கடல்களும், ஆறுகளும், தீர்த்தங்களும், மேகங்களும், நதிகளும் இறைவனின் பூஜைக்காக இங்கே வரட்டும்.",
        '4.3': "கங்கையே, யமுனையே, கோதாவரியே, ஸரஸ்வதியே, நர்மதையே, ஸிந்துவே, காவேரியே, இந்நீரில் ஸந்நிதி கொள்வீர்.",
        '4.4': "தேவர்கள் வரவும் அசுர சக்திகள் விலகவும், தேவர்களை அழைக்கும் அடையாளமான மணியை ஒலிக்கிறேன்.",
        '4.5': "ஓ வருணா, என் இந்த அழைப்பைக் கேள், இன்று எங்களுக்கு அருள்செய்; உன் பாதுகாப்பை விரும்பி உன்னை அழைக்கிறேன். (ரிக்வேதம் 1.25.19; கலசத்தில் வருண ஆவாஹனம்)",
        '4.6': "இந்தத் துதியால் வணங்கி, யஜமானன் ஹவிஸ்களால் வேண்டுவதையே நான் உன்னிடம் வேண்டுகிறேன்; வருணனே, சினமின்றி இங்கு கவனிப்பாயாக; பலரால் போற்றப்படுபவனே, எங்கள் ஆயுளைப் பறிக்காதே. (ருக்வேதம் 1.24.11) ஓம் பூர்புவஸ்ஸுவரோம்: இந்தக் கும்பத்தில் வருணனை தியானித்து ஆவாஹனம் செய்கிறேன்.",
        '5.0': "இந்த ஸ்ரீ மஹாகணபதி மஹாமந்திரத்துக்கு கணக ருஷி, நிச்ருத்காயத்ரீ சந்தஸ், மஹாகணபதி தேவதை; காம் பீஜம், கீம் சக்தி, கூம் கீலகம்; மஹாகணபதி அருளுக்காக ஜபத்தில் விநியோகம். காம் கட்டைவிரல்களுக்கு, கீம் ஆள்காட்டி விரல்களுக்கு, கூம் நடுவிரல்களுக்கு, கைம் மோதிர விரல்களுக்கு, கௌம் சுண்டுவிரல்களுக்கு, க: உள்ளங்கை புறங்கைகளுக்கு; காம் இதயத்துக்கு, கீம் தலைக்கு, கூம் சிகைக்கு, கைம் கவசத்துக்கு, கௌம் மூன்று கண்களுக்கு, க: அஸ்த்ரத்துக்கு; பூர்புவஸ்ஸுவரோம் என்று திக்பந்தம்.",
        '5.1': "மாதுளை, கதை, கரும்பு வில், சூலம், சக்கரம், தாமரை, பாசம், நீலோத்பலம், நெற்கதிர், தன் தந்தம், ரத்னகலசம் ஏந்திய தாமரைக் கரங்கள் உடையவரும், கையில் தாமரை ஏந்திய ஒளிரும் அணிகலன்கள் கொண்ட துணைவியால் அணைக்கப்பட்டவரும், உலகின் படைப்பு அழிவு நிலைப்பைச் செய்பவருமான, விரும்பியதைத் தரும் விக்னேசரை தியானிக்க வேண்டும். (மஹாகணபதி தியானம்)",
        '5.2': "லம் — பூமி வடிவினருக்கு சந்தனம்; ஹம் — ஆகாச வடிவினருக்கு மலர்கள்; யம் — வாயு வடிவினருக்கு தூபம்; ரம் — அக்னி வடிவினருக்கு தீபம்; வம் — அமுத வடிவினருக்கு அமுத நைவேத்யம்; ஸம் — அனைத்தின் ஆத்மாவுக்கு எல்லா உபசாரங்களும்.",
        '5.3': "ஓம் ஸ்ரீம் ஹ்ரீம் க்லீம் க்லௌம் கம் — கணபதிக்கு, வரம் தருபவர்களில் சிறந்தவனே, எல்லா மக்களையும் எனக்கு இணக்கமாக்குவாயாக, ஸ்வாஹா. (மஹாகணபதியின் இருபத்தெட்டு அக்ஷர மூலமந்திரம்; ஐந்து பீஜங்கள் ரமா-விஷ்ணு, கிரிஜா-சிவன், ரதி-காமன், பூமி-வராஹர், மஹாலக்ஷ்மீ-மஹாகணபதி ஆகிய இணைகள். இது உபதேச மந்திரம்: குருவிடம் கற்கவும்.)",
        '5.4': "இந்தக் கும்பத்திலும் இந்தப் பிரதிமையிலும் மஹாகணபதியை தியானிக்கிறேன்; ஆவாஹனம் செய்கிறேன்.",
        '6.0': "செங்கடலில் படகின் மேல் ஒளிரும் செந்தாமரையில் அமர்ந்தவளும், தாமரைக் கரங்களில் பாசம், வண்டு நாண் கொண்ட கரும்பு வில், அங்குசம், ஐந்து அம்புகள், கபாலம் ஏந்தியவளும், மூன்று கண்களால் ஒளிர்பவளும், உதய சூரிய நிறத்தவளுமான பரா ப்ராணசக்தி தேவி எங்களுக்கு இன்பம் தரட்டும். (ப்ராணப்ரதிஷ்டை தியானம்)",
        '6.1': "ஆம் ஹ்ரீம் க்ரோம் க்ரோம் ஹ்ரீம் ஆம், யரலவசஷஸஹோம், ஹம்ஸ: ஸோஹம் ஸோஹம் ஹம்ஸ: — ஸ்ரீ மஹாகணபதியின் ப்ராணன்கள் இங்கே; ஜீவன் இங்கே நிலைபெற்றது; வாக்கு, மனம், தோல், கண், காது, நாக்கு, மூக்கு ஆகிய எல்லா இந்திரியங்களும் ஐந்து ப்ராணன்களும் இங்கு வந்து இந்தக் கும்பத்திலும் பிரதிமையிலும் இன்பமாக நெடுநாள் தங்கட்டும், ஸ்வாஹா.",
        '6.2': "அஸுநீதியே, எங்களுக்கு மீண்டும் பார்வையையும் ப்ராணனையும் இன்பத்தையும் இங்கு தா; உதிக்கும் சூரியனை நெடுநாள் காண்போமாக; அனுமதியே, எங்கள் நலனுக்காக அருள்புரிவாயாக. (ருக்வேதம் 10.59.6)",
        '6.3': "ஸ்வாமியே, எல்லா உலகின் நாதனே, பூஜை முடியும் வரை அன்புடன் இந்த பிம்பத்தில் ஸந்நிதி செய்வாயாக. ப்ராணன்களை ப்ரதிஷ்டை செய்கிறேன்.",
        '7.0': "மஹாகணபதிக்கு நமஸ்காரம்: ரத்னஸிம்ஹாஸனம், பாதங்களுக்குப் பாத்யம், கைகளுக்கு அர்க்யம், முகத்துக்கு ஆசமனீயம், ஸ்நானம், வஸ்த்ரம், யஜ்ஞோபவீதம், ஆபரணங்கள், சந்தனம், மஞ்சள் குங்குமம், அக்ஷதை, புஷ்பமாலை ஸமர்ப்பிக்கிறேன். (ஒவ்வொன்றுக்கும் முன் மூலமந்திரம்.)",
        '7.1': "நீர்களே, நீங்கள் இன்பம் தருபவர்கள். நாங்கள் பேரின்பத்தைக் காணும்படி எங்களை வலிமையால் நிறைப்பீர்.",
        '7.2': "அன்புள்ள தாய்மார் குழந்தைகளுடன் பகிர்வது போல், உங்கள் மிக மங்கலமான ரஸத்தில் நாங்கள் இங்கே பங்குகொள்வோமாக.",
        '7.3': "உலகில் உறைவன அனைத்தையும் நீங்கள் போஷிக்கும் உங்கள் அந்த ரஸத்தை நாங்கள் எளிதில் அடைவோமாக; நீர்களே, எங்களுக்குப் புத்துயிர் தருவீர்.",
        '7.4': "கணபதியின் பதினாறு நாமங்கள் — ஸுமுக, ஏகதந்த, கபில, கஜகர்ணக, லம்போதர, விகட, விக்னராஜ, விநாயக, தூமகேது, கணாத்யக்ஷ, பாலசந்த்ர, கஜானன, வக்ரதுண்ட, ஶூர்பகர்ண, ஹேரம்ப, ஸ்கந்தபூர்வஜ — ஒவ்வொன்றுக்கும் மலர் அல்லது அருகம்புல்.",
        '7.5': "ஓம் கம் கணபதயே நம:. மஹாகணபதிக்கு நமஸ்காரம்: பலவித இலை மலர்கள், தூபம், தீபம் ஸமர்ப்பிக்கிறேன்.",
        '7.6': "ஓம் பூர்புவஸ்ஸுவ:; தெய்வீக ஸவிதாவின் சிறந்த ஒளியைத் தியானிக்கிறோம்; அவர் எங்கள் அறிவைத் தூண்டட்டும் (நைவேத்யத்தின் மேல் ப்ரோக்ஷணம்). ஸவிதா தேவனே, தூண்டுவாயாக. ஸத்யத்தை ருதத்தால் சுற்றித் தெளிக்கிறேன். நீ அமுதத்தின் விரிப்பு. ஓம் ப்ராண, அபான, வ்யான, உதான, ஸமானங்களுக்கும் ப்ரஹ்மத்துக்கும் ஸ்வாஹா (நைவேத்யத்தைக் காட்டி).",
        '7.7': "மஹாகணபதிக்கு நமஸ்காரம்: தேங்காய் முதலிய த்ரவ்யங்களை நிவேதிக்கிறேன். நீ அமுதத்தின் மூடி (நீர் விட்டு).",
        '8.0': "இவ்வாறு பூர்வாங்கம் (பொது முறையிலிருந்து).",
        '9.0': "சிவந்த ஆடை அணிந்த, சிவந்த உடல்கொண்ட, சிவந்த மாலையும் சந்தனமும் அணிந்த, பெருவயிறுடைய, யானைமுகத்தான், பாசம்–தந்தம்–அங்குசம்–அபயம் ஏந்திய, விரைவில் விருப்பம் அருளும் விக்னஹரனைத் த்யானிக்க வேண்டும். (தந்த்ரஸாரஸங்க்ரஹம் 3.90-91)",
        '9.1': "அந்தந்த தேவர்களில் நிலைத்து அவர்களின் சக்திகளை எழுப்பும் விஷ்ணு, ஒருவரே ஆயினும் மகாசக்தியுடையவராய் எல்லாவற்றையும் எளிதாகச் செய்கிறார். (தந்த்ரஸாரஸங்க்ரஹம் 3.92; கணபதியை விஷ்ணுவின் இருப்பிடமாக வழிபடுவதற்கான காரணம்.)",
        '9.2': "கணங்களின் தலைவனே, கவிகளின் கவியே, மிகப் புகழ்பெற்றவனே, மந்திரங்களில் மூத்த அரசனே, ப்ரஹ்மணஸ்பதியே, உன்னை அழைக்கிறோம்: எங்களைக் கேட்டபடி உன் காவல்களுடன் வந்து ஆசனத்தில் அமர். (ரிக்வேதம் 2.23.1) ஸ்வாஹா; இது கணபதிக்கு, என்னுடையதல்ல.",
        '9.3': "ஓ கணபதியே, உன் கணங்களிடையே அமர்; கவிகளுள் உன்னை மிகுந்த அறிவாளி என்கிறார்கள். உன்னைவிட்டு அருகிலோ தொலைவிலோ எதுவும் நடப்பதில்லை; எங்கள் இந்தப் பெரும் துதியை ஏற்றுக்கொள். (ரிக்வேதம் 10.112.9) ஸ்வாஹா; இது கணபதிக்கு, என்னுடையதல்ல.",
        '10.0': "இந்த அக்னியில் மஹாகணபதியை தியானித்து ஆவாஹனம் செய்கிறேன். மஹாகணபதிக்கு நமஸ்காரம்: ஆஸனம், பாத்யம், அர்க்யம், ஆசமனீயம், மதுபர்க்கம், ஸ்நானம்; வஸ்த்ர உபவீதங்களுக்கு அக்ஷதை; சந்தன மலர்கள்; தூபம்; தீபம். (ஒவ்வொன்றுக்கும் முன் மூலமந்திரம்.)",
        '10.1': "மஹாகணபதிக்கு நமஸ்காரம்: நெய்யை உணவாக (அக்னியில்) ஸமர்ப்பிக்கிறேன்; நீ அமுதத்தின் மூடி; கற்பூர தாம்பூலம் (அக்னியில்), கற்பூர நீராஜனம், ப்ரதக்ஷிண நமஸ்காரங்கள் ஸமர்ப்பிக்கிறேன்.",
        '11.0': "ஸ்வாஹாவுடன் மூலமந்திரம்; இது மஹாகணபதிக்கு, என்னுடையதல்ல. (முதலில் சொல் சொல்லாக வளர்த்து — ஓம் ஸ்வாஹா, ஓம் ஸ்ரீம் ஸ்வாஹா, ஓம் ஸ்ரீம் ஹ்ரீம் ஸ்வாஹா … — ஒவ்வொரு படிக்கும் ஒரு நெய் ஆஹுதி, இறுதியில் முழு மந்திரம்; பின் இடக்கையில் நெய்ப் பாத்திரம் ஏந்தி முழு மந்திரத்தால் எட்டு ஆஹுதிகள். மந்திரத்தை குருவிடம் கற்கவும்.)",
        '11.1': "கணங்களின் தலைவனே, கவிகளின் கவியே, மிகப் புகழ்பெற்றவனே, மந்திரங்களில் மூத்த அரசனே, ப்ரஹ்மணஸ்பதியே, உன்னை அழைக்கிறோம்: எங்களைக் கேட்டபடி உன் காவல்களுடன் வந்து ஆசனத்தில் அமர். (ரிக்வேதம் 2.23.1) (கலந்த த்ரவ்யத்தால் 8 அல்லது 16 முறை.) ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '11.2': "அந்தப் பரமபுருஷனை அறிவோமாக; வளைந்த துதிக்கையனைத் தியானிப்போமாக; அந்தத் தந்தி எங்களைத் தூண்டட்டும். (மஹாநாராயண உபநிஷத்தின் கணேச காயத்ரீ, எட்டு ஆஹுதிகள்.) ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '11.3': "வளைந்த துதிக்கையனே, பேருடலோனே, கோடி சூரிய ஒளியோனே, தேவனே, என் எல்லாச் செயல்களையும் எப்போதும் இடையூறின்றிச் செய்வாயாக. (எட்டு ஆஹுதிகள்.) ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '11.4': "இன்ன நட்சத்திரம் ராசியில் பிறந்த இன்ன பெயருடைய இந்த யஜமானனுக்கும் குடும்பத்துக்கும் அனுகூலம் தா, பிரதிகூலம் அழி, ஆபத்துகளை அழி, செல்வத்தை வளர், எங்கும் வெற்றி அளி, எல்லா மக்களின் இணக்கத்தையும் செய்; தேவனே, என் எல்லாச் செயல்களையும் எப்போதும் இடையூறின்றிச் செய்வாயாக. (குறைந்தது நான்கு ஆஹுதிகள்.) ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '11.5': "எழுவாயாக, புருஷனே, பச்சை பொன்னிறத்தோனே, சிவந்த கண்ணோனே, தனதான்ய வளத்தைத் தா தா, தரச்செய் தரச்செய். (பொரியால் எட்டு ஆஹுதிகள்; அதற்கு முன் பாலிலோ நெய்யிலோ தோய்த்த அருகம்புல்லால் மூலமந்திரத்துடன் எட்டு ஆஹுதிகள்.) ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '11.6': "ஜாதவேதனுக்காக ஸோமத்தைப் பிழிவோம்; பகைவனின் செல்வத்தை அவன் எரிக்கட்டும்; படகு ஆற்றைக் கடத்துவதுபோல் அக்னி எங்களை எல்லா இடர்களிலிருந்தும் பாவங்களிலிருந்தும் கடத்தட்டும், ஸ்வாஹா. இது அக்னி வடிவ மஹாகணபதிக்கு, என்னுடையதல்ல. (ருக்வேதம் 1.99.1; கண்கள் உள்ள தேங்காய் ஓட்டின் பாதியை அர்ப்பிக்கும்போது)",
        '11.7': "இந்த நிலையான இருப்பிடங்களில் வாழும் எங்களிடமிருந்து வருணன் தன் பாசத்தை விடுவிக்கட்டும்; அதிதியின் மடியிலிருந்து காவல் பெற்று — நீங்கள் எப்போதும் மங்கலங்களால் எங்களைக் காப்பீர்களாக, ஸ்வாஹா. இது வருண வடிவ மஹாகணபதிக்கு, என்னுடையதல்ல. (ருக்வேதம் 7.88.7; ஓட்டின் மற்றப் பாதியை அர்ப்பிக்கும்போது)",
        '12.0': "தேவர்களே, நாங்கள் காதுகளால் நன்மையையே கேட்போமாக; வணங்கத்தக்கவர்களே, கண்களால் நன்மையையே காண்போமாக. உறுதியான உறுப்புகளோடும் உடல்களோடும் உங்களைத் துதித்தபடி தேவர்கள் அளித்த ஆயுளை வாழ்வோமாக. பெரும்புகழ் இந்திரன் எங்களுக்கு நலம் செய்யட்டும்; அனைத்தும் அறிந்த பூஷா நலம் செய்யட்டும்; தீங்குகளைத் தடுக்கும் தார்க்ஷ்யன் நலம் செய்யட்டும்; பிருஹஸ்பதி எங்களுக்கு நலம் தரட்டும். ஓம் சாந்தி, சாந்தி, சாந்தி.",
        '12.1': "ஓம், கணபதிக்கு வணக்கம். நீயே நேரடியான தத்துவம். நீயே படைப்பவன்; நீயே காப்பவன்; நீயே அழிப்பவன். இவை அனைத்தும் நீயே, பிரம்மமே. நீயே என்றும் உள்ள ஆத்மா. ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.2': "நான் ருதத்தைக் கூறுகிறேன்; சத்தியத்தைக் கூறுகிறேன். ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.3': "என்னைக் காப்பாய்; பேசுபவனைக் காப்பாய்; கேட்பவனைக் காப்பாய்; கொடுப்பவனைக் காப்பாய்; தாங்குபவனைக் காப்பாய்; கற்றறிந்த ஆசிரியனையும் சீடனையும் காப்பாய். பின்னாலிருந்தும் முன்னாலிருந்தும், வடக்கிலிருந்தும் தெற்கிலிருந்தும், மேலிருந்தும் கீழிருந்தும் காப்பாய். எல்லாப் புறங்களிலிருந்தும் என்னைக் காப்பாய், காப்பாய். ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.4': "நீ சொல்வடிவானவன், அறிவு வடிவானவன்; ஆனந்த மயன், பிரம்ம மயன். நீ ஒப்பற்ற ஸத்-சித்-ஆனந்தம். நீ நேரடியான பிரம்மம். நீ ஞானமயன், விஞ்ஞானமயன். ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.5': "இவ்வுலகம் முழுவதும் உன்னிடமிருந்து தோன்றுகிறது; உன்னிடமே நிலைக்கிறது; உன்னிடமே ஒடுங்கும்; உன்னிடமே மீள்கிறது. நீ நிலம், நீர், நெருப்பு, காற்று, வானம். நீ வாக்கின் நான்கு நிலைகள் (பரா, பஶ்யந்தீ, மத்யமா, வைகரீ). ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.6': "நீ மூன்று குணங்களையும், மூன்று அவஸ்தைகளையும் (விழிப்பு, கனவு, ஆழ்துயில்), மூன்று உடல்களையும், மூன்று காலங்களையும் கடந்தவன். நீ என்றும் மூலாதாரத்தில் நிலைத்திருக்கிறாய். நீ மூன்று சக்திகளின் வடிவம். யோகிகள் எப்போதும் உன்னைத் தியானிக்கிறார்கள். நீ பிரம்மா, விஷ்ணு, ருத்ரன், இந்திரன், அக்கினி, வாயு, சூரியன், சந்திரன்; நீயே பிரம்மம், பூர் புவஸ் ஸுவ, ஓம். ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.7': "“கண” என்ற சொல்லின் முதல் எழுத்தாகிய “க”வை முதலில் உச்சரித்து, பின்னர் எழுத்துகளின் முதலாகிய “அ”வையும், அதன்பின் அனுஸ்வாரத்தையும் உச்சரிக்க வேண்டும்; அர்த்தசந்திரனால் அழகுபெற்று ஓங்காரத்தால் சூழப்பட்ட இதுவே உன் மந்திர வடிவம். ககாரம் முன்வடிவம், அகாரம் நடுவடிவம், அனுஸ்வாரம் இறுதிவடிவம், பிந்து மேல்வடிவம், நாதம் இணைப்பு, சம்ஹிதை சந்தி. இதுவே கணேச வித்யை. ரிஷி கணகர், சந்தஸ் நிசிருத் காயத்ரி, தேவதை கணபதி: ஓம் கம் கணபதயே நமஹ. ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.8': "ஏகதந்தனை அறிகிறோம்; வக்ரதுண்டனைத் தியானிக்கிறோம்; அந்தத் தந்தி (யானை முகன்) எங்களைத் தூண்டட்டும். ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.9': "அவர் ஒற்றைக் கொம்புடையவர், நான்கு கைகள் கொண்டவர், பாசமும் அங்குசமும் ஏந்தியவர்; கைகளில் தந்தத்தையும் வரத முத்திரையையும் தாங்கியவர்; எலியே அவர் கொடி. சிவந்த நிறமுடையவர், பெருவயிறர், முறம் போன்ற காதுகள் உடையவர், செந்நிற ஆடை அணிந்தவர், செஞ்சந்தனம் பூசிய உறுப்புகளுடையவர், செம்மலர்களால் நன்கு பூஜிக்கப்படுபவர். பக்தர்களிடம் அருளுடைய தேவர், உலகின் காரணர், அச்யுதர், படைப்பின் தொடக்கத்தில் தோன்றியவர், பிரகிருதி புருஷர்களைக் கடந்தவர். இவ்வாறு நாள்தோறும் தியானிப்பவன் யோகிகளில் சிறந்த யோகி. ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '12.10': "வ்ராதபதிக்கு வணக்கம், கணபதிக்கு வணக்கம், பிரமதபதிக்கு வணக்கம். பெருவயிறனுக்கு, ஒற்றைக் கொம்பனுக்கு, தடைகளை அழிப்பவனுக்கு, சிவனின் மைந்தனுக்கு, வரம் அளிக்கும் வடிவினனுக்கு உனக்கு வணக்கம். ஸ்வாஹா; இது மஹாகணபதிக்கு, என்னுடையதல்ல.",
        '13.0': "ஓம் வ்ராதபதிக்கு நமஸ்காரம்; கணபதிக்கு நமஸ்காரம்; ப்ரமதபதிக்கு நமஸ்காரம். லம்போதரா, ஏகதந்தா, விக்னவிநாசா, சிவபுத்ரா, வரதமூர்த்தியே, உனக்குத் திரும்பத் திரும்ப நமஸ்காரம். (அதர்வசீர்ஷம் 10; மைலாப்பூர் நூலில் பூர்ணாஹுதிக்குப் பின்; தமிழ் கணபதி ஹோமத்தில் மூலமந்திரம்.)",
        '13.1': "அக்னியில் ஆவாஹனம் செய்த மஹாகணபதியை இதயத்தில் புகச்செய்கிறேன். (அவருக்கு அர்ப்பித்த மலரை முகர்ந்து)",
        '14.0': "ஓம் பூர்புவஸ்ஸுவ:; தெய்வீக ஸவிதாவின் சிறந்த ஒளியைத் தியானிக்கிறோம்; அவர் எங்கள் அறிவைத் தூண்டட்டும் (நைவேத்யத்தின் மேல் ப்ரோக்ஷணம்). ஸவிதா தேவனே, தூண்டுவாயாக. ஸத்யத்தை ருதத்தால் சுற்றித் தெளிக்கிறேன். நீ அமுதத்தின் விரிப்பு. ஓம் ப்ராண, அபான, வ்யான, உதான, ஸமானங்களுக்கும் ப்ரஹ்மத்துக்கும் ஸ்வாஹா (நைவேத்யத்தைக் காட்டி).",
        '14.1': "பல பக்ஷ்யங்கள், பல பழங்கள், பரமான்னம், தேன், நெய் கூடிய அறுசுவை இந்த நைவேத்யத்தை அன்புடன் ஏற்பாயாக. ஸ்ரீ மஹாகணபதிக்கு நமஸ்காரம்: மஹாநைவேத்யம் நிவேதிக்கிறேன்.",
        '14.2': "பாக்கும் கற்பூரத் தூளும் சேர்ந்த வெற்றிலையாலான இந்தத் தாம்பூலத்தை ஏற்றருள்வாய்.",
        '14.3': "சந்திரனும் சூரியனும், விண்மீன்களும், மின்னலும், அக்னியும் நீயே; எல்லா ஒளிகளும் நீயே; பிரபுவே, இந்த நீராஜனத்தை ஏற்பாயாக. ஸ்ரீ மஹாகணபதிக்கு நமஸ்காரம்: கற்பூர நீராஜனம் காட்டுகிறேன்.",
        '14.4': "நீரின் மலரை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். சந்திரனே நீரின் மலர்; இதை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். நீரின் ஆதாரத்தை அறிபவன் உறுதியான ஆதாரத்தைப் பெறுகிறான்.",
        '14.5': "வேதத்தின் தொடக்கத்தில் சொல்லப்பட்டு வேதாந்தத்தில் நிலைபெற்ற ஸ்வரம் — அதன் மூலத்தில் லயித்ததற்கும் அப்பாற்பட்டவனே மஹேச்வரன். (மஹாநாராயண உபநிஷத்) ஸ்ரீ மஹாகணபதிக்கு நமஸ்காரம்: மந்த்ரபுஷ்பாஞ்ஜலி ஸமர்ப்பிக்கிறேன்.",
        '14.6': "முற்பிறவிகளில் செய்த பாவங்கள் எவையோ அவை அனைத்தும் வலம் வரும் ஒவ்வொரு அடியிலும் அழியட்டும். பெரும் பாவங்கள் அழியவும் சிறந்த பலன் கிட்டவும் ஈசனே, வலம் வருகிறேன்; கணநாயகனே, அருள்வாயாக.",
        '14.7': "பூதகணங்களால் சேவிக்கப்படுபவரும், விளாம்பழம் நாவல்பழங்களின் சாரத்தை உண்பவரும், உமையின் மைந்தரும், துயர் நீக்கும் காரணருமான கஜானன விக்னேச்வரரின் திருவடித் தாமரைகளை வணங்குகிறேன். பார்வதியின் முகத்தாமரைக்குச் சூரியனானவரும், பக்தர்களுக்குப் பலவும் தருபவருமான ஏகதந்த கஜானனரை இரவும் பகலும் உபாஸிக்கிறோம். கணேசருக்கு மீண்டும் மீண்டும் நமஸ்காரம்; சிவனின் மைந்தனே, உமக்கு நமஸ்காரம்; என் விருப்பத்தை இடையூறின்றிச் செய்வீராக; கஜானனனே, உம்மை வணங்குகிறேன்.",
        '15.0': "ஸுமுக, ஏகதந்த, கபில, கஜகர்ணக, லம்போதர, விகட, விக்னராஜ, விநாயக, தூமகேது, கணாத்யக்ஷ, பாலசந்த்ர, கஜானன, வக்ரதுண்ட, சூர்ப்பகர்ண, ஹேரம்ப, ஸ்கந்தபூர்வஜர்களை (நீரால்) திருப்தி செய்கிறேன்.",
        '15.1': "இந்தக் கும்பத்தில் ஆவாஹனம் செய்த மஹாகணபதியை அவர் இடத்தில் ப்ரதிஷ்டை செய்கிறேன் — மங்கலத்துக்காக, நலனுக்காக, மீண்டும் வருவதற்காக.",
        '15.2': "அகால மரணத்தைப் போக்கும், எல்லா நோய்களையும் நீக்கும், எல்லாப் பாவங்களையும் அழிக்கும் மந்திரத்தால் தூய்மையான மங்கல நீர். (கும்ப நீரைத் தீர்த்தமாக அருந்தும்போது)",
        '16.0': "ஓ விநாயகா, எனக்கு ஆயுளையும் புகழையும் செல்வத்தையும் தா; ஓ கணநாயகா, மகன்களையும் பேரன்களையும் கொள்ளுப்பேரன்களையும் தா.",
      },
    },
    'navagraha-homa': {
      summary: "கிரகங்கள் காட்டும் துன்பங்களின் அமைதிக்காக நவக்ரஹ ஹோமம் தொடக்கம் முதல் முடிவு வரை: ஸங்கல்பம், அக்னிமுகம், க்ரஹமண்டலமும் ஆவாஹனமும், வ்யாஸரின் ஸ்தோத்திரத்தால் தியானம், ஒன்பது கிரகங்களுக்கும் முழு வைதிக மந்திரத்தால் (ரிக்வேத, தைத்திரீய வடிவங்கள்) அவற்றின் அதிதேவதை, ப்ரத்யதிதேவதைகளுக்கும் ஹோமம் — ஒவ்வொன்றின் ஸமித்து, நைவேத்யம், எண்ணிக்கையுடன், திக்பாலர் ஆஹுதிகள், க்ரஹ பூர்ணாஹுதியுடன் உத்தராங்கம், மத்ஸ்யபுராண ஶ்லோகங்களால் யஜமானனுக்கு அபிஷேகம், மந்திரத்துடன் நவதானங்கள், ஸ்தோத்திரங்கள், நிறைவு. மேலே மாத்வ/ஸ்மார்த்த, உங்கள் வேதத்தைத் தேர்ந்தெடுக்கவும்.",
      verses: {
        '0.0': "சூரியன், சந்திரன், செவ்வாய் (பூமிபுத்ரன்), புதன் (சந்திரபுத்ரன்), குரு, சுக்ரன், சனி, ராகு, கேது — இவர்களே கிரகங்கள் எனப்படுகின்றனர். (யாஜ்ஞவல்க்ய ஸ்ம்ருதி 1.296)",
        '0.1': "அர்கம் (எருக்கு), பலாசம், கதிரம், அபாமார்கம், பிப்பலம் (அரசு), உதும்பரம், சமீ, அருகு, தர்ப்பை — முறையே இவை ஸமித்துகள். (யாஜ்ஞவல்க்ய ஸ்ம்ருதி 1.302)",
        '0.2': "ஒவ்வொரு கிரகத்துக்கும் நூற்றெட்டு அல்லது இருபத்தெட்டு, தேன்–நெய், தயிர் அல்லது பாலுடன் சேர்த்து ஹோமம் செய்ய வேண்டும். (யாஜ்ஞவல்க்ய ஸ்ம்ருதி 1.303)",
        '1.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள் உறைபவனுமான ஹரிணீபதி ஶ்ரீபரசுராமனின் தூண்டுதலால், அவன் ப்ரீதிக்காக: என் ஜன்மராசி அல்லது நாமராசியிலிருந்து அநிஷ்ட ஸ்தானங்களில் உள்ள கிரகங்கள் காட்டும் தோஷங்களின் பரிகாரத்தின் மூலம், ஆதித்யாதி நவக்ரஹங்களுள் உறையும் ஶ்ரீராமாதி பகவத்ரூபங்களின் ப்ரீதிக்காக நவக்ரஹ ஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக ஸ்தண்டில ஸம்ஸ்காரம் செய்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '2.0': "நான் சேர்த்த எல்லாப் பாவங்களின் அழிவின் மூலம் பரமேஶ்வரனின் ப்ரீதிக்காக; என் ஜன்மராசி அல்லது நாமராசியிலிருந்து அநிஷ்ட ஸ்தானங்களில் உள்ள கிரகங்களின் எல்லா அரிஷ்டங்களும் நீங்கி நற்பலன் பெறுவதற்காக; ஆதித்யாதி நவக்ரஹ தேவதைகளின் அருள் கிட்டுவதற்காக நவக்ரஹ ஹோமம் செய்வேன்; அதன் அங்கமாக ஸ்தண்டிலத்தில் கோடுகள் வரைந்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '3.0': "அக்னிமுகம், ஆஜ்யபாகம் வரை. (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '4.0': "நடுவில் சூரியன், தெற்கில் செவ்வாய், வடக்கில் குரு, வடகிழக்கில் புதன் என்று அறிய வேண்டும். (மத்ஸ்யபுராணம் 93.11)",
        '4.1': "கிழக்கில் சுக்கிரன், தென்கிழக்கில் சந்திரன், மேற்கில் சனி, தென்மேற்கில் ராகு, வடமேற்கில் கேது — இவர்களை வெள்ளை அரிசியால் ஸ்தாபிக்க வேண்டும். (மத்ஸ்யபுராணம் 93.12)",
        '4.2': "சூரியனுக்கு ஈஶ்வரன், சந்திரனுக்கு உமா, செவ்வாய்க்கு ஸ்கந்தன், புதனுக்கு ஹரி அதிதேவதைகள் என்று அறிய வேண்டும். (மத்ஸ்யபுராணம் 93.13)",
        '4.3': "குருவுக்குப் பிரம்மா, சுக்கிரனுக்கு சசீபதி இந்திரன், சனிக்கு யமன், ராகுவுக்குக் காலன். (மத்ஸ்யபுராணம் 93.14)",
        '4.4': "கேதுவுக்குச் சித்ரகுப்தன் — இவர்களே அனைவரின் அதிதேவதைகள். அக்னி, நீர், பூமி, விஷ்ணு, இந்திரன், ஐந்த்ரீ (இந்திராணி)… (மத்ஸ்யபுராணம் 93.15)",
        '4.5': "…பிரஜாபதி, ஸர்ப்பங்கள், பிரம்மா ப்ரத்யதிதேவதைகள். விநாயகர், துர்கை, வாயு, ஆகாசம், அஶ்வினீகுமாரர்களையும் வ்யாஹ்ருதிகளால் ஆவாஹனம் செய்ய வேண்டும். (மத்ஸ்யபுராணம் 93.16)",
        '4.6': "ஓம் பூர்புவஃ ஸ்வஃ: அதிதேவதை, ப்ரத்யதிதேவதைகளுடன் கூடிய ஆதித்யாதி நவக்ரஹங்களை இந்த மண்டலத்தில் ஆவாஹனம் செய்கிறேன், ஸ்தாபிக்கிறேன், பூஜிக்கிறேன்.",
        '5.0': "செம்பருத்திப் பூப்போலச் சிவந்தவரும், கஶ்யபரின் மைந்தரும், பெரும் ஒளியுடையவரும், இருளின் பகைவரும், எல்லாப் பாவங்களையும் போக்குபவருமான திவாகரனை (சூரியனை) வணங்குகிறேன்.",
        '5.1': "தயிர், சங்கு, பனி போல வெண்மையானவரும், பாற்கடலில் தோன்றியவரும், ஶம்புவின் (சிவனின்) மகுடத்துக்கு அணியானவருமான சந்திரனை (ஸோமனை) வணங்குகிறேன்.",
        '5.2': "பூமியின் கருவில் தோன்றியவரும், மின்னலின் ஒளிபோல ஒளிர்பவரும், குமாரரும், கையில் ஶக்தி ஆயுதம் ஏந்தியவருமான மங்கலனை (செவ்வாயை) வணங்குகிறேன்.",
        '5.3': "ப்ரியங்கு மொட்டுப்போலப் பசுமை கலந்த கருநிறமுடையவரும், அழகில் இணையற்றவரும், ஸௌம்யரும் (ஸோமனின் மைந்தரும்), மென்மையான குணங்கள் உடையவருமான புதனை வணங்குகிறேன்.",
        '5.4': "தேவர்களுக்கும் ரிஷிகளுக்கும் குருவும், பொன்னிறமுடையவரும், அறிவின் வடிவமும், மூவுலகுக்கும் தலைவருமான பிருஹஸ்பதியை வணங்குகிறேன்.",
        '5.5': "பனி, குந்த மலர், தாமரைத் தண்டு போல வெண்மையானவரும், தைத்யர்களின் பரம குருவும், எல்லா ஶாஸ்திரங்களையும் உபதேசிப்பவருமான பார்கவரை (சுக்கிரனை) வணங்குகிறேன்.",
        '5.6': "கருநீல அஞ்சனம் போலத் தோன்றுபவரும், சூரியனின் மைந்தரும், யமனின் அண்ணனும், சாயா தேவிக்கும் மார்த்தாண்டனுக்கும் (சூரியனுக்கும்) பிறந்தவருமான ஶனைஶ்சரனை வணங்குகிறேன்.",
        '5.7': "பாதி உடல் உடையவரும், பெரும் வலிமையுடையவரும், (கிரகணங்களில்) சந்திர சூரியர்களை வருத்துபவரும், ஸிம்ஹிகையின் கருவில் தோன்றியவருமான ராகுவை வணங்குகிறேன்.",
        '5.8': "புரச மலர் போலச் சிவந்தவரும், நட்சத்திரங்களுக்கும் கிரஹங்களுக்கும் தலைபோன்றவரும், ரௌத்ரரும், ரௌத்ர இயல்புடையவரும், அச்சம் தருபவருமான கேதுவை வணங்குகிறேன்.",
        '5.9': "அதிதேவதை, ப்ரத்யதிதேவதைகளுடன் கூடிய ஆதித்யாதி நவக்ரஹ தேவதைகளுக்கு நமஸ்காரம். (ஒவ்வொரு உபசாரத்துடனும்: \"பாத்யம் ஸமர்ப்பயாமி\", \"அர்க்யம் ஸமர்ப்பயாமி\" முதலியன.)",
        '6.0': "எருக்கு, புரசு, கருங்காலி, நாயுருவி, அரசு, அத்தி, வன்னி, அருகு, தர்ப்பை — இவை முறையே ஸமித்துகள். (மத்ஸ்யபுராணம் 93.27)",
        '6.1': "ஒவ்வொரு கிரகத்துக்கும் நூற்றெட்டு அல்லது இருபத்தெட்டு, தேன், நெய், தயிருடன் சேர்த்து ஹோமம் செய்ய வேண்டும். (மத்ஸ்யபுராணம் 93.28)",
        '7.0': "இருண்ட வெளியில் சஞ்சரித்து, அமரரையும் மர்த்யரையும் அவரவர் இடத்தில் நிலைநிறுத்தி, ஸவிதா தேவன் எல்லா உலகங்களையும் பார்த்தபடி பொன் தேரில் வருகிறான். (ரிக்வேதம் 1.35.2; சூரியன்) ஸ்வாஹா; இது சூரியனுக்கு, என்னுடையதல்ல.",
        '7.1': "சத்திய வழியில் வானில் சஞ்சரித்து, அமரரையும் மனிதரையும் அவரவர் இடத்தில் நிலைநிறுத்தி, சவித்ருதேவன் உலகங்களைப் பார்த்தபடி பொன்னிற ரதத்தில் வருகிறான். (தைத்திரீய ஸம்ஹிதை 3.4.11; சூரியன்) ஸ்வாஹா; இது சூரியனுக்கு, என்னுடையதல்ல.",
        '7.2': "எல்லாம் அறிந்த ஹோதாவும் இந்த யஜ்ஞத்தை நன்கு நடத்துபவனுமான அக்னியைத் தூதனாகத் தேர்ந்தெடுக்கிறோம். (ரிக்வேதம் 1.12.1; சூரியனுடன் அக்னி) ஸ்வாஹா; இது அக்னிக்கு, என்னுடையதல்ல.",
        '7.3': "நாற்கால், இருகால் உயிர்களின் தலைவனான பசுபதிக்குரிய இந்த யஜ்ஞபாகம் அவனைச் சேரட்டும்; யஜமானனுக்குச் செல்வச் செழிப்பு உண்டாகட்டும். (தைத்திரீய ஸம்ஹிதை 3.1.4; சூரியனுடன் ருத்ரன்) ஸ்வாஹா; இது ருத்ரனுக்கு, என்னுடையதல்ல.",
        '8.0': "ஓ ஸோமனே, வளர்வாயாக; எல்லாத் திசைகளிலிருந்தும் உன்னிடம் வலிமை சேரட்டும்; உணவும் வலிமையும் பெறுமிடத்தில் நீ இருப்பாயாக. (ரிக்வேதம் 1.91.16; சந்திரன்) ஸ்வாஹா; இது சந்திரனுக்கு, என்னுடையதல்ல.",
        '8.1': "நீரில் எல்லா மருந்துகளும், அனைவருக்கும் நலம் தரும் அக்னியும், எல்லாவற்றையும் குணமாக்கும் நீர்களும் உள்ளன என்று ஸோமன் எனக்குச் சொன்னான். (ரிக்வேதம் 1.23.20; சந்திரனுடன் ஜலதேவதைகள்) ஸ்வாஹா; இது ஜலதேவதைகளுக்கு, என்னுடையதல்ல.",
        '8.2': "கௌரி நீர்களை உருவாக்கியபடி நாதம் செய்தாள்; அவள் ஒருபதம், இருபதம், நாற்பதம், எண்பதம், ஒன்பதம் உடையவளாகி உயர்ந்த வானில் ஆயிரம் அக்ஷரம் உடையவளானாள். (தைத்திரீய பிராம்மணம் 2.4.6, ரிக்வேதம் 1.164.41; சந்திரனுடன் கௌரி) ஸ்வாஹா; இது கௌரிக்கு, என்னுடையதல்ல.",
        '9.0': "அக்னி த்யுலோகத்தின் தலையும் சிகரமும், பூமியின் அதிபதி; அவன் நீர்களின் ரேதஸ்ஸை உயிர்ப்பிக்கிறான். (ரிக்வேதம் 8.44.16; செவ்வாய்) ஸ்வாஹா; இது அங்காரகனுக்கு, என்னுடையதல்ல.",
        '9.1': "ஓ பூமியே, எங்களுக்கு இன்பம் தருபவளாக, முள்ளற்றவளாக, உறைவிடமாக இருப்பாயாக; எங்களுக்குப் பரந்த அடைக்கலம் தருவாயாக. (ரிக்வேதம் 1.22.15; செவ்வாயுடன் பூமி) ஸ்வாஹா; இது பூமிதேவிக்கு, என்னுடையதல்ல.",
        '9.2': "க்ஷேத்ரபதியை நண்பனாகக் கொண்டு நாம் வெல்கிறோம்; நம் பசுக்களையும் குதிரைகளையும் போஷிக்கும் அவன் இவ்வாறே நமக்கு அருள்வானாக. (ரிக்வேதம் 4.57.1; செவ்வாயுடன் க்ஷேத்ரபாலர்) ஸ்வாஹா; இது க்ஷேத்ரபதிக்கு, என்னுடையதல்ல.",
        '10.0': "அக்னியே, விழித்தெழு, இவனைக் காப்பாயாக; நீயும் இவனும் சேர்ந்து இஷ்டாபூர்த்த கர்மங்களை நிறைவேற்றுங்கள்; உன்னை மீண்டும் இளைய தந்தையாக்கி இவன் இந்த இழையை உன்னில் விரித்துள்ளான். (தைத்திரீய ஸம்ஹிதை 4.7.13; புதன்) ஸ்வாஹா; இது புதனுக்கு, என்னுடையதல்ல.",
        '10.1': "விஷ்ணு இவை அனைத்தையும் அளந்தான்; மூன்று முறை அடி வைத்தான்; அவனுடைய தூசுநிறை அடியில் உலகம் அடங்கியுள்ளது. (ரிக்வேதம் 1.22.17; புதனுடன் விஷ்ணு) ஸ்வாஹா; இது விஷ்ணுவுக்கு, என்னுடையதல்ல.",
        '10.2': "நீ விஷ்ணுவின் நெற்றி, விஷ்ணுவின் முதுகு, விஷ்ணுவின் வாயின் இரு ஓரங்கள், விஷ்ணுவின் நூல், விஷ்ணுவின் நிலையான இடம்; நீ விஷ்ணுவுக்கு உரியவன்; உன்னை விஷ்ணுவுக்காக. (தைத்திரீய ஸம்ஹிதை 1.2.13; புதனுடன் ப்ரத்யதிதேவதை விஷ்ணு) ஸ்வாஹா; இது விஷ்ணுவுக்கு, என்னுடையதல்ல.",
        '11.0': "ஓ பிருஹஸ்பதியே, மக்களிடையே தகுதியில் மிகுந்து ஒளியுடனும் உறுதியுடனும் பிரகாசிப்பதும், ஸத்யத்தில் பிறந்த வலிமையால் ஒளிர்வதுமான அந்த அற்புதச் செல்வத்தை எங்களுக்குத் தா. (ரிக்வேதம் 2.23.15; குரு) ஸ்வாஹா; இது பிருஹஸ்பதிக்கு, என்னுடையதல்ல.",
        '11.1': "மருத்துகளுடன் கூடிய இந்திரனே, சார்யாதனிடம் ஸோமம் அருந்தியதுபோல் இங்கும் அருந்துவாயாக; ஓ வீரனே, உன் வழிகாட்டலில், உன் அடைக்கலத்தில் நன்கு யஜ்ஞம் செய்யும் கவிஞர்கள் உன்னை வழிபடுகின்றனர். (ரிக்வேதம் 3.51.7; குருவுடன் இந்திரன்) ஸ்வாஹா; இது இந்திரனுக்கு, என்னுடையதல்ல.",
        '11.2': "முதலில் கிழக்கில் தோன்றிய பிரம்மத்தை வேனன் ஒளிரும் எல்லையிலிருந்து திறந்து காட்டினான்; அதன் ஆழ்ந்த, அருகிலுள்ள வடிவங்களையும் சத், அசத் இரண்டின் தோற்றுவாயையும் வெளிப்படுத்தினான். (தைத்திரீய ஸம்ஹிதை 4.2.8; குருவுடன் பிரம்மா) ஸ்வாஹா; இது பிரம்மாவுக்கு, என்னுடையதல்ல.",
        '12.0': "உன் ஒரு வடிவம் ஒளிமிக்கது, மற்றொன்று வழிபடத்தக்கது; பகல், இரவு என்ற இரு வேறு வடிவுடைய வானம்போல் நீ இருக்கிறாய். ஓ ஸ்வதாவானே, எல்லா அற்புத சக்திகளையும் காக்கிறாய்; ஓ பூஷனே, உன் கொடை இங்கே மங்களமாகட்டும். (ரிக்வேதம் 6.58.1; சுக்கிரன்) ஸ்வாஹா; இது சுக்கிரனுக்கு, என்னுடையதல்ல.",
        '12.1': "ஒளிமிக்க, பிரகாசிக்கும் அக்னிக்கு ஹவிஸையும் நன்கு தூய்மையான துதியையும் கொண்டு வாருங்கள்; தேவர், மனிதர் ஆகியோரின் எல்லாப் பிறவிகளையும் உள்ளிருந்து அறிந்து அவன் அவர்களிடையே சஞ்சரிக்கிறான். (தைத்திரீய பிராம்மணம் 2.8.2; சுக்கிரன்) ஸ்வாஹா; இது சுக்கிரனுக்கு, என்னுடையதல்ல.",
        '12.2': "இந்தப் பெண்களுள் இந்திராணியே மிகப் பேறுபெற்றவள் என்று கேட்டிருக்கிறேன்; அவள் கணவன் முதுமையால் ஒருபோதும் இறப்பதில்லை; இந்திரன் அனைவரிலும் மேலானவன். (ரிக்வேதம் 10.86.11; சுக்கிரனுடன் இந்திராணி) ஸ்வாஹா; இது இந்திராணிக்கு, என்னுடையதல்ல.",
        '12.3': "இந்தப் பெண்களுள் இந்திராணியே சிறந்த கணவனை உடையவள் என்று கேட்டிருக்கிறேன்; அவள் கணவன் முதுமையால் ஒருபோதும் இறப்பதில்லை. (ரிக்வேதம் 10.86.11இன் நவக்ரஹ ஸூக்த பாடம்; சுக்கிரனுடன் இந்திராணி) ஸ்வாஹா; இது இந்திராணிக்கு, என்னுடையதல்ல.",
        '12.4': "எல்லா மக்களிடமிருந்தும் விலக்கி உங்களுக்காக இந்திரனை அழைக்கிறோம்; அவன் நமக்கே உரியவனாகட்டும். (ரிக்வேதம் 1.7.10; சுக்கிரனுடன் இந்திரன்) ஸ்வாஹா; இது இந்திரனுக்கு, என்னுடையதல்ல.",
        '13.0': "அக்னி தன் தீப்பிழம்புகளால் நமக்கு அமைதி தரட்டும்; சூரியன் நமக்கு நலமாகக் காயட்டும்; காற்று தீங்கின்றி வீசட்டும்; பகைவர் அகலட்டும். (ரிக்வேதம் 8.18.9; மாத்வ நூலின் சனி மந்திரம்) ஸ்வாஹா; இது சனைச்சரனுக்கு, என்னுடையதல்ல.",
        '13.1': "தெய்வ நீர்கள் எங்கள் நலனுக்கும் பருகுதலுக்கும் மங்கலமாகட்டும்; ஆரோக்கியத்துடனும் சுகத்துடனும் எங்களை நோக்கிப் பாயட்டும். (ரிக்வேதம் 10.9.4; சனி) ஸ்வாஹா; இது சனைச்சரனுக்கு, என்னுடையதல்ல.",
        '13.2': "ஓ பிரஜாபதியே, உன்னைத் தவிர வேறு எவரும் இந்தப் படைப்புகள் அனைத்தையும் சூழவில்லை; எந்த விருப்பத்துடன் உனக்கு ஹோமம் செய்கிறோமோ அது எமக்கு ஆகட்டும்; நாங்கள் செல்வங்களின் தலைவர்களாவோமாக. (ரிக்வேதம் 10.121.10; சனியுடன் பிரஜாபதி) ஸ்வாஹா; இது பிரஜாபதிக்கு, என்னுடையதல்ல.",
        '13.3': "ஓ யமனே, அங்கிரஸர்களுடனும் பித்ருக்களுடனும் இணங்கி இந்த விரித்த தர்ப்பையில் அமர்வாயாக; கவிகள் சொன்ன மந்திரங்கள் உன்னை அழைத்து வரட்டும்; ஓ அரசனே, இந்த ஹவிஸால் மகிழ்வாயாக. (ரிக்வேதம் 10.14.4; சனியுடன் யமன்) ஸ்வாஹா; இது யமனுக்கு, என்னுடையதல்ல.",
        '14.0': "எந்தக் காவலுடன், எந்த மிக வலிய பரிவாரத்துடன் அந்த அற்புதமான, எப்போதும் வளரும் நண்பன் எங்களிடம் வருவான்? (ரிக்வேதம் 4.31.1; கர்நாடக முறைகளின் ராகு மந்திரம்.) ஸ்வாஹா; இது ராகுவுக்கு, என்னுடையதல்ல.",
        '14.1': "இந்தப் புள்ளிகளுடைய காளை முன்வந்து தன் தாயின் முன் அமர்ந்துள்ளது, தந்தையான சுவர்க்கத்தை நோக்கிச் சென்றபடி. (ரிக்வேதம் 10.189.1, ஸர்ப்பராஜ்ஞியின் மந்திரம்; ராகுவுடன் ஸர்ப்பங்கள்) ஸ்வாஹா; இது சர்ப்பங்களுக்கு, என்னுடையதல்ல.",
        '14.2': "இந்தப் புள்ளிகளுடைய காளை முன்வந்து தன் தாயை மீண்டும் அடைந்துள்ளது, தந்தையான சுவர்க்கத்தை நோக்கிச் சென்றபடி. (தைத்திரீய ஸம்ஹிதை 1.5.3, ஸர்ப்பராஜ்ஞியின் மந்திரம்; ராகுவுடன் ஸர்ப்பங்கள்) ஸ்வாஹா; இது சர்ப்பங்களுக்கு, என்னுடையதல்ல.",
        '14.3': "நிர்ருதி தேவி உன் கழுத்தில் கட்டிய அவிழ்க்க முடியாத கட்டை நான் ஆயுளின் நடுவிலிருந்தே என்பதுபோல் அவிழ்க்கிறேன்; இப்போது விடுபட்டு ஊட்டம் தரும் உணவை உண்பாயாக. (தைத்திரீய ஸம்ஹிதை 4.2.5; ராகுவுடன் நிர்ருதி) ஸ்வாஹா; இது நிர்ருதிக்கு, என்னுடையதல்ல.",
        '15.0': "ஓ மனிதர்களே, ஒளியில்லாதவர்க்கு ஒளியையும் உருவமில்லாதவர்க்கு உருவத்தையும் தந்து நீ உஷைகளுடன் பிறந்தாய். (ரிக்வேதம் 1.6.3; கேது) ஸ்வாஹா; இது கேதுவுக்கு, என்னுடையதல்ல.",
        '15.1': "தேவர்களில் பிரம்மா, கவிகளில் வழிகாட்டி, விப்ரர்களில் ரிஷி, விலங்குகளில் எருமை, கழுகுகளில் ஶ்யேனம், மரங்களுக்குக் கோடரி — ஸோமன் ஒலித்தபடி பவித்ரத்தைக் கடக்கிறான். (ரிக்வேதம் 9.96.6; கேதுவுடன் பிரம்மா) ஸ்வாஹா; இது பிரம்மாவுக்கு, என்னுடையதல்ல.",
        '15.2': "ஓ அற்புதனே, அற்புத வலிமையுடையவனே, எமக்கு அற்புதமான, மிக ஒளிமிக்க, ஊக்கம் தரும் செல்வத்தைத் தருவாயாக; ஓ ஒளிர்பவனே, ஒளிரும் துதிகளால் உன்னைப் போற்றுபவனுக்கு வீரமக்களுடன் கூடிய பெரும் செல்வத்தை அருள்வாயாக. (ரிக்வேதம் 6.6.7; கேதுவுடன் சித்ரகுப்தன்) ஸ்வாஹா; இது சித்ரகுப்தனுக்கு, என்னுடையதல்ல.",
        '16.0': "விநாயகருக்கு ஸ்வாஹா; துர்கைக்கு ஸ்வாஹா; வாயுவுக்கு ஸ்வாஹா; ஆகாசத்துக்கு ஸ்வாஹா; அஶ்வினீ தேவர்களுக்கு ஸ்வாஹா. (மத்ஸ்யபுராணம் 93.16 கிரகங்களுடன் குறிப்பிடும் தேவதைகள்; ஒவ்வொன்றுக்கும் \"இதம் ந மம\" த்யாகம்.)",
        '16.1': "எட்டுத் திசைகளின் காவலர்களான இந்திரன், அக்னி, யமன், நிர்ருதி, வருணன், வாயு, குபேரன், ஈஶானன் ஆகியோருக்கு (கிழக்கு, தென்கிழக்கு, தெற்கு, தென்மேற்கு, மேற்கு, வடமேற்கு, வடக்கு, வடகிழக்கு) ஒவ்வொருவருக்கும் ஸ்வாஹா, த்யாகத்துடன்.",
        '17.0': "ஸ்விஷ்டக்ருத்தில் தொடங்கும் உத்தராங்கம். (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '17.1': "வானத்தின் தலையும், பூமியின் தூதனும், ருதத்தில் பிறந்தவனும், கவியும், சக்கரவர்த்தியும், மக்களின் விருந்தினனும், அவர்கள் வாய்க்குப் பாத்திரமுமான வைஶ்வானர அக்னியைத் தேவர்கள் தோற்றுவித்தனர். ஸ்வாஹா; இது வைஶ்வானர அக்னிக்கு, என்னுடையதல்ல. (ரிக்வேதம் 6.7.1; க்ரஹ ஹோமத்தின் பூர்ணாஹுதி, மத்ஸ்யபுராணம் 93.48)",
        '18.0': "ஓம், நாராயணனுக்கு நமஸ்காரம்; மங்கள நீராஜனத்தை (ஆரத்தியை) அர்ப்பிக்கிறேன்.",
        '18.1': "அங்கே ஸூர்யனோ சந்த்ர–நட்சத்திரங்களோ இந்த மின்னல்களோ ஒளிர்வதில்லை — இந்த நெருப்பு எப்படி? ஒளிரும் அவனைப் பின்பற்றியே எல்லாம் ஒளிர்கிறது; அவன் ஒளியாலேயே இவை அனைத்தும் விளங்குகின்றன. (கடோபநிஷத் 2.2.15; கற்பூர ஆரத்தியின்போது.)",
        '18.2': "கற்பூர நீராஜனம் காட்டுகிறேன்; நீராஜனத்திற்குப் பின் ஆசமனத்திற்கு நீர் அர்ப்பிக்கிறேன்.",
        '19.0': "தன் வலிமையால் வெல்லும் அரசர்க்கரசனான வைச்ரவணனை வணங்குகிறோம். விருப்பங்களின் தலைவனான அவன் ஏங்கும் எனக்கு என் விருப்பங்களை அருளட்டும். மகாராஜனான குபேர வைச்ரவணனுக்கு நமஸ்காரம்.",
        '19.1': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '19.2': "நீரின் மலரை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். சந்திரனே நீரின் மலர்; இதை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். நீரின் ஆதாரத்தை அறிபவன் உறுதியான ஆதாரத்தைப் பெறுகிறான்.",
        '19.3': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '20.0': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '20.1': "நான் செய்பவன் அல்லன், ஹரியே செய்பவன்; எல்லாச் செயலும் அவனுடைய பூஜையே. ஆயினும் நான் செய்த இந்தப் பூஜை அவன் அருளால்தான் நடந்தது, வேறு விதமாக அல்ல.",
        '20.2': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '21.0': "பிரம்மா, விஷ்ணு, மஹேஶ்வரன் ஆகிய தேவர்கள் உனக்கு அபிஷேகம் செய்யட்டும்; ஜகந்நாதனான வாஸுதேவன், விபுவான ஸங்கர்ஷணன், ப்ரத்யும்னன், அநிருத்தன் ஆகியோர் உன் வெற்றிக்கு இருக்கட்டும். (மத்ஸ்யபுராணம் 93.51)",
        '21.1': "இந்திரன், பகவான் அக்னி, யமன், நிர்ருதி, வருணன், வாயு, தனாத்யக்ஷன் குபேரன், சிவன், பிரம்மாவுடன் சேஷன் — இந்தத் திக்பாலர்கள் உன்னைக் காக்கட்டும். (மத்ஸ்யபுராணம் 93.52)",
        '21.2': "கீர்த்தி, லக்ஷ்மீ, த்ருதி, மேதா, புஷ்டி, ஶ்ரத்தா, க்ரியா, மதி, புத்தி, லஜ்ஜா, வபு, ஶாந்தி, துஷ்டி, காந்தி — தர்மனின் பத்தினிகளான இந்த மாதாக்கள் இங்கே கூடி உனக்கு அபிஷேகம் செய்யட்டும். (மத்ஸ்யபுராணம் 93.53)",
        '21.3': "சூரியன், சந்திரன், செவ்வாய், புதன், குரு, சுக்கிரன், சனி, ராகு, கேது — திருப்தியடைந்த இந்தக் கிரகங்கள் உனக்கு அபிஷேகம் செய்யட்டும். (மத்ஸ்யபுராணம் 93.54)",
        '22.0': "சூரியனுக்குக் கபிலப் பசு, சந்திரனுக்குச் சங்கு, செவ்வாய்க்குத் திமிலுடைய சிவப்புக் காளையைத் தானம் செய்ய வேண்டும். (மத்ஸ்யபுராணம் 93.60)",
        '22.1': "புதனுக்குப் பொன், குருவுக்கு மஞ்சள் ஆடை இணை, தைத்யகுருவான சுக்கிரனுக்கு வெள்ளைக் குதிரை, சூரியபுத்திரனான சனிக்குக் கருப்புப் பசு. (மத்ஸ்யபுராணம் 93.61)",
        '22.2': "ராகுவுக்கு இரும்பு, கேதுக்களுக்குச் சிறந்த ஆடு; யஜமானன் அதற்குச் சமமாகப் பொன் தக்ஷிணை தர வேண்டும். (மத்ஸ்யபுராணம் 93.62)",
        '22.3': "அல்லது அனைவருக்கும் பொன்னால் அலங்கரித்த பசுக்கள், அல்லது பொன், அல்லது குரு எதனால் மகிழ்வாரோ அதைத் தரலாம்; எல்லாத் தக்ஷிணைகளையும் மந்திரத்துடனேயே தர வேண்டும். (மத்ஸ்யபுராணம் 93.63)",
        '22.4': "ஓ கபிலையே, ரோஹிணியே, நீ எல்லாத் தேவர்களாலும் பூஜிக்கத்தக்கவள்; தீர்த்தங்களும் தேவர்களும் நிறைந்தவளாதலால் எனக்கு அமைதி தருவாயாக. (சூரியனுக்காகப் பசுதானம்) (மத்ஸ்யபுராணம் 93.64)",
        '22.5': "ஓ சங்கே, நீ புண்ணியங்களில் புண்ணியம், மங்களங்களில் மங்களம்; விஷ்ணு உன்னைத் தாங்கியுள்ளான்; ஆதலால் எனக்கு அமைதி தருவாயாக. (சந்திரனுக்காகச் சங்கு) (மத்ஸ்யபுராணம் 93.65)",
        '22.6': "உலகுக்கு ஆனந்தம் தருபவனே, நீ காளை வடிவில் தர்மம், அஷ்டமூர்த்தியான சிவனின் இருப்பிடம்; ஆதலால் எனக்கு அமைதி தருவாயாக. (செவ்வாய்க்காகக் காளை) (மத்ஸ்யபுராணம் 93.66)",
        '22.7': "நீ ஹிரண்யகர்ப்பனின் கருவில் உள்ள, அக்னியின் விதையான பொன், முடிவற்ற புண்ணியப் பலன் தருவது; ஆதலால் எனக்கு அமைதி தருவாயாக. (புதனுக்காகப் பொன்) (மத்ஸ்யபுராணம் 93.67)",
        '22.8': "மஞ்சள் ஆடை இணை வாஸுதேவனுக்கு உகந்தது ஆதலால், ஓ விஷ்ணுவே, அதன் தானத்தால் எனக்கு அமைதி தருவாயாக. (குருவுக்காக மஞ்சள் ஆடை) (மத்ஸ்யபுராணம் 93.68)",
        '22.9': "நீ குதிரை வடிவில் விஷ்ணு, அமுதத்திலிருந்து தோன்றியவன், எப்போதும் சந்திர சூரியரின் வாகனம்; ஆதலால் எனக்கு அமைதி தருவாயாக. (சுக்கிரனுக்காகக் குதிரை) (மத்ஸ்யபுராணம் 93.69)",
        '22.10': "ஓ பசுவே, நீ முழுப் பூமி, கேசவனைப் போன்றவள், எப்போதும் எல்லாப் பாவங்களையும் போக்குபவள்; ஆதலால் எனக்கு அமைதி தருவாயாக. (சனிக்காகக் கருப்புப் பசு) (மத்ஸ்யபுராணம் 93.70)",
        '22.11': "கலப்பை, ஆயுதங்கள் முதலிய இரும்பு வேலைகள் யாவும் எப்போதும் உன்னைச் சார்ந்தே இருப்பதால் எனக்கு அமைதி தருவாயாக. (ராகுவுக்காக இரும்பு) (மத்ஸ்யபுராணம் 93.71)",
        '22.12': "நீ எல்லா யஜ்ஞங்களுக்கும் அங்கமாக நிலைபெற்றவன், எப்போதும் அக்னியின் வாகனம்; ஆதலால் எனக்கு அமைதி தருவாயாக. (கேதுவுக்காக ஆடு) (மத்ஸ்யபுராணம் 93.72)",
        '23.0': "சூரியன் என்னுள் தத்துவத்தை ஒளிரச்செய்யட்டும்; சந்திரன் மகிழ்ச்சி தரட்டும்; செவ்வாய் மங்கலம் தரட்டும்; புதன் அறிவை அருளட்டும்.",
        '23.1': "குரு பெருமையைத் தரட்டும்; சுக்ரன் கவித்திறனைத் தரட்டும்; சனி நலம் தரட்டும்; கேது என் வெற்றிக் கொடியை ஏற்றட்டும்.",
        '23.2': "ராகு என் நோயை நீக்கட்டும்; எல்லாக் கிரகங்களும் கைகொடுத்துத் தூக்கட்டும்; இந்த நவக்கிரகங்கள் எனக்குப் புதிது புதிதாக ஐஸ்வர்யம் அருளட்டும்.",
        '23.3': "ஓ சூரியபுத்ரனான சனியே, எண்ணற்ற குணங்களின் மணியே, என் அரிஷ்டத்தை நீக்கு, விருப்பத்தைத் தா, துன்பம் தராதே.",
        '23.4': "ஹரியின் அனுக்கிரகத்துக்காகவும் எதிரிகளை அடக்கவும் ஸ்ரீவாதிராஜ யதிகள் கூறிய இந்தக் கிரக ஸ்தோத்திரத்தை எப்போதும் ஓத வேண்டும்.",
        '23.5': "கிரக வரிசையில் பசு, சங்கு, காளை, பொன், ஆடை, குதிரை, கருப்புப் பசு, இரும்பு, ஆடு — இவையே தக்ஷிணைகள் எனப்படுகின்றன. (யாஜ்ஞவல்க்ய ஸ்ம்ருதி 1.306)",
        '24.0': "எவனை நினைப்பதாலும் எவன் நாமத்தைச் சொல்வதாலும் தவம், பூஜை, கர்மங்களில் உள்ள குறை உடனே நிறைவடைகிறதோ அந்த அச்யுதனை வணங்குகிறேன்.",
        '24.1': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '24.2': "இந்த நவக்ரஹ ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள்ளும் ஆதித்யாதி நவக்ரஹங்களுள்ளும் உறைபவனுமான ஶ்ரீலக்ஷ்மீந்ருஸிம்ஹன் மகிழ்வானாக. ஶ்ரீக்ருஷ்ணார்ப்பணமஸ்து.",
        '24.3': "தேவாசுரர்களால் வணங்கப்படும் தேவ ஸ்ரேஷ்டரே, செல்லுங்கள்; ஓ ஹுதாசனனே, பிரம்மாதி தேவர்கள் இருக்கும் இடத்திற்குச் செல்.",
        '24.4': "உன்னை அழைக்கும் முறையோ, விடைகொடுக்கும் முறையோ, வழிபடும் முறையோ நான் அறியேன்; பரமேச்வரா, பொறுத்தருள்.",
        '24.5': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '24.6': "இந்த நவக்ரஹ ஹோம கர்மத்தால் அதிதேவதை, ப்ரத்யதிதேவதைகளுடன் கூடிய ஆதித்யாதி நவக்ரஹ தேவதைகள் மகிழட்டும். ஓம் தத்ஸத், பிரம்மத்துக்கு அர்ப்பணமாகட்டும்.",
      },
    },
    'mrityunjaya-homa': {
      summary: "ஜன்மநக்ஷத்திரம், பிறந்தநாள், நோய் அல்லது அகால மரண பயத்தில் செய்யும் ம்ருத்யுஞ்ஜய ஹோமம் தொடக்கம் முதல் முடிவு வரை: ஸங்கல்பம், அக்னிமுகம், கலசத்தில் ம்ருத்யுஞ்ஜயனின் தியானமும் ஆவாஹனமும், த்ர்யம்பக ஹோமம் (மாத்வ: ப்ரணவ வ்யாஹ்ருதி ஸம்புடிதம், தேன்–நெய்–தயிரில் தோய்த்த அருகுடன்; ஸ்மார்த்த: ஆறு ஸமித்துகள், பாயஸம், நெய், எள்) — 28, 108 அல்லது 1000 எண்ணிக்கை, ருத்ர மந்திரங்கள், உத்தராங்கம், உத்தரபூஜை, கலச நீர் ப்ரோக்ஷணம், தீர்த்தப் பிரசாதம், ஸமர்ப்பணம்.",
      verses: {
        '0.0': "தேன், நெய், தயிர் கலந்த அருகம்புல்லை ம்ருத்யுஞ்ஜய மந்திரத்தால் ஆயிரம் முறை அல்லது இருபத்தெட்டு ஆஹுதிகள் ஹோமம் செய்ய வேண்டும். (ப்ரயோகபாரிஜாதம், ஹோம–ஹவனத்தில் மேற்கோள்)",
        '0.1': "ஆயுள் வளர தினமும் அல்லது ஜன்ம நட்சத்திரத்தில், பால்–நெய்யில் தோய்த்த நான்கு நான்கு அருகம்புல்லால் ஹோமம் செய்யப்படுகிறது. (தந்த்ரஸாரஸங்க்ரஹம் 4.102)",
        '0.2': "பத்தாயிரம் அம்ருதா (சீந்தில்) ஸமித்துகளைப் பசுநெய்–பாலுடன் ஹோமம் செய்தால், ஹரியிடமிருந்து விமுகன் ஆகாதவனுக்கு எல்லா நோய்களும் அழியும். (தந்த்ரஸாரஸங்க்ரஹம் 4.100)",
        '1.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள் உறைபவனுமான ஹரிணீபதி ஶ்ரீபரசுராமனின் தூண்டுதலால், அவன் ப்ரீதிக்காக: என் அகால மரண தோஷம் நீங்கி ஆரோக்கியத்துடன் கூடிய நீண்ட ஆயுள் பெறுவதற்காக, ம்ருத்யுஞ்ஜய ருத்ரனுள் உறையும் ஶ்ரீஸங்கர்ஷணனின் ப்ரீதிக்காக ம்ருத்யுஞ்ஜய ஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக ஸ்தண்டில ஸம்ஸ்காரம் செய்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '2.0': "நான் சேர்த்த எல்லாப் பாவங்களின் அழிவின் மூலம் பரமேஶ்வரனின் ப்ரீதிக்காக; அகால மரண தோஷம் நீங்கி ஆரோக்கியத்துடன் கூடிய நீண்ட ஆயுள் பெறுவதற்காக; ஶ்ரீம்ருத்யுஞ்ஜயனின் அருள் கிட்டுவதற்காக ம்ருத்யுஞ்ஜய ஹோமம் செய்வேன்; அதன் அங்கமாக ஸ்தண்டிலத்தில் கோடுகள் வரைந்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '3.0': "அக்னிமுகம், ஆஜ்யபாகம் வரை. (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '4.0': "நாடியதையும் நிலையான பதத்தையும் அடைய, உபாசகன் ஒரே இறைவனான சிவனைத் தியானிக்கட்டும்: பாதாளம் முதல் வானம் வரை எல்லா உலகங்களிலும் ஒளி வீசும், தலைமேல் உள்ள முழுநிலவிலிருந்து பெருகும் அமுதத்தால் நிறைவாக நீராட்டப்படும் ஸ்படிக லிங்கம்; ருத்ர அனுவாகங்களை இடையறாது ஓதியவாறு சிவனுக்கு அபிஷேகம் செய்யட்டும்.",
        '4.1': "ஓம் பூர்புவஃ ஸ்வஃ: ஶ்ரீம்ருத்யுஞ்ஜயனை இந்தக் கலசத்தில் ஆவாஹனம் செய்கிறேன், ஸ்தாபிக்கிறேன், பூஜிக்கிறேன்.",
        '4.2': "ஓம், பகவான் ருத்திரனுக்கு நமஸ்காரம்.",
        '5.0': "ஓம் பூர்புவஃ ஸ்வஃ. மூன்று கண்களுடைய, நறுமணமுள்ள, ஊட்டம் பெருக்கும் தேவனை வழிபடுகிறோம்; பழுத்த வெள்ளரி காம்பிலிருந்து விடுபடுவதுபோல் நான் மரணத்திலிருந்து விடுபடுவேனாக, அமிர்தத்திலிருந்து அல்ல. ஸ்வர்புவர்பூஃ ஓம். ஸ்வாஹா; இது ம்ருத்யுஞ்ஜய ருத்ரனுள், பாரதீரமண முக்யப்ராணனுள் உறையும் ஶ்ரீஸங்கர்ஷணனுக்கு, என்னுடையதல்ல. (ரிக்வேதம் 7.59.12, ஹோம–ஹவனம் சொல்வதுபோல் ப்ரணவ வ்யாஹ்ருதிகளால் ஸம்புடிதம்)",
        '5.1': "மூன்று கண்களுடைய, நறுமணம் கொண்ட, புஷ்டியை வளர்க்கும் தேவனை வழிபடுகிறோம்; பழுத்த வெள்ளரிக்காய் காம்பிலிருந்து விடுபடுவது போல நான் ம்ருத்யுவிலிருந்து விடுபடுவேனாக, அமரத்துவத்திலிருந்து அல்ல, ஸ்வாஹா. இது ருத்ரனுக்கு, என்னுடையதன்று. (ரிக்வேதம் 7.59.12)",
        '6.0': "மரணமே, மனிதரை வதைக்க நீ விரிக்கும் ஆயிரம், பத்தாயிரம் கண்ணிகள் அனைத்தையும் யாகத்தின் ஆற்றலால் அகற்றுகிறோம். மரணத்துக்கு ஸ்வாஹா! மரணத்துக்கு ஸ்வாஹா!",
        '6.1': "அக்னியிலும் நீரிலும் செடிகளிலும் உள்ள, எல்லா உலகங்களிலும் நுழைந்துள்ள அந்த ருத்திரனுக்கு நமஸ்காரம்.",
        '6.2': "நல்ல அம்புகளும் நல்ல வில்லும் உடையவனும் எல்லா மருந்துகளையும் ஆள்பவனுமானவனைப் போற்றுங்கள். அவன் பெரும் கருணைக்காக ருத்திரனை வழிபடுங்கள்; வலிய திவ்ய இறைவனை நமஸ்காரங்களால் போற்றுங்கள்.",
        '6.3': "ஓம், பகவான் ருத்திரனுக்கு, விஷ்ணுவுக்கு நமஸ்காரம்: மரணத்திலிருந்து என்னைக் காப்பாய்.",
        '6.4': "நீ உயிர்மூச்சுகளை ஒன்றாகப் பிணைக்கும் முடிச்சு. அந்தகனான ருத்ரனே, (மரணமாக) என்னுள் புகாதே. இந்த அன்னத்தால் நிறைவு பெறுவாயாக.",
        '6.5': "ருத்திரனுக்கு, விஷ்ணுவுக்கு நமஸ்காரம்: மரணத்திலிருந்து என்னைக் காப்பாய். ஸதாசிவ ஓம்.",
        '7.0': "ஸ்விஷ்டக்ருத்தில் தொடங்கும் உத்தராங்கம். (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '8.0': "ஓம், நாராயணனுக்கு நமஸ்காரம்; மங்கள நீராஜனத்தை (ஆரத்தியை) அர்ப்பிக்கிறேன்.",
        '8.1': "அங்கே ஸூர்யனோ சந்த்ர–நட்சத்திரங்களோ இந்த மின்னல்களோ ஒளிர்வதில்லை — இந்த நெருப்பு எப்படி? ஒளிரும் அவனைப் பின்பற்றியே எல்லாம் ஒளிர்கிறது; அவன் ஒளியாலேயே இவை அனைத்தும் விளங்குகின்றன. (கடோபநிஷத் 2.2.15; கற்பூர ஆரத்தியின்போது.)",
        '8.2': "கற்பூர நீராஜனம் காட்டுகிறேன்; நீராஜனத்திற்குப் பின் ஆசமனத்திற்கு நீர் அர்ப்பிக்கிறேன்.",
        '9.0': "தன் வலிமையால் வெல்லும் அரசர்க்கரசனான வைச்ரவணனை வணங்குகிறோம். விருப்பங்களின் தலைவனான அவன் ஏங்கும் எனக்கு என் விருப்பங்களை அருளட்டும். மகாராஜனான குபேர வைச்ரவணனுக்கு நமஸ்காரம்.",
        '9.1': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '9.2': "நீரின் மலரை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். சந்திரனே நீரின் மலர்; இதை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். நீரின் ஆதாரத்தை அறிபவன் உறுதியான ஆதாரத்தைப் பெறுகிறான்.",
        '9.3': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '10.0': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '10.1': "நான் செய்பவன் அல்லன், ஹரியே செய்பவன்; எல்லாச் செயலும் அவனுடைய பூஜையே. ஆயினும் நான் செய்த இந்தப் பூஜை அவன் அருளால்தான் நடந்தது, வேறு விதமாக அல்ல.",
        '10.2': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '11.0': "நறுமணம் கமழ்பவனும், எல்லா உயிர்களையும் போஷித்து வளர்ப்பவனுமான முக்கண்ணனை வழிபடுகிறோம். பழுத்த வெள்ளரிக்காய் காம்பிலிருந்து விடுபடுவது போல், அவன் எங்களை மரணத்திலிருந்து விடுவிக்கட்டும்; அமரத்துவத்திலிருந்து அல்ல.",
        '11.1': "எங்கள் பிள்ளைகளுக்கும் பேரர்களுக்கும், எங்கள் ஆயுளுக்கும், எங்கள் பசுக்களுக்கும் குதிரைகளுக்கும் தீங்கு செய்யாதே. ஓ ருத்ரனே, கோபத்தில் எங்கள் வீரர்களைக் கொல்லாதே; ஹவிஸ்ஸுடன் நாங்கள் எப்போதும் உன்னை அழைக்கிறோம். (ரிக்வேதம் 1.114.8)",
        '11.2': "அகால மரணத்தை நீக்குவதும், எல்லா நோய்களையும் அழிப்பதுமான, விஷ்ணுவின் பாதங்களைக் கழுவிய இந்தத் தீர்த்தத்தை நான் உட்கொள்கிறேன்.",
        '11.3': "மார்க்கண்டேயரிடமிருந்து வரம் பெற்று, ஆயுள் வளர எள்–வெல்லம் கலந்த அரை அஞ்சலி பாலைப் பருகுகிறேன். (பிரதக்ஷிண–நமஸ்காரங்களுக்குப் பின் பால் பருகும்போது.)",
        '12.0': "எவனை நினைப்பதாலும் எவன் நாமத்தைச் சொல்வதாலும் தவம், பூஜை, கர்மங்களில் உள்ள குறை உடனே நிறைவடைகிறதோ அந்த அச்யுதனை வணங்குகிறேன்.",
        '12.1': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '12.2': "இந்த ம்ருத்யுஞ்ஜய ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள்ளும் ம்ருத்யுஞ்ஜய ருத்ரனுள்ளும் உறைபவனுமான ஶ்ரீஸங்கர்ஷணன் மகிழ்வானாக. ஶ்ரீக்ருஷ்ணார்ப்பணமஸ்து.",
        '12.3': "தேவாசுரர்களால் வணங்கப்படும் தேவ ஸ்ரேஷ்டரே, செல்லுங்கள்; ஓ ஹுதாசனனே, பிரம்மாதி தேவர்கள் இருக்கும் இடத்திற்குச் செல்.",
        '12.4': "உன்னை அழைக்கும் முறையோ, விடைகொடுக்கும் முறையோ, வழிபடும் முறையோ நான் அறியேன்; பரமேச்வரா, பொறுத்தருள்.",
        '12.5': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '12.6': "இந்த ம்ருத்யுஞ்ஜய ஹோம கர்மத்தால் ஶ்ரீம்ருத்யுஞ்ஜயன் மகிழ்வானாக. ஓம் தத்ஸத், பிரம்மத்துக்கு அர்ப்பணமாகட்டும்.",
      },
    },
    'sudarshana-homa': {
      summary: "வீட்டின் காவல், அபிசார நிவர்த்தி, வைஷ்ணவ முத்ராதாரணத்துக்காக ஸுதர்சன ஹோமம் தொடக்கம் முதல் இறுதி வரை: த்ரவ்யங்களும் எண்ணிக்கையும் (எட்டு த்ரவ்யங்கள், ஒவ்வொன்றாலும் 126), ஸங்கல்பம், ஆசார்ய ப்ரஹ்ம வரணம், யந்த்ரம், தியானம், ஸுதர்சன மந்திர ஜபம், பொது முறையிலிருந்து அக்னிமுகம், பீட தேவதா ஹோமம், பிரதான ஆஹுதிகள், ஆவரண தேவதா ஹோமம், பலி, பழத்துடன் பூர்ணாஹுதி, கலச நீரால் யஜமான அபிஷேகம், தானங்கள், ரக்ஷை, ஸமர்ப்பணம்.",
      verses: {
        '0.0': "மகாஜ்வாலை கொண்ட, கோடி சூரிய ஒளியுடைய ஓ ஸுதர்சனா, அறியாமையால் குருடனான எனக்கு எப்போதும் விஷ்ணுவின் வழியைக் காட்டு. (பிரார்த்தனை, ஹோம–ஹவனம்)",
        '1.0': "என், என் குடும்பம், வீட்டின் காவலுக்காக; பகைவர் செய்த துர்மந்திர உபத்ரவங்களை வேரோடு அழித்து எல்லாப் பகைவரும் ஓட; எல்லா க்ரஹபாதைகளும் நீங்க; ச்ருதி ஸ்ம்ருதி ஆகம புராணங்களில் சொன்ன பலன் பெற; எல்லாப் பாவங்களும் நீங்கி நான்கு புருஷார்த்தங்களும் கிட்டுவதன் மூலம் எல்லாத் தேவதைகளும் ஆன ஸ்ரீ மஹாஸுதர்சனரின் ப்ரீதிக்காக, இயன்ற த்ரவ்யங்களாலும் உபசாரங்களாலும் பாஞ்சராத்ர ஆகம விதிப்படி ஸ்ரீ மஹாஸுதர்சன ஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக ஸ்வஸ்தி புண்யாஹவாசனமும் ஆசார்யாதி வரணமும் செய்வேன்.",
        '2.0': "ப்ருஹஸ்பதியே, சிறந்தோருக்குத் தகுந்த, மக்களிடையே ஒளியாலும் ஆற்றலாலும் ஒளிர்வதும் வலிமையால் சுடர்வதுமான செல்வத்தை, ருதத்திலிருந்து பிறந்தவனே, எங்களுக்குத் தருவாயாக. (ருக்வேதம் 2.23.15) விண்ணில் இந்திரன் முதலியோருக்கு ப்ருஹஸ்பதி ஆசார்யனாக இருப்பதுபோல், நல்விரதம் உடையவரே, இந்த மஹாஸுதர்சன ஹோமத்தில் ஆசார்யனாக இருப்பீராக.",
        '2.1': "மந்திரத்தால் பூட்டப்படும், மகிழ்ச்சியில் தோழர்களான உன் இரு விரைவுக் குதிரைகளை மந்திரத்தால் பூட்டுகிறேன்; இந்திரனே, உறுதியான இனிய ரதத்தில் ஏறி, அறிந்தவனாக ஸோமத்திடம் வருவாயாக. (ருக்வேதம் 3.35.4; ப்ரஹ்ம வரணத்தில்)",
        '3.0': "மத்தியான சூரியனைப் போல ஒளிரும், பழுப்பு முடியுடைய, மின்னும் பெருஞ்சிரிப்புடைய, மூன்று கண்ணுடைய, சுடரும் ஆடை அணிந்த, சக்கரத்தில் நிலைத்த, சக்கரம் ஏந்திய, எட்டுத் தோளுடைய முதன்மையானவரைத் துதிக்கிறேன்.",
        '3.1': "சங்கு, சக்கரம், கதை, தாமரை, பெருஞ்சுளகு, வில், பாசம், அங்குசம் முதலியவற்றைக் கைகளில் ஏந்திய முராரி சக்ரராஜனை மனத்தில் த்யானிக்கிறேன்.",
        '3.2': "எல்லாச் செயல்களும் கைகூட, சங்கு சக்கரம் வரம் அபயம் கொண்ட நான்கு கை தேவனான வீர ஸுதர்சனரைத் தியானிக்க வேண்டும். ஸுதர்சனரே, உமக்கு நமஸ்காரம்; பகைவரை அழிப்பவரே, உமக்கு நமஸ்காரம்; உபசாரங்களால் உம்மை அர்ச்சிக்கிறேன்; விஷ்ணு வடிவான உமக்கு நமஸ்காரம். (ஜப தியானம்)",
        '3.3': "ஓம் நாங்கள் ஸுதர்சனனை அறிகிறோம்; ஆயுதராஜனைத் த்யானிக்கிறோம்; அச்சக்கரம் எங்களைத் தூண்டட்டும். (ஸுதர்சன காயத்ரி, ஸ்ரீமஹாஸுதர்சன கல்பம்)",
        '3.4': "ஓம் ஓ ஸஹஸ்ராரா, ஹும் பட் ஸ்வாஹா. (ஸுதர்சனரின் சுருக்கமான அஸ்த்ர மந்திரம், ஸ்ரீமஹாஸுதர்சன கல்பம்.)",
        '4.0': "இவ்வாறு பூர்வாங்கம் (பொது முறையிலிருந்து).",
        '5.0': "ஓம் மம் மண்டூக பீடத்துக்கு ஸ்வாஹா; ஓம் கம் காலாக்னிருத்ர பீடத்துக்கு ஸ்வாஹா; ஓம் ஆம் ஆதாரசக்தி பீடத்துக்கு ஸ்வாஹா; ஓம் தம் தரா பீடத்துக்கு ஸ்வாஹா; ஓம் ஸம் ஸுதாஸிந்து பீடத்துக்கு ஸ்வாஹா. (பீட தேவதா ஆஹுதிகளின் தொடக்கம்)",
        '6.0': "மத்தியான சூரியனைப் போல ஒளிரும், பழுப்பு முடியுடைய, மின்னும் பெருஞ்சிரிப்புடைய, மூன்று கண்ணுடைய, சுடரும் ஆடை அணிந்த, சக்கரத்தில் நிலைத்த, சக்கரம் ஏந்திய, எட்டுத் தோளுடைய முதன்மையானவரைத் துதிக்கிறேன்.",
        '6.1': "சங்கு, சக்கரம், கதை, தாமரை, பெருஞ்சுளகு, வில், பாசம், அங்குசம் முதலியவற்றைக் கைகளில் ஏந்திய முராரி சக்ரராஜனை மனத்தில் த்யானிக்கிறேன்.",
        '6.2': "ஓம் நாங்கள் ஸுதர்சனனை அறிகிறோம்; ஆயுதராஜனைத் த்யானிக்கிறோம்; அச்சக்கரம் எங்களைத் தூண்டட்டும். (ஸுதர்சன காயத்ரி, ஸ்ரீமஹாஸுதர்சன கல்பம்)",
        '6.3': "ஓம், ஆயிரம் ஆரங்கள் உடையவனே, ஹும் பட் ஸ்வாஹா; இது ஸ்ரீ ஸுதர்சனருக்கு, என்னுடையதல்ல. (கல்பத்தின் ஸுதர்சன அஷ்டாக்ஷர மந்திரம்; குருவிடம் மூல/மாலா மந்திரம் பெறாதவர்கள் இதனால் ஆஹுதி அளிக்கிறார்கள்: கொடுத்த வரிசையில் எட்டு த்ரவ்யங்களில் ஒவ்வொன்றாலும் 126 — நெய், நாயுருவி ஸமித், எள், கடுகு, பாயஸம், பஞ்சகவ்யம், அரிசி அல்லது பொரி, மீண்டும் நெய் — மொத்தம் 1008.)",
        '7.0': "ஓம் ஸ்ரீ ஸுதர்சனருக்கு ஸ்வாஹா; ஆசக்ர, விசக்ர, ஸுசக்ர, தீசக்ர, ஸஞ்சக்ர, ஜ்வாலாசக்ர (சக்கரத்தின் ஆறு அங்கங்கள்) — ஒவ்வொன்றுக்கும் ஸ்வாஹா. (கல்பத்தில் ஒவ்வொன்றுக்கும் பீஜாக்ஷரம்.)",
        '7.1': "ஓம் சக்கரம், சங்கு, கதை, தாமரை, உலக்கை, வில், பாசம், அங்குசம் ஆகியவற்றுக்கு ஸ்வாஹா. (தியானத்தின் எட்டு ஆயுதங்கள்.)",
        '7.2': "ஓம் இந்திரன், அக்னி, யமன், நிர்ருதி, வருணன், வாயு, குபேரன், ஈசானன், ப்ரஹ்மா (மேலே), அனந்தன் (கீழே) — இவர்களுக்கு ஸ்வாஹா. (பத்துத் திசைக் காவலர்கள்)",
        '8.0': "ஓம், அங்கம் ஆயுதம் பரிவாரம் சக்திகளுடன் கூடிய பகவான் மஹாஸுதர்சனருக்கு நமஸ்காரம்: இந்தப் பாயஸ பலியை ஏற்பீராக; எனக்கு ஆயுள், சாந்தி, புஷ்டி, நலம் தருபவராகவும் எல்லாப் பகைவரையும் அழிப்பவராகவும் வரம் தருபவராகவும் ஆவீராக. இந்த பலிதானத்தால் மஹாஸுதர்சனர் ப்ரீதியடையட்டும்.",
        '8.1': "தேவர்கள், ஆதித்யர்கள், வஸுக்கள், மருத்துகள், அச்வினிகள், ருத்ரர்கள், ஸுபர்ணர்கள், பன்னகர்கள், பறவைகள்; அஸுரர்கள், யாதுதானர்கள், பிசாச உரக ராக்ஷஸர்கள்; டாகினிகள், யக்ஷ வேதாளர்கள், யோகினிகள், பூதனைகள், சிவைகள்; ஜ்ரும்பகர்கள், ஸித்த கந்தர்வர்கள், நாகர்கள், வித்யாதரர்கள், மலைகள்; திக்பாலகர்கள், லோகபாலகர்கள், விக்ன விநாயகர்கள்; உலகுக்கு அமைதி தரும் ப்ரஹ்மா முதலிய மஹர்ஷிகள் — இந்த பலியை ஏற்கட்டும். இடையூறு இல்லாதிருக்கட்டும், எனக்குப் பாவம் இல்லாதிருக்கட்டும், பகைவர் இல்லாதிருக்கட்டும்; பூதப்ரேதங்கள் சாந்தமாகவும் திருப்தியாகவும் இன்பம் தருபவையாகவும் ஆகட்டும்.",
        '8.2': "பூமி அமைதியாக இருக்கட்டும், அந்தரிக்ஷம் மங்கலமாக இருக்கட்டும்; தெய்வ த்யுலோகம் எங்களுக்கு அபயம் தரட்டும்; திசைகள், உபதிசைகள், நீர்கள், மின்னல்கள் இனிதாக எல்லாப் பக்கமும் எங்களைக் காக்கட்டும். சாந்தி: சாந்தி: சாந்தி:. (ஸுதர்சன கல்பத்தில் உள்ளபடி.)",
        '9.0': "காய்க்கும், காய்க்காத, பூக்காத, பூக்கும், ப்ருஹஸ்பதியால் தூண்டப்பட்ட மூலிகைகள் எங்களைத் துயரிலிருந்து விடுவிக்கட்டும், ஸ்வாஹா. (ருக்வேதம் 10.97.15; இதனால் முழுப் பழம் அர்ப்பிக்கப்படுகிறது.)",
        '9.1': "ஆவாஹனம் செய்த தேவதைகள் ப்ரீதியடையட்டும். (அக்ஷதை நீர் விட்டு, விடைகொடுப்பதற்கு முன்)",
        '10.0': "ப்ரஹ்மா, விஷ்ணு, மஹேச்வரர் ஆகிய தேவர்கள் உனக்கு அபிஷேகம் செய்யட்டும்; ஜகன்னாதரான வாஸுதேவர், விபுவான ஸங்கர்ஷணர், ப்ரத்யும்னர், அநிருத்தர் உன் வெற்றிக்காக இருக்கட்டும்; இந்திரன், பகவான் அக்னி, யமன், நிர்ருதி, வருணன், வாயு, குபேரன், சிவன் — ப்ரஹ்மாவுடன் எல்லாத் திக்பாலகர்களும் உன்னை எப்போதும் காக்கட்டும்; ஸூர்யன், சந்திரன், அங்காரகன், புதன், குரு, சுக்ரன், சனி, ராகு, கேது ஆகிய க்ரஹங்கள் பூஜிக்கப்பட்டு உனக்கு அபிஷேகம் செய்யட்டும். (கிழக்கு நோக்கி அமர்ந்த யஜமான தம்பதியர் மேல் ஆசார்யரும் ருத்விக்குகளும் பிரதான கலச நீரை அருகம்புல் மாவிலையால் தெளிக்கும்போது)",
        '11.0': "இந்த மஹாஸுதர்சன ஹோம கர்மத்தால் ஸ்ரீ மஹாஸுதர்சனருள் உறையும் பரமாத்மா ப்ரீதியடையட்டும்.",
      },
    },
    'lakshmi-homa': {
      summary: "லக்ஷ்மீ ஹோமம் தொடக்கம் முதல் முடிவு வரை: ஸங்கல்பம், அக்னிமுகம், லக்ஷ்மியின் (மாத்வ: லக்ஷ்மீநாராயணரின்) தியானமும் ஆவாஹனமும், ரிக்வேத புருஷஸூக்தத்தின் பதினாறு மந்திரங்களாலும் ஸ்வாஹாவுடன் ஹோமம் — ஒவ்வொன்றும் பதினாறு முறை (மாத்வ), ஶ்ரீஸூக்தத்தின் பதினைந்து ருக்குகளாலும் ஸ்வாஹாவுடன் ஹோமம் (மாத்வரில் ஒவ்வொன்றும் பதினைந்து முறை), உத்தராங்கம், உத்தரபூஜை, ஸமர்ப்பணம்.",
      verses: {
        '0.0': "செல்வத்தை விரும்புபவன் தூய்மையும் அடக்கமும் உடையவனாகி, தினமும் அக்னியில் நெய் அர்ப்பணித்து, பதினைந்து ருக்குகள் கொண்ட இந்த ஸூக்தத்தை இடையறாது ஜபிக்க வேண்டும்.",
        '1.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள் உறைபவனுமான ஹரிணீபதி ஶ்ரீபரசுராமனின் தூண்டுதலால், அவன் ப்ரீதிக்காக, ஶ்ரீலக்ஷ்மீநாராயணரின் ப்ரீதிக்காக புருஷஸூக்தம், ஶ்ரீஸூக்தம் ஆகியவற்றால் ஸுக்ருத ஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக ஸ்தண்டில ஸம்ஸ்காரம் செய்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '2.0': "நான் சேர்த்த எல்லாப் பாவங்களின் அழிவின் மூலம் பரமேஶ்வரனின் ப்ரீதிக்காக, ஶ்ரீமஹாலக்ஷ்மியின் அருள் கிட்டுவதற்காக ஶ்ரீஸூக்தத்தால் ஶ்ரீஸூக்த ஹோமம் செய்வேன்; அதன் அங்கமாக ஸ்தண்டிலத்தில் கோடுகள் வரைந்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '3.0': "அக்னிமுகம், ஆஜ்யபாகம் வரை. (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '4.0': "தாமரையில் அமர்ந்தவளும், அகன்ற இடுப்பும், தாமரை இதழ் போல் நீண்ட கண்களும், ஆழ்ந்த நாபியும், மார்பின் நிறைவால் வளைந்த உடலும், வெண்ணிற மேலாடையும் உடையவளும் (அடுத்த ஸ்லோகத்தில் தொடர்கிறது).",
        '4.1': "மணி பதித்த பொற்குடங்களிலிருந்து திக்கஜங்களால் நீராட்டப்பட்டவளும், தாமரை ஏந்தியவளும், எல்லா மங்கலமும் நிறைந்தவளுமான அந்த லக்ஷ்மி என் இல்லத்தில் என்றும் உறையட்டும்.",
        '4.2': "ஓம் பூர்புவஃ ஸ்வஃ: ஶ்ரீலக்ஷ்மீநாராயணரை இந்தக் கலசத்தில் ஆவாஹனம் செய்கிறேன், ஸ்தாபிக்கிறேன், பூஜிக்கிறேன்.",
        '4.3': "ஓம் பூர்புவஃ ஸ்வஃ: ஶ்ரீமஹாலக்ஷ்மியை இந்தக் கலசத்தில் ஆவாஹனம் செய்கிறேன், ஸ்தாபிக்கிறேன், பூஜிக்கிறேன்.",
        '4.4': "மகாலக்ஷ்மியை அறிகிறோம்; விஷ்ணுபத்னியைத் தியானிக்கிறோம். அந்த லக்ஷ்மி எங்களைத் தூண்டி வழிநடத்தட்டும்.",
        '5.0': "பரமபுருஷன் ஆயிரம் தலைகளும் ஆயிரம் கண்களும் ஆயிரம் பாதங்களும் உடையவன். பூமியை எப்புறமும் நிறைத்து, அதற்குப் பத்து விரல் அளவு — அதாவது எல்லா அளவுக்கும் — அப்பால் நிற்கிறான். (ரிக்வேதம் 10.90.1) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.1': "இவை அனைத்தும் புருஷனே: இருந்தவையும் இனி இருக்கப்போவனவும். அவனே அமரத்துவத்தின் தலைவன்; உணவால் வளர்வன அனைத்துக்கும் மேலாக உயர்ந்தவன். (ரிக்வேதம் 10.90.2) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.2': "இதுவே அவன் மகிமை, ஆயினும் புருஷன் அதனினும் பெரியவன். எல்லா உயிர்களும் அவனுடைய ஒரு கால் பங்கே; அவனுடைய முக்கால் பங்கு மேலான வானில் அமரத்துவமாக உள்ளது. (ரிக்வேதம் 10.90.3) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.3': "முக்கால் பங்கால் புருஷன் மேலே உயர்ந்தான்; ஒரு கால் பங்கு உலகமாக மீண்டும் மீண்டும் இங்கே தோன்றுகிறது. அதிலிருந்து உண்பன, உண்ணாதன அனைத்திலும் எங்கும் பரவினான். (ரிக்வேதம் 10.90.4) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.4': "அவனிடமிருந்து விராட் எனும் பிரபஞ்ச வடிவம் பிறந்தது; விராட்டுக்குள் புருஷன் உறைந்தான். வெளிப்பட்டதும் அதற்கு அப்பாலும் விரிந்து, பின் பூமியையும் உயிர்களின் உடல்களையும் தோற்றுவித்தான். (ரிக்வேதம் 10.90.5) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.5': "புருஷனையே ஹவிஸாகக் கொண்டு தேவர்கள் யாகம் செய்தபோது, வசந்தம் அதன் நெய், கோடை அதன் விறகு, சரத்காலம் அதன் ஹவிஸ். (ரிக்வேதம் 10.90.6) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.6': "அனைத்துக்கும் முன் பிறந்த அப்புருஷனை யாகமாகவே தர்ப்பையின் மீது பிரோக்ஷணம் செய்தனர். அவனாலேயே தேவர்களும் ஸாத்யர்களும் ரிஷிகளும் வழிபட்டனர். (ரிக்வேதம் 10.90.7) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.7': "அனைத்தும் அர்ப்பணிக்கப்பட்ட அந்த யாகத்திலிருந்து தயிர் கலந்த நெய் சேர்க்கப்பட்டது. அதிலிருந்து வான்வெளி உயிர்களையும், காட்டு விலங்குகளையும், ஊர் விலங்குகளையும் படைத்தான். (ரிக்வேதம் 10.90.8) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.8': "அனைத்தும் அர்ப்பணிக்கப்பட்ட அந்த யாகத்திலிருந்து ரிக் மந்திரங்களும் ஸாம கானங்களும் பிறந்தன; அதிலிருந்து சந்தஸ்கள் பிறந்தன; அதிலிருந்து யஜுஸ் தோன்றியது. (ரிக்வேதம் 10.90.9) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.9': "அதிலிருந்து குதிரைகளும் இரு தாடைகளிலும் பற்களுடைய எல்லா விலங்குகளும் பிறந்தன. அதிலிருந்து பசுக்கள் பிறந்தன; அதிலிருந்து ஆடுகளும் செம்மறிகளும் பிறந்தன. (ரிக்வேதம் 10.90.10) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.10': "புருஷனைக் கண்டுணர்ந்தபோது அவனை எத்தனை விதமாகக் கற்பித்தனர்? அவன் வாய் எது, கரங்கள் எவை, தொடைகளும் பாதங்களும் எவை எனப்படுகின்றன? (ரிக்வேதம் 10.90.11) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.11': "அந்தணன் அவன் வாயானான், க்ஷத்ரியன் அவன் கரங்களாக்கப்பட்டான், வைசியன் அவன் தொடைகளானான், அவன் பாதங்களிலிருந்து சூத்திரன் பிறந்தான். இவ்வாறு ஒரே உடலின் அங்கங்கள் போல் சமூகத்தின் எல்லாப் பிரிவுகளும் ஒரே இறைவனிடமிருந்து தோன்றுகின்றன. (ரிக்வேதம் 10.90.12) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.12': "அவன் மனத்திலிருந்து சந்திரன் பிறந்தான், கண்களிலிருந்து சூரியன்; வாயிலிருந்து இந்திரனும் அக்னியும், மூச்சிலிருந்து வாயுவும் தோன்றினர். (ரிக்வேதம் 10.90.13) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.13': "நாபியிலிருந்து அந்தரிக்ஷம் தோன்றியது, தலையிலிருந்து வானம் உருவானது; பாதங்களிலிருந்து பூமி, காதுகளிலிருந்து திசைகள். இவ்வாறு உலகங்கள் அமைக்கப்பட்டன. (ரிக்வேதம் 10.90.14) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.14': "தேவர்கள் அந்த யாகத்தை விரித்துப் புருஷனையே பலியாகக் கட்டியபோது, அதற்கு ஏழு பரிதிகளும் மூவேழு ஸமித்துகளும் இருந்தன. (ரிக்வேதம் 10.90.15) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '5.15': "யாகமே வடிவான இறைவனைத் தேவர்கள் யாகத்தால் வழிபட்டனர்; இவையே தர்மங்களில் முதலானவை. அம்மகான்கள் பழைய ஸாத்யர்களும் தேவர்களும் உறையும் மேலான வானை அடைகின்றனர். (ரிக்வேதம் 10.90.16) ஸ்வாஹா; இது புருஷனுக்கு, என்னுடையதல்ல.",
        '6.0': "ஜாதவேதஸே (அக்னியே), பொன்னிறமுடையவளும், துயர் போக்குபவளும், பொன் வெள்ளி மாலைகள் அணிந்தவளும், சந்திரன் போல் இனியவளும், பொன் போல் ஒளிர்பவளுமான லக்ஷ்மியை என்னிடம் கொணர்வாய். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.1': "ஜாதவேதஸே, எவளுடைய அருளால் பொன்னும் பசுக்களும் குதிரைகளும் சுற்றம் சூழ்ந்த மக்களும் பெறுவேனோ, ஒருபோதும் நீங்காத அந்த லக்ஷ்மியை என்னிடம் கொணர்வாய். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.2': "முன்னே குதிரைகளும் நடுவே தேர்களும் கொண்ட ஊர்வலமுடையவளும், யானைகளின் பிளிறலால் வருகை அறிவிக்கப்படுபவளுமான ஸ்ரீ தேவியை அழைக்கிறேன். ஸ்ரீ தேவி எனக்கு அருள்புரியட்டும். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.3': "ஆனந்தமே வடிவானவளும், மென்மையாகப் புன்னகைப்பவளும், பொன்னால் சூழப்பட்டவளும், கருணையால் கனிந்தவளும், ஒளிர்பவளும், என்றும் திருப்தியுடன் பக்தர்களைத் திருப்திப்படுத்துபவளும், தாமரையில் அமர்ந்து தாமரை நிறமுடையவளுமான ஸ்ரீயை இங்கே அழைக்கிறேன். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.4': "சந்திரன் போல் அழகியவளும், ஒளிமிக்கவளும், புகழால் சுடர்விடுபவளும், உலகில் தேவர்களால் போற்றப்படுபவளும், வள்ளலும், தாமரை ஏந்தியவளுமான ஸ்ரீயைச் சரணடைகிறேன். அன்னையே, உன்னைத் தேர்ந்தெடுக்கிறேன்; என் துரதிர்ஷ்டம் அழியட்டும். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.5': "சூரியன் போல் ஒளிரும் தேவியே, உன் தவத்திலிருந்து மரங்களின் அரசனான வில்வம் பிறந்தது. உன் ஆற்றலால் அதன் கனிகள் உள்ளே அறியாமைத் தடைகளையும் வெளியே துரதிர்ஷ்டத்தையும் விரட்டட்டும். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.6': "தேவர்களின் நண்பன் (குபேரன்) கீர்த்தியுடனும் (புகழுடனும்) விலைமதிப்பற்ற மணிகளுடனும் என்னிடம் வரட்டும். நான் இந்நாட்டில் பிறந்தவன்; அவன் எனக்குப் புகழும் செல்வமும் அருளட்டும். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.7': "பசி, தாகம், அசுத்தம் ஆகியவற்றைக் கொணரும் மூத்த சகோதரி அலக்ஷ்மியை விரட்டுகிறேன். தேவியே, என் இல்லத்திலிருந்து எல்லாக் குறைவையும் வளமின்மையையும் வெளியேற்று. ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.8': "நறுமணத்தால் அறியப்படுபவளும், வெல்ல முடியாதவளும், என்றும் நிறைவானவளும், பசுக்கூட்டங்கள் நிறைந்தவளும், எல்லா உயிர்களுக்கும் அரசியுமான ஸ்ரீயை இங்கே அழைக்கிறேன். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.9': "மனத்தின் விருப்பங்களையும் சங்கல்பங்களையும், வாக்கில் சத்தியத்தையும் அடைவோமாக. செழிக்கும் பசுக்களாகவும், நிறைந்த உணவாகவும், நற்பெயராகவும் ஸ்ரீ என்னுள் உறையட்டும். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.10': "கர்தமரே, உம்மால் லக்ஷ்மி மக்கட்பேறு பெற்றாள்; கர்தமரே, என்னுடன் உறைவீர். தாமரை மாலை அணிந்த அன்னை ஸ்ரீயை என் குலத்தில் உறையச் செய்வீர். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.11': "நீர்கள் மென்மையான போஷிக்கும் வளத்தைத் தோற்றுவிக்கட்டும். சிக்லீதரே, என் இல்லத்தில் உறைவீர்; திவ்ய அன்னை ஸ்ரீயை என் குலத்தில் உறையச் செய்வீர். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.12': "ஜாதவேதஸே, கருணையால் கனிந்தவளும், தாமரைக் குளத்தில் உறைபவளும், போஷணை அருள்பவளும், பொன்மஞ்சள் நிறமுடையவளும், தாமரை மாலை அணிந்தவளும், சந்திரன் போல் இனியவளும், பொன் போல் ஒளிர்பவளுமான லக்ஷ்மியை என்னிடம் கொணர்வாய். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.13': "ஜாதவேதஸே, கருணையால் கனிந்தவளும், பக்தர்களுக்கு ஊன்றுகோல் போன்ற ஆதரவும், அழகிய வடிவினளும், பொன்மாலை அணிந்தவளும், சூரியன் போல் ஒளிமிக்கவளும், பொன் போல் ஒளிர்பவளுமான லக்ஷ்மியை என்னிடம் கொணர்வாய். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '6.14': "ஜாதவேதஸே, எவளுடைய அருளால் மிகுதியான பொன்னும், பசுக்களும், பணியாட்களும், குதிரைகளும், சுற்றம் சூழ்ந்த மக்களும் பெறுவேனோ, ஒருபோதும் நீங்காத அந்த லக்ஷ்மியை என்னிடம் கொணர்வாய். ஸ்வாஹா; இது ஶ்ரீதேவிக்கு, என்னுடையதல்ல.",
        '7.0': "ஸ்விஷ்டக்ருத்தில் தொடங்கும் உத்தராங்கம். (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '8.0': "ஓம், நாராயணனுக்கு நமஸ்காரம்; மங்கள நீராஜனத்தை (ஆரத்தியை) அர்ப்பிக்கிறேன்.",
        '8.1': "அங்கே ஸூர்யனோ சந்த்ர–நட்சத்திரங்களோ இந்த மின்னல்களோ ஒளிர்வதில்லை — இந்த நெருப்பு எப்படி? ஒளிரும் அவனைப் பின்பற்றியே எல்லாம் ஒளிர்கிறது; அவன் ஒளியாலேயே இவை அனைத்தும் விளங்குகின்றன. (கடோபநிஷத் 2.2.15; கற்பூர ஆரத்தியின்போது.)",
        '8.2': "கற்பூர நீராஜனம் காட்டுகிறேன்; நீராஜனத்திற்குப் பின் ஆசமனத்திற்கு நீர் அர்ப்பிக்கிறேன்.",
        '9.0': "தன் வலிமையால் வெல்லும் அரசர்க்கரசனான வைச்ரவணனை வணங்குகிறோம். விருப்பங்களின் தலைவனான அவன் ஏங்கும் எனக்கு என் விருப்பங்களை அருளட்டும். மகாராஜனான குபேர வைச்ரவணனுக்கு நமஸ்காரம்.",
        '9.1': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '9.2': "நீரின் மலரை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். சந்திரனே நீரின் மலர்; இதை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். நீரின் ஆதாரத்தை அறிபவன் உறுதியான ஆதாரத்தைப் பெறுகிறான்.",
        '9.3': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '10.0': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '10.1': "நான் செய்பவன் அல்லன், ஹரியே செய்பவன்; எல்லாச் செயலும் அவனுடைய பூஜையே. ஆயினும் நான் செய்த இந்தப் பூஜை அவன் அருளால்தான் நடந்தது, வேறு விதமாக அல்ல.",
        '10.2': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '11.0': "எவனை நினைப்பதாலும் எவன் நாமத்தைச் சொல்வதாலும் தவம், பூஜை, கர்மங்களில் உள்ள குறை உடனே நிறைவடைகிறதோ அந்த அச்யுதனை வணங்குகிறேன்.",
        '11.1': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '11.2': "இந்த ஸுக்ருத ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள் உறைபவனுமான ஶ்ரீலக்ஷ்மீநாராயணன் மகிழ்வானாக. ஶ்ரீக்ருஷ்ணார்ப்பணமஸ்து.",
        '11.3': "தேவாசுரர்களால் வணங்கப்படும் தேவ ஸ்ரேஷ்டரே, செல்லுங்கள்; ஓ ஹுதாசனனே, பிரம்மாதி தேவர்கள் இருக்கும் இடத்திற்குச் செல்.",
        '11.4': "உன்னை அழைக்கும் முறையோ, விடைகொடுக்கும் முறையோ, வழிபடும் முறையோ நான் அறியேன்; பரமேச்வரா, பொறுத்தருள்.",
        '11.5': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '11.6': "இந்த ஶ்ரீஸூக்த ஹோம கர்மத்தால் ஶ்ரீமஹாலக்ஷ்மி மகிழ்வாளாக. ஓம் தத்ஸத், பிரம்மத்துக்கு அர்ப்பணமாகட்டும்.",
      },
    },
    'ayushya-homa': {
      summary: "ஜன்மநக்ஷத்திரம் அல்லது பிறந்தநாளில் ஆயுளுக்காகச் செய்யும் கர்மம் தொடக்கம் முதல் முடிவு வரை: நாள், ஸங்கல்பம், அக்னிமுகம், தன்வந்தரி தியானம், பிரதான ஆஹுதிகள் (மாத்வ: பால்–நெய்யில் தோய்த்த நான்கு அருகுகளால் தன்வந்தரிக்கு ஹோமமும் த்ர்யம்பக மந்திரத்தால் தூர்வா ஹோமமும்; ஸ்மார்த்த: ஆயுஷ்ய ஸூக்தத்தின் எட்டு மந்திரங்களால் நெய் ஹோமமும் த்ர்யம்பக மந்திரமும்), உத்தராங்கம், உத்தரபூஜை, ஸமர்ப்பணம்; பிறகு வீட்டில் யாரும் செய்யக்கூடிய சிறிய வர்தாபன பூஜை (அக்ஷதைக் குவியல்களில் பதினாறு தேவதைகளின் ஆவாஹனம், பிரார்த்தனை, எள்–வெல்லம் கலந்த பால்) மற்றும் அன்று தவிர்க்க வேண்டியவை.",
      verses: {
        '0.0': "ஆயுள் வளர தினமும் அல்லது ஜன்ம நட்சத்திரத்தில், பால்–நெய்யில் தோய்த்த நான்கு நான்கு அருகம்புல்லால் ஹோமம் செய்யப்படுகிறது. (தந்த்ரஸாரஸங்க்ரஹம் 4.102)",
        '1.0': "யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள் உறைபவனுமான ஹரிணீபதி ஶ்ரீபரசுராமனின் தூண்டுதலால், அவன் ப்ரீதிக்காக: என் ஆயுள் வளர்வதற்காகவும் ஶ்ரீதன்வந்தரியின் ப்ரீதிக்காகவும் தூர்வாயுஷ்ய ஹோமம் என்ற கர்மத்தைச் செய்வேன்; அதன் அங்கமாக ஸ்தண்டில ஸம்ஸ்காரம் செய்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '2.0': "நான் சேர்த்த எல்லாப் பாவங்களின் அழிவின் மூலம் பரமேஶ்வரனின் ப்ரீதிக்காக, என் ஆயுளும் ஆரோக்கியமும் வளர்வதற்காக ஆயுஷ்ய ஹோமம் செய்வேன்; அதன் அங்கமாக ஸ்தண்டிலத்தில் கோடுகள் வரைந்து அக்னிப்ரதிஷ்டை செய்வேன்.",
        '3.0': "அக்னிமுகம், ஆஜ்யபாகம் வரை. (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '4.0': "சந்திரத் தொகுதி போன்ற ஒளியுடைய, அமுதமயமான பெருங்கிரணங்களால் உலகங்களை வாழவைக்கும், எல்லையற்ற இன்பவடிவான, ஞானமுத்திரையும் அமுதக் கலசமும் ஏந்திய, சந்திரமண்டலத்தில் உள்ள பரமேசனைத் தன்னுள் நினைக்க வேண்டும். (தந்த்ரஸாரஸங்க்ரஹம் 4.94)",
        '4.1': "ஓம் பூர்புவஃ ஸ்வஃ: ஶ்ரீதன்வந்தரியை இந்தக் கலசத்தில் ஆவாஹனம் செய்கிறேன், ஸ்தாபிக்கிறேன், பூஜிக்கிறேன்.",
        '5.0': "தேன், நெய், தயிர் கலந்த அருகம்புல்லை ம்ருத்யுஞ்ஜய மந்திரத்தால் ஆயிரம் முறை அல்லது இருபத்தெட்டு ஆஹுதிகள் ஹோமம் செய்ய வேண்டும். (ப்ரயோகபாரிஜாதம், ஹோம–ஹவனத்தில் மேற்கோள்)",
        '5.1': "ஓம் பூர்புவஃ ஸ்வஃ. மூன்று கண்களுடைய, நறுமணமுள்ள, ஊட்டம் பெருக்கும் தேவனை வழிபடுகிறோம்; பழுத்த வெள்ளரி காம்பிலிருந்து விடுபடுவதுபோல் நான் மரணத்திலிருந்து விடுபடுவேனாக, அமிர்தத்திலிருந்து அல்ல. ஸ்வர்புவர்பூஃ ஓம். ஸ்வாஹா; இது ம்ருத்யுஞ்ஜய ருத்ரனுள், பாரதீரமண முக்யப்ராணனுள் உறையும் ஶ்ரீஸங்கர்ஷணனுக்கு, என்னுடையதல்ல. (ரிக்வேதம் 7.59.12, ஹோம–ஹவனம் சொல்வதுபோல் ப்ரணவ வ்யாஹ்ருதிகளால் ஸம்புடிதம்)",
        '6.0': "பிராணன்களுடன் பிரம்மாவின் தலையைக் கிள்ளி எடுத்தவர், தோலை ஆடையாக அணிந்தவர், பினாகம் என்ற வில்லை உடையவர் ஆன ஈசான தேவன் எங்களுக்கு நீண்ட ஆயுளைத் தரட்டும். அவருக்கு நான் நெய் ஹவிஸால் ஆஹுதி அளிக்கிறேன். ஸ்வாஹா.",
        '6.1': "நீர்ப்பரப்பின் நடுவிலிருந்து ஒளிர்ந்து, மின்னி, வெப்பமே காந்தியாக உதித்த அந்த தேவன் மரணத்தின் பயங்கரமான பாசங்களை அகற்றி, எங்கள் நீண்ட ஆயுளுக்காக இங்கே இந்த நெய்யை ஏற்கட்டும். ஸ்வாஹா.",
        '6.2': "புனித அக்னி ரிஷிகளின் பத்தினிகளில் கருவாக வைத்த, பல வடிவங்கள் கொண்ட, வெற்றி பெறும், பொன் தண்டம் ஏந்திய, வழிபடத் தகுந்த ஒளிமிக்கவரை நீண்ட ஆயுளுக்காக நெய்யால் வளர்க்கிறோம். (இது ஸ்கந்தனைப் பற்றியது எனக் கொள்வர்.) ஸ்வாஹா.",
        '6.3': "ஸ்ரீ, லக்ஷ்மி, ஔபலா, அம்பிகா, கோ, ஷஷ்டீ, இந்திரசேனா என்று அழைக்கப்படுபவள், வித்யா ஸ்வரூபிணி, பிரம்மனிடமிருந்து தோன்றியவள், அழகிய வடிவம் உடையவள்: அவளை நீண்ட ஆயுளுக்காக இங்கே நெய்யால் திருப்தி செய்கிறோம். ஸ்வாஹா.",
        '6.4': "எல்லா உயிர்களுக்கும் மூலமாகி, ஒரே மூலத்திலிருந்து தோன்றி, ஆயிரக்கணக்கில் உள்ள, எல்லா வடிவங்களும் பலவித வடிவங்களும் கொண்ட தக்ஷனின் புதல்வியர் தம் மக்கள், கணவர்கள், தோழியருடன் எங்கள் நீண்ட ஆயுளுக்காக இந்த நெய்யை ஏற்கட்டும். ஸ்வாஹா.",
        '6.5': "பல வடிவங்கள் கொண்ட பழமையான தெய்வீக கணங்கள், ஆயுளை வெட்டக்கூடியவை, எங்கள் வீரர்களை நசுக்கக்கூடியவை: அவர்களுக்கு நான் பல வகையாக நெய் அளிக்கிறேன். எங்கள் சந்ததியையும் எங்கள் வீரர்களையும் துன்புறுத்தாதீர்கள். ஸ்வாஹா.",
        '6.6': "ஆதியில் ஒருவராக இருந்து இவையெல்லாமாக ஆனவர்; யாரிடமிருந்து உலகைக் காப்பவர் தோன்றினாரோ, பிரளயத்தில் உலகம் யாரிடம் ஒடுங்குமோ, அந்த தேவன் எங்கள் நீண்ட ஆயுளுக்காக இங்கே எங்கள் நெய் ஹவிஸை ஏற்கட்டும். ஸ்வாஹா.",
        '6.7': "வஸுக்கள், ருத்ரர்கள், ஆதித்யர்கள், மருத்துகள், ஸாத்யர்கள், ருபுக்கள், யக்ஷர்கள், கந்தர்வர்கள், பித்ருக்கள், விஸ்வேதேவர்கள், பிருகுக்கள், ஸர்ப்பங்கள், அங்கிரஸர்கள் ஆகிய எல்லோருக்கும் நெய்யை அளித்து, நீண்ட ஆயுளைப் பெற்று நாங்கள் அவர்களை எப்போதும் வழிபடுவோம். ஸ்வாஹா.",
        '6.8': "விஷ்ணுவே, எங்களுக்கு மிக அருகில் இருப்பவரே, வெற்றியாளரே, எங்களுக்கு அடைக்கலம் தா. தேன் பொழியும் உன் தாரைகள் என்றும் வற்றாத ஊற்றைப் பெருக்குகின்றன. ஓம் சாந்தி: சாந்தி: சாந்தி:.",
        '6.9': "மூன்று கண்களுடைய, நறுமணம் கொண்ட, புஷ்டியை வளர்க்கும் தேவனை வழிபடுகிறோம்; பழுத்த வெள்ளரிக்காய் காம்பிலிருந்து விடுபடுவது போல நான் ம்ருத்யுவிலிருந்து விடுபடுவேனாக, அமரத்துவத்திலிருந்து அல்ல, ஸ்வாஹா. இது ருத்ரனுக்கு, என்னுடையதன்று. (ரிக்வேதம் 7.59.12)",
        '7.0': "ஸ்விஷ்டக்ருத்தில் தொடங்கும் உத்தராங்கம். (தலைப்பு: இந்தப் படிகளை \"ஹோமவிதி — பூர்வாங்கம் உத்தராங்கம்\" பாடத்திலிருந்து செய்யவும்.)",
        '8.0': "ஓம், நாராயணனுக்கு நமஸ்காரம்; மங்கள நீராஜனத்தை (ஆரத்தியை) அர்ப்பிக்கிறேன்.",
        '8.1': "அங்கே ஸூர்யனோ சந்த்ர–நட்சத்திரங்களோ இந்த மின்னல்களோ ஒளிர்வதில்லை — இந்த நெருப்பு எப்படி? ஒளிரும் அவனைப் பின்பற்றியே எல்லாம் ஒளிர்கிறது; அவன் ஒளியாலேயே இவை அனைத்தும் விளங்குகின்றன. (கடோபநிஷத் 2.2.15; கற்பூர ஆரத்தியின்போது.)",
        '8.2': "கற்பூர நீராஜனம் காட்டுகிறேன்; நீராஜனத்திற்குப் பின் ஆசமனத்திற்கு நீர் அர்ப்பிக்கிறேன்.",
        '9.0': "தன் வலிமையால் வெல்லும் அரசர்க்கரசனான வைச்ரவணனை வணங்குகிறோம். விருப்பங்களின் தலைவனான அவன் ஏங்கும் எனக்கு என் விருப்பங்களை அருளட்டும். மகாராஜனான குபேர வைச்ரவணனுக்கு நமஸ்காரம்.",
        '9.1': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '9.2': "நீரின் மலரை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். சந்திரனே நீரின் மலர்; இதை அறிபவன் மலர்களும் மக்களும் பசுக்களும் நிறைந்தவனாகிறான். நீரின் ஆதாரத்தை அறிபவன் உறுதியான ஆதாரத்தைப் பெறுகிறான்.",
        '9.3': "மந்த்ரபுஷ்பத்தை — வேத மந்த்ரங்களுடன் மலர்களை — அர்ப்பிக்கிறேன்.",
        '10.0': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '10.1': "நான் செய்பவன் அல்லன், ஹரியே செய்பவன்; எல்லாச் செயலும் அவனுடைய பூஜையே. ஆயினும் நான் செய்த இந்தப் பூஜை அவன் அருளால்தான் நடந்தது, வேறு விதமாக அல்ல.",
        '10.2': "முற்பிறவிகளில் செய்தவை உட்பட எந்தப் பாவங்கள் உண்டோ, அவை பிரதக்ஷிணத்தின் ஒவ்வோர் அடியிலும் அழிகின்றன.",
        '11.0': "எவனை நினைப்பதாலும் எவன் நாமத்தைச் சொல்வதாலும் தவம், பூஜை, கர்மங்களில் உள்ள குறை உடனே நிறைவடைகிறதோ அந்த அச்யுதனை வணங்குகிறேன்.",
        '11.1': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '11.2': "இந்த ஆயுஷ்ய ஹோமத்தால் யஜ்ஞபுருஷனின் அந்தர்யாமியும், பாரதீரமண முக்யப்ராணனுள் உறைபவனுமான ஶ்ரீதன்வந்தரி மகிழ்வானாக. ஶ்ரீக்ருஷ்ணார்ப்பணமஸ்து.",
        '11.3': "தேவாசுரர்களால் வணங்கப்படும் தேவ ஸ்ரேஷ்டரே, செல்லுங்கள்; ஓ ஹுதாசனனே, பிரம்மாதி தேவர்கள் இருக்கும் இடத்திற்குச் செல்.",
        '11.4': "உன்னை அழைக்கும் முறையோ, விடைகொடுக்கும் முறையோ, வழிபடும் முறையோ நான் அறியேன்; பரமேச்வரா, பொறுத்தருள்.",
        '11.5': "உடலாலும் வாக்காலும் மனத்தாலும் புலன்களாலும், புத்தியாலும் உள்ளத்தாலும், இயல்பின் தூண்டுதலாலும் நான் செய்வன அனைத்தையும் பரம்பொருளான நாராயணனுக்கே சமர்ப்பிக்கிறேன்.",
        '11.6': "இந்த ஆயுஷ்ய ஹோம கர்மத்தால் பரமேஶ்வரன் மகிழ்வானாக. ஓம் தத்ஸத், பிரம்மத்துக்கு அர்ப்பணமாகட்டும்.",
        '12.0': "ஆயுள் வளர்வதற்காக வர்ஷவ்ருத்தி கர்மம் செய்வேன். குருக்களுக்கு நமஸ்காரம்: இந்த வ்ருத்தி கர்மத்துக்கு அனுமதி தாருங்கள். கம் கணபதயே நமஃ: தடையின்றிச் செய்வாயாக. (வர்தாபன ஸங்கல்பம், ஹோம–ஹவனம்)",
        '12.1': "வர்ஷவ்ருத்தியின் பதினாறு தேவதைகளுக்கும் ஒவ்வொருவருக்கும் நமஸ்காரமும் ஆவாஹனமும்: குலதேவதை, ஜன்மநக்ஷத்திர தேவதை (பெயரால்; குறிப்பைப் பார்க்கவும்), பித்ருக்கள், பிரஜாபதி, வேதவ்யாஸர், பரசுராமர், ஹனுமான், அஶ்வத்தாமா, பலி, விபீஷணன், க்ருபர், மார்க்கண்டேயர், ஷஷ்டீதேவி, ப்ரஹ்லாதன், பானு (சூரியன்), விக்னேசர். பிறகு: குலதேவதை முதலிய பதினாறு வர்ஷவ்ருத்தி தேவதைகளை இந்த அக்ஷதைக் குவியல்களில் ஆவாஹனம் செய்கிறேன். (ஹோம–ஹவனம்)",
        '12.2': "ஓ மகாபாகரான மார்க்கண்டேயரே, ஏழு கல்பங்களின் முடிவு வரை வாழ்ந்தவரே, முனிசிரேஷ்டரே, எனக்கு ஆயுள், ஆரோக்கியம், ஐஸ்வர்யம் தாருங்கள்.",
        '12.3': "ஓ விநாயகா, எனக்கு ஆயுளையும் புகழையும் செல்வத்தையும் தா; ஓ கணநாயகா, மகன்களையும் பேரன்களையும் கொள்ளுப்பேரன்களையும் தா.",
        '12.4': "தைத்யேந்திர குலத்தில் பிறந்த, தானம்–யஜ்ஞம் செய்வதில் ஈடுபட்ட ஓ பலியே, உன்னைச் சரணடைகிறேன்; எனக்கு நீண்ட ஆயுளைத் தா.",
        '12.5': "வஸிஷ்ட குலத்தில் பிறந்த, வேத சாஸ்திர விசாரதரான, நாராயணாம்சரான வேதவ்யாஸரே, உங்களுக்கு நமஸ்காரம்.",
        '12.6': "ஓ அஞ்சனை மைந்தா, மகாபாகா, வானரத் தலைவா, அமைச்சருள் சிறந்தவா, ராமப்ரியா, உனக்கு நமஸ்காரம்; ஹனுமானே, எப்போதும் என்னைக் காத்தருள்.",
        '12.7': "ராமனின் பாதத் தாமரைகளை வணங்கும் விபீஷணா, உனக்கு நமஸ்காரம்; ஓ புலஸ்திய வம்சத்தின் ஆனந்தமே, எனக்கு ஆயுள், ஆரோக்கியம், ஐஸ்வர்யம் தா.",
        '12.8': "ஓ ரேணுகையின் மகனே, மகாவீர்யனே, கார்த்தவீர்ய குலாந்தகனே, ஜாமதக்ன்ய ராமா, எனக்கு ஆயுளைத் தா; உனக்கு நமஸ்காரம்.",
        '12.9': "மூன்று உலகங்களிலும் உள்ள அசையும் அசையாத எல்லா உயிர்களும் பிரம்மா–விஷ்ணு–சிவனுடன் சேர்ந்து என்னைக் காக்கட்டும்.",
        '12.10': "மார்க்கண்டேயரிடமிருந்து வரம் பெற்று, ஆயுள் வளர எள்–வெல்லம் கலந்த அரை அஞ்சலி பாலைப் பருகுகிறேன். (பிரதக்ஷிண–நமஸ்காரங்களுக்குப் பின் பால் பருகும்போது.)",
        '12.11': "இந்த வருஷவ்ருத்தி பூஜையால் மத்வபதியான பகவான் கோபாலகிருஷ்ணன் மகிழட்டும். ஸ்ரீகிருஷ்ணார்ப்பணமஸ்து.",
        '13.0': "பிறந்தநாளில் நகம்–முடி வெட்டுதல், மைதுனம், பயணம், மாமிசம் உண்ணுதல், சண்டை, ஹிம்சை ஆகியவற்றைத் தவிர்க்க வேண்டும். (தர்மஸிந்து)",
      },
    },
  },
};
